// ── HELPER: texto de historia según idioma ────────────────────
String sorpresaStopText(String stopId, String lang) {
  final map = kSorpresaTexts[stopId];
  if (map == null) return '';
  switch (lang) {
    case 'en': return map['EN'] ?? map['ES'] ?? '';
    case 'de': return map['DE'] ?? map['ES'] ?? '';
    case 'it': return map['IT'] ?? map['ES'] ?? '';
    default:   return map['ES'] ?? '';
  }
}


const kSorpresaTexts = <String, Map<String, String>>{
  'lena_01': {
    'ES': 'Berlín, 1925. Me llamo Lena Hoffmann. Tengo veintidós años y esta ciudad es mía.\n\nEstoy parada frente a la cúpula dorada de la Nueva Sinagoga. La conozco de toda la vida — crecí tres calles al norte, en el Scheunenviertel, y de niña me parecía lo más hermoso que existía. Sigue pareciéndomelo.\n\nLa inauguraron en 1866, cuando mi abuela era niña. Ocho mil personas dentro, dicen, incluyendo al canciller Bismarck — que no era conocido precisamente por su simpatía hacia nadie. Tiene capacidad para tres mil fieles, un órgano de cuatro mil trescientos tubos, y una cúpula de hierro y zinc recubierta de azulejos dorados que se ven desde los tejados de medio Berlín. El arquitecto Eduard Knoblauch la diseñó mezclando el estilo neomudéjar con el románico renano — una catedral que no es catedral, levantada por una comunidad que llevó siglos pidiendo permiso para existir con dignidad.\n\nMis padres llegaron de Lodz con dos maletas y la certeza de que Berlín los dejaría ser lo que eran. En los años veinte, esa certeza todavía tiene sentido.\n\nAprendí a cantar escuchando por las ventanas abiertas de la sinagoga los viernes por la noche. Hay ciertos sonidos que no piden permiso para entrar.\n\nA los dieciséis años supe que quería cantar en un escenario. Mi madre dijo: eso no es un trabajo. Mi padre dijo: claro que es un trabajo, es el trabajo más difícil que existe.\n\nMi padre tenía razón. Como siempre.\n\nCamina hacia el sur siguiendo el río. El Monbijoupark está a tres minutos.',
    'EN': 'Berlin, 1925. My name is Lena Hoffmann. I am twenty-two years old and this city is mine.\n\nI am standing in front of the golden dome of the New Synagogue. I have known it all my life — I grew up three streets to the north, in the Scheunenviertel, and as a child it seemed to me the most beautiful thing in existence. It still does.\n\nThey inaugurated it in 1866, when my grandmother was a girl. Eight thousand people inside, they say, including Chancellor Bismarck — not a man known for his warmth toward anyone. It holds three thousand worshippers, an organ with four thousand three hundred pipes, and a dome of iron and zinc covered in golden tiles visible from the rooftops of half of Berlin. The architect Eduard Knoblauch designed it blending the neo-Moorish style with Rhenish Romanesque — a cathedral that is not a cathedral, built by a community that spent centuries asking permission to exist with dignity.\n\nMy parents came from Lodz with two suitcases and the certainty that Berlin would let them be what they were. In the nineteen-twenties, that certainty still makes sense.\n\nI learned to sing by listening through the synagogue\'s open windows on Friday nights. There are certain sounds that don\'t ask permission to enter.\n\nAt sixteen I knew I wanted to sing on a stage. My mother said: that\'s not a job. My father said: of course it\'s a job, it\'s the hardest job there is.\n\nMy father was right. As always.\n\nWalk south along the river. Monbijoupark is three minutes away.',
    'DE': 'Berlin, 1925. Ich heiße Lena Hoffmann. Ich bin zweiundzwanzig Jahre alt und diese Stadt gehört mir.\n\nIch stehe vor der goldenen Kuppel der Neuen Synagoge. Ich kenne sie mein ganzes Leben – ich bin drei Straßen nördlich im Scheunenviertel aufgewachsen, und als Kind schien sie mir das Schönste zu sein, was es gibt. Das tue ich heute noch.\n\nSie wurde 1866 eingeweiht, als meine Großmutter noch ein Kind war. Achttausend Menschen im Inneren, heißt es, darunter Kanzler Bismarck – der nicht gerade für seine Sympathie gegenüber irgendjemandem bekannt war. Sie fasst dreitausend Gläubige, hat eine Orgel mit viertausenddreihundert Pfeifen und eine Kuppel aus Eisen und Zink, verkleidet mit goldenen Kacheln, die von den Dächern halb Berlins aus zu sehen ist. Der Architekt Eduard Knoblauch entwarf sie mit einer Mischung aus Neomaurisch und Rheinromanik – eine Kathedrale, die keine Kathedrale ist, errichtet von einer Gemeinschaft, die jahrhundertelang darum bat, mit Würde existieren zu dürfen.\n\nMeine Eltern kamen mit zwei Koffern aus Łódź und der Gewissheit, dass Berlin sie sein ließ, was sie waren. In den zwanziger Jahren hat diese Gewissheit noch einen Sinn.\n\nIch habe das Singen gelernt, indem ich freitagabends durch die offenen Fenster der Synagoge lauschte. Es gibt bestimmte Klänge, die nicht um Erlaubnis bitten, bevor sie eintreten.\n\nMit sechzehn wusste ich, dass ich auf einer Bühne singen wollte. Meine Mutter sagte: Das ist kein Beruf. Mein Vater sagte: Natürlich ist es ein Beruf, es ist der schwerste Beruf, den es gibt.\n\nMein Vater hatte recht. Wie immer.\n\nGeh nach Süden dem Fluss entlang. Der Monbijoupark ist drei Minuten entfernt.',
    'IT': 'Berlino, 1925. Mi chiamo Lena Hoffmann. Ho ventidue anni e questa città è mia.\n\nSono in piedi davanti alla cupola dorata della Nuova Sinagoga. La conosco da tutta la vita – sono cresciuta tre strade a nord, nello Scheunenviertel, e da bambina mi sembrava la cosa più bella che esistesse. Continua a sembrarmi tale.\n\nFu inaugurata nel 1866, quando mia nonna era ancora bambina. Ottomila persone all\'interno, dicono, incluso il cancelliere Bismarck – che non era certo noto per la sua simpatia verso nessuno. Ha una capienza di tremila fedeli, un organo di quattromilatrecento canne e una cupola di ferro e zinco rivestita di mattonelle dorate che si vedono dai tetti di mezza Berlino. L\'architetto Eduard Knoblauch la progettò mescolando lo stile neoarabo con il romanico renano – una cattedrale che non è una cattedrale, costruita da una comunità che per secoli chiese il permesso di esistere con dignità.\n\nI miei genitori arrivarono da Łódź con due valigie e la certezza che Berlino li avrebbe lasciati essere ciò che erano. Negli anni venti, quella certezza ha ancora un senso.\n\nHo imparato a cantare ascoltando dalle finestre aperte della sinagoga il venerdì sera. Ci sono certi suoni che non chiedono il permesso prima di entrare.\n\nA sedici anni sapevo che volevo cantare su un palcoscenico. Mia madre disse: non è un lavoro. Mio padre disse: certo che è un lavoro, è il lavoro più difficile che esista.\n\nMio padre aveva ragione. Come sempre.\n\nCammina verso sud seguendo il fiume. Il Monbijoupark è a tre minuti.',
  },
  'lena_02': {
    'ES': 'El Spree no es un río impresionante. Es discreto, de color gris verdoso, atraviesa la ciudad sin hacer ruido. Lo que tiene no es grandeza — es persistencia. Lleva fluyendo por aquí desde antes de que Berlín existiera y seguirá haciéndolo cuando Berlín sea otra cosa completamente distinta. Por eso me gusta.\n\nEste parque era en los años veinte uno de los pocos espacios verdes del centro sin estatuas de generales con espada. Solo árboles, el río al fondo, y una vista directa al Bode Museum al otro lado del puente. Donde estuvo el Palacio de Monbijou — residencia de la reina Sofia Dorotea — quedó en 1877 un parque público. La monarquía convertida en césped. Que también es una forma de democracia.\n\nVengo aquí los jueves. Mi único día libre en el Silhouetten — el cabaret de la Friedrichstrasse donde canto cinco noches a la semana. Llego con una manta y la intención firme de no pensar en nada. Nunca lo consigo del todo. Pero el intento vale la pena.\n\nHeinrich me encontró aquí una tarde de primavera de 1926. Estaba fingiendo leer cuando se sentó en el banco de al lado y dijo, sin mirarme: ese libro está al revés.\n\nNo estaba al revés. Pero lo giré de todas formas, porque me pareció una entrada demasiado buena para contradecirla.\n\nNos quedamos tres horas. Cuando se hizo de noche me di cuenta de que no había pensado en el Silhouetten ni una sola vez. Eso no me había pasado nunca.\n\nCruza el puente sobre el Spree. El Bode Museum está al final de la isla, a cuatro minutos.',
    'EN': 'The Spree is not an impressive river. It is discreet, grey-green, it flows through the city without making noise. What it has is not grandeur — it is persistence. It has been flowing here since before Berlin existed and will keep flowing when Berlin has become something entirely different. That is why I love it.\n\nIn the nineteen-twenties this park was one of the few green spaces in the city centre without a statue of a general holding a sword. Just trees, the river in the background, and a direct view of the Bode Museum across the bridge. Where the Monbijou Palace once stood — residence of Queen Sophie Dorothea — a public park opened in 1877. The monarchy turned into grass. Which is also a form of democracy.\n\nI come here on Thursdays. My only day off from the Silhouetten — the cabaret on Friedrichstrasse where I sing five nights a week. I arrive with a blanket and a firm intention to think about nothing. I never quite manage it. But the attempt is worth it.\n\nHeinrich found me here on a spring afternoon in 1926. I was pretending to read when he sat down on the bench beside me and said, without looking at me: that book is upside down.\n\nIt wasn\'t upside down. But I turned it over anyway, because it seemed too good an opening to contradict.\n\nWe stayed three hours. When it grew dark I realised I hadn\'t thought about the Silhouetten once. That had never happened before.\n\nCross the bridge over the Spree. The Bode Museum is at the end of the island, four minutes away.',
    'DE': 'Die Spree ist kein beeindruckender Fluss. Sie ist diskret, graugrün, durchquert die Stadt ohne Aufsehen. Was sie hat, ist keine Größe – es ist Beständigkeit. Sie fließt hier schon, bevor Berlin existierte, und wird es noch tun, wenn Berlin längst etwas ganz anderes geworden ist. Deshalb mag ich sie.\n\nDieser Park war in den zwanziger Jahren einer der wenigen Grünflächen im Zentrum ohne Statuen von Generälen mit Schwert. Nur Bäume, der Fluss im Hintergrund und ein direkter Blick auf das Bode-Museum auf der anderen Seite der Brücke. Wo einst das Schloss Monbijou stand – Residenz der Königin Sophie Dorothea – entstand 1877 ein öffentlicher Park. Die Monarchie verwandelt in Rasen. Das ist auch eine Form von Demokratie.\n\nIch komme donnerstags. Mein einziger freier Tag im Silhouetten – dem Kabarett in der Friedrichstraße, wo ich fünf Nächte die Woche singe. Ich komme mit einer Decke und dem festen Vorsatz, an nichts zu denken. Ganz gelingt mir das nie. Aber der Versuch lohnt sich.\n\nHeinrich fand mich hier an einem Frühlingsnachmittag 1926. Ich tat so, als würde ich lesen, als er sich auf die Bank neben mir setzte und sagte, ohne mich anzusehen: Das Buch ist verkehrt herum.\n\nEs war nicht verkehrt herum. Aber ich drehte es trotzdem um, weil mir der Anfang zu gut erschien, um ihn zu widerlegen.\n\nWir blieben drei Stunden. Als es dunkel wurde, merkte ich, dass ich kein einziges Mal ans Silhouetten gedacht hatte. Das war mir noch nie passiert.\n\nÜberquere die Brücke über die Spree. Das Bode-Museum liegt am Ende der Insel, vier Minuten entfernt.',
    'IT': 'La Spree non è un fiume impressionante. È discreto, di un grigio verdastro, attraversa la città senza fare rumore. Quello che ha non è grandezza – è persistenza. Scorre qui da prima che Berlino esistesse e continuerà a farlo quando Berlino sarà qualcosa di completamente diverso. Ecco perché mi piace.\n\nQuesto parco era negli anni venti uno dei pochi spazi verdi del centro senza statue di generali con la spada. Solo alberi, il fiume sullo sfondo e una vista diretta sul Bode Museum dall\'altra parte del ponte. Dove si trovava il Palazzo di Monbijou – residenza della regina Sofia Dorotea – nel 1877 nacque un parco pubblico. La monarchia trasformata in prato. Che è anche una forma di democrazia.\n\nVengo di giovedì. Il mio unico giorno libero al Silhouetten – il cabaret della Friedrichstrasse dove canto cinque notti a settimana. Arrivo con una coperta e la ferma intenzione di non pensare a niente. Non ci riesco mai del tutto. Ma il tentativo vale la pena.\n\nHeinrich mi trovò qui un pomeriggio di primavera del 1926. Stavo fingendo di leggere quando si sedette sulla panchina accanto a me e disse, senza guardarmi: quel libro è capovolto.\n\nNon era capovolto. Ma lo girai lo stesso, perché mi sembrò un inizio troppo buono per contraddirlo.\n\nRestammo tre ore. Quando si fece buio mi accorsi che non avevo pensato al Silhouetten nemmeno una volta. Non mi era mai successo.\n\nAttraversa il ponte sulla Spree. Il Bode Museum si trova in fondo all\'isola, a quattro minuti.',
  },
  'lena_03': {
    'ES': 'Para un momento y mira este edificio.\n\nLo conozco desde que tengo memoria. Lo construyeron entre 1897 y 1904 en la punta norte de la Museumsinsel, encajado entre los dos brazos del Spree como la proa de un barco que no va a ningún lado. El arquitecto Ernst von Ihne quería que pareciera que emergía directamente del agua. Lo consiguió. La cúpula central tiene 23 metros, corona una estructura de casi 20.000 metros cuadrados construida para albergar lo que el Imperio alemán consideraba el arte más valioso del mundo: esculturas bizantinas, monedas antiguas, marfiles medievales, obras de los siglos XII al XVIII que viajaron desde toda Europa hasta esta isla.\n\nEl Kaiser Guillermo II lo inauguró y le puso su propio nombre. En 1956 lo rebautizaron Bode Museum, en honor al museólogo Wilhelm von Bode, que pasó cuarenta años convirtiendo esta isla en algo sin equivalente en el mundo.\n\nVengo los domingos por la mañana, antes de que el resto del mundo se despierte. Me voy directo a la sala de esculturas bizantinas del tercer piso — la sala más silenciosa del museo. Hay una madonna de marfil del siglo XII a la que visito como si fuera una amiga. Tiene la cara de alguien que ha entendido algo difícil y ha decidido seguir de todas formas.\n\nHeinrich nunca entendió esa costumbre. ¿Para qué vas siempre a ver lo mismo?, me pregunta. Le respondo: para ver si ha cambiado algo. Dice: es una escultura de marfil del siglo doce, no ha cambiado nada. Le digo: exacto.\n\nEn 1945 una bomba destruyó parte del ala este. La madonna sobrevivió. Está todavía aquí, en el tercer piso, con exactamente la misma expresión.\n\nSigue por el puente hacia el sur. El Berliner Dom está a cuatro minutos.',
    'EN': 'Stop for a moment and look at this building.\n\nI have known it since I can remember. They built it between 1897 and 1904 at the northern tip of the Museumsinsel, wedged between the two arms of the Spree like the prow of a ship going nowhere. The architect Ernst von Ihne wanted it to look as if it were emerging directly from the water. He succeeded. The central dome is 23 metres across, crowning a structure of nearly 20,000 square metres built to house what the German Empire considered the world\'s most valuable art: Byzantine sculptures, ancient coins, medieval ivories, works from the 12th to the 18th century that travelled from across Europe to this island.\n\nKaiser Wilhelm II inaugurated it and gave it his own name. In 1956 it was renamed the Bode Museum, in honour of the museologist Wilhelm von Bode, who spent forty years turning this island into something without equal in the world.\n\nI come on Sunday mornings, before the rest of the world wakes up. I go straight to the Byzantine sculpture room on the third floor — the quietest room in the museum. There is a 12th-century ivory madonna I visit as if visiting a friend. She has the face of someone who has understood something difficult and decided to carry on anyway.\n\nHeinrich never understood the habit. Why do you always go to see the same thing?, he asks. I answer: to see if anything has changed. He says: it\'s a 12th-century ivory sculpture, nothing has changed. I say: exactly.\n\nIn 1945 a bomb destroyed part of the east wing. The madonna survived. She is still here, on the third floor, with exactly the same expression.\n\nContinue over the bridge heading south. The Berliner Dom is four minutes away.',
    'DE': 'Halte einen Moment inne und schau dir dieses Gebäude an.\n\nIch kenne es, seit ich denken kann. Es wurde zwischen 1897 und 1904 an der Nordspitze der Museumsinsel gebaut, eingeklemmt zwischen die beiden Arme der Spree wie der Bug eines Schiffes, das nirgendwo hinfährt. Der Architekt Ernst von Ihne wollte, dass es direkt aus dem Wasser aufzutauchen scheint. Das ist ihm gelungen. Die Mittelkuppel misst 23 Meter, sie krönt ein Bauwerk von fast 20.000 Quadratmetern, das errichtet wurde, um das zu beherbergen, was das Deutsche Kaiserreich als wertvollste Kunst der Welt betrachtete: byzantinische Skulpturen, antike Münzen, mittelalterliche Elfenbeinarbeiten, Werke vom 12. bis 18. Jahrhundert, die aus ganz Europa auf diese Insel gereist waren.\n\nKaiser Wilhelm II. weihte es ein und gab ihm seinen eigenen Namen. 1956 wurde es in Bode-Museum umbenannt, zu Ehren des Museumswissenschaftlers Wilhelm von Bode, der vierzig Jahre damit verbrachte, diese Insel in etwas ohne Gleiches auf der Welt zu verwandeln.\n\nIch komme sonntags morgens, bevor der Rest der Welt aufwacht. Ich gehe direkt in den Saal mit den byzantinischen Skulpturen im dritten Stock – den stillsten Saal des Museums. Es gibt eine Elfenbeinmadonna aus dem 12. Jahrhundert, die ich besuche wie eine Freundin. Sie hat das Gesicht von jemandem, der etwas Schwieriges begriffen hat und sich entschieden hat, trotzdem weiterzumachen.\n\nHeinrich hat diese Gewohnheit nie verstanden. Wozu gehst du immer dasselbe ansehen?, fragt er. Ich antworte: um zu sehen, ob sich etwas verändert hat. Er sagt: Es ist eine Elfenbeinskulptur aus dem zwölften Jahrhundert, da hat sich nichts verändert. Ich sage: Genau.\n\n1945 zerstörte eine Bombe Teile des Ostflügels. Die Madonna überlebte. Sie ist noch immer hier, im dritten Stock, mit genau demselben Ausdruck.\n\nWeiter über die Brücke nach Süden. Der Berliner Dom ist vier Minuten entfernt.',
    'IT': 'Fermati un momento e guarda questo edificio.\n\nLo conosco da quando ho memoria. Fu costruito tra il 1897 e il 1904 alla punta nord della Museumsinsel, incastrato tra i due bracci della Spree come la prua di una nave che non va da nessuna parte. L\'architetto Ernst von Ihne volle che sembrasse emergere direttamente dall\'acqua. Ci riuscì. La cupola centrale misura 23 metri, corona una struttura di quasi 20.000 metri quadrati costruita per accogliere ciò che l\'Impero tedesco considerava l\'arte più preziosa del mondo: sculture bizantine, monete antiche, avori medievali, opere dal XII al XVIII secolo che avevano viaggiato da tutta Europa fino a quest\'isola.\n\nL\'imperatore Guglielmo II lo inaugurò e gli diede il proprio nome. Nel 1956 fu ribattezzato Bode Museum, in onore del museografo Wilhelm von Bode, che trascorse quarant\'anni a trasformare quest\'isola in qualcosa senza eguali al mondo.\n\nVengo la domenica mattina, prima che il resto del mondo si svegli. Vado direttamente alla sala delle sculture bizantine al terzo piano – la sala più silenziosa del museo. C\'è una madonna d\'avorio del XII secolo che visito come un\'amica. Ha il viso di qualcuno che ha capito qualcosa di difficile e ha deciso di andare avanti lo stesso.\n\nHeinrich non ha mai capito questa abitudine. Perché vai sempre a vedere la stessa cosa?, mi chiede. Rispondo: per vedere se è cambiato qualcosa. Dice: è una scultura d\'avorio del dodicesimo secolo, non è cambiato niente. Dico: esatto.\n\nNel 1945 una bomba distrusse parte dell\'ala est. La madonna sopravvisse. È ancora qui, al terzo piano, con esattamente la stessa espressione.\n\nContinua sul ponte verso sud. Il Berliner Dom è a quattro minuti.',
  },
  'lena_04': {
    'ES': 'Mira hacia arriba.\n\nSé lo que ves. La cúpula del Berliner Dom tiene 98 metros de altura. La construyeron entre 1894 y 1905 por orden del Kaiser Guillermo II, que quería una catedral protestante capaz de competir con San Pedro de Roma. No lo consiguió — Roma gana esa pelea sin esfuerzo — pero el intento es genuinamente imponente. El arquitecto Julius Raschdorff diseñó un edificio de mármol, granito y arenisca con capacidad para 1.500 personas, cuatro torres angulares, y una cripta imperial que alberga más de noventa sarcófagos de la dinastía Hohenzollern. Los que construyeron esto creían que duraría para siempre. Casi todo lo que se construye en Berlín lo creen.\n\nYo detesto este edificio. No la arquitectura — eso es otra cuestión. Lo que odio es lo que representa: el Berlín oficial, el Berlín del poder y los uniformes, el Berlín que mira con condescendencia el Berlín de los cabarets, los inmigrantes y la gente que vive demasiado fuerte.\n\nEn los años veinte existen dos Berlín en paralelo, casi sin tocarse. El Berlín de las instituciones y la burguesía respetable. Y mi Berlín: artistas, músicos, gente llegada de toda Europa porque aquí pueden ser lo que son.\n\nPero hay algo que me gusta del Lustgarten en verano: las familias lo toman con mantas y niños y perros, y el contraste entre la solemnidad imperial de la catedral y ese caos alegre me parece la imagen más honesta de la ciudad. Berlín ha sido siempre eso: demasiado grande para tener una sola cara.\n\nCamina hacia el oeste por la Unter den Linden. La Staatsoper está al fondo del bulevar.',
    'EN': 'Look up.\n\nI know what you see. The dome of the Berliner Dom is 98 metres tall. They built it between 1894 and 1905 on the orders of Kaiser Wilhelm II, who wanted a Protestant cathedral capable of competing with St Peter\'s in Rome. He didn\'t manage it — Rome wins that fight without effort — but the attempt is genuinely imposing. The architect Julius Raschdorff designed a building of marble, granite and sandstone with capacity for 1,500 people, four corner towers, and an imperial crypt housing over ninety sarcophagi of the Hohenzollern dynasty. Those who built this believed it would last forever. Almost everything built in Berlin does.\n\nI detest this building. Not the architecture — that is another matter. What I hate is what it represents: official Berlin, the Berlin of power and uniforms, the Berlin that looks down on the Berlin of cabarets, immigrants and people who live too loudly.\n\nIn the nineteen-twenties there are two Berlins running in parallel, barely touching. The Berlin of institutions and respectable bourgeoisie. And my Berlin: artists, musicians, people who have come from all over Europe because here they can be what they are.\n\nBut there is one thing I like about the Lustgarten in summer: families spread out with blankets and children and dogs, and the contrast between the imperial solemnity of the cathedral and that cheerful chaos seems to me the most honest image of the city. Berlin has always been that: too large to have a single face.\n\nWalk west along Unter den Linden. The Staatsoper is at the far end of the boulevard.',
    'DE': 'Schau nach oben.\n\nIch weiß, was du siehst. Die Kuppel des Berliner Doms ist 98 Meter hoch. Sie wurde zwischen 1894 und 1905 auf Befehl Kaiser Wilhelms II. erbaut, der eine protestantische Kathedrale wollte, die mit dem Petersdom in Rom konkurrieren konnte. Das gelang nicht – Rom gewinnt diesen Kampf mühelos – aber der Versuch ist aufrichtig beeindruckend. Der Architekt Julius Raschdorff entwarf ein Gebäude aus Marmor, Granit und Sandstein mit 1.500 Sitzplätzen, vier Ecktürmen und einer Kaisergruft mit mehr als neunzig Sarkophagen der Hohenzollern-Dynastie. Die, die das erbauten, glaubten, es würde ewig dauern. Fast alles, was in Berlin gebaut wird, glaubt das.\n\nIch hasse dieses Gebäude. Nicht die Architektur – das ist eine andere Frage. Was ich hasse, ist das, wofür es steht: das offizielle Berlin, das Berlin der Macht und der Uniformen, das Berlin, das das Berlin der Kabaretts, der Einwanderer und der Menschen, die zu intensiv leben, mit Herablassung betrachtet.\n\nIn den zwanziger Jahren gibt es zwei Berlins nebeneinander, die sich kaum berühren. Das Berlin der Institutionen und der angesehenen Bürgerlichkeit. Und mein Berlin: Künstler, Musiker, Menschen aus ganz Europa, die hierher gekommen sind, weil sie hier sein können, was sie sind.\n\nAber es gibt etwas an dem Lustgarten im Sommer, das mir gefällt: Familien nehmen ihn mit Decken, Kindern und Hunden in Besitz, und der Kontrast zwischen der imperialen Feierlichkeit der Kathedrale und diesem fröhlichen Chaos erscheint mir als das ehrlichste Bild der Stadt. Berlin war immer das: zu groß, um ein einziges Gesicht zu haben.\n\nGeh nach Westen entlang der Unter den Linden. Die Staatsoper liegt am Ende des Boulevards.',
    'IT': 'Guarda in su.\n\nSo cosa vedi. La cupola del Berliner Dom è alta 98 metri. Fu costruita tra il 1894 e il 1905 per ordine dell\'imperatore Guglielmo II, che voleva una cattedrale protestante capace di competere con San Pietro a Roma. Non ci riuscì – Roma vince quella lotta senza sforzo – ma il tentativo è genuinamente imponente. L\'architetto Julius Raschdorff progettò un edificio di marmo, granito e arenaria con 1.500 posti, quattro torri angolari e una cripta imperiale con più di novanta sarcofagi della dinastia Hohenzollern. Quelli che costruirono questo credevano che sarebbe durato per sempre. Quasi tutto ciò che si costruisce a Berlino lo crede.\n\nIo odio questo edificio. Non l\'architettura – quella è un\'altra questione. Quello che odio è ciò che rappresenta: la Berlino ufficiale, la Berlino del potere e delle uniformi, la Berlino che guarda con condiscendenza la Berlino dei cabaret, degli immigrati e della gente che vive troppo intensamente.\n\nNegli anni venti esistono due Berlino in parallelo, quasi senza toccarsi. La Berlino delle istituzioni e della borghesia rispettabile. E la mia Berlino: artisti, musicisti, gente arrivata da tutta Europa perché qui possono essere ciò che sono.\n\nMa c\'è qualcosa che mi piace del Lustgarten d\'estate: le famiglie lo occupano con coperte, bambini e cani, e il contrasto tra la solennità imperiale della cattedrale e quel caos allegro mi sembra l\'immagine più onesta della città. Berlino è sempre stata questo: troppo grande per avere un solo volto.\n\nCammina verso ovest lungo Unter den Linden. La Staatsoper si trova in fondo al viale.',
  },
  'lena_05': {
    'ES': 'Es el 10 de mayo de 1933. Tengo treinta años.\n\nHan pasado ocho desde que llegué al Silhouetten. Ocho años en los que Berlín fue la ciudad más libre de la tierra y luego fue dejando de serlo — tan despacio que era fácil no notarlo, tan rápido que cuando lo notabas ya era tarde.\n\nEstoy en la Bebelplatz. El edificio blanco a tu derecha es la Staatsoper Unter den Linden — la conozco bien, la construyeron en 1742 por orden de Federico el Grande como el primer edificio independiente de ópera de Europa. Su fachada neoclásica de columnas corintias fue diseñada por Georg Wenzeslaus von Knobelsdorff. Aquí actuaron Mozart, Beethoven, Richard Strauss. Aquí el rey de Prusia sentó las bases de lo que los alemanes llaman Kulturnation — la idea de que una nación se define por su cultura tanto como por sus fronteras.\n\nEsta noche, frente a ese mismo edificio, hay fuego en la plaza.\n\nEstán quemando libros. Los de Freud. Los de Marx. Los de Remarque. Los de Heinrich Heine, que escribió en 1820: donde queman libros, al final también queman personas. Lo escribió aquí, en Berlín, sobre los moros de España. Nadie imaginó que sería una profecía sobre este mismo suelo.\n\nHeinrich aprieta mi mano tan fuerte que duele. No le pido que me suelte.\n\nUn estudiante universitario pasa cargando una pila de libros, sonriendo. Tiene diecinueve años. Lo miro y pienso: este chico fue un bebé. Su madre lo amó. ¿Cómo se llega de ese bebé a este chico que sonríe mientras quema libros?\n\nNo encuentro la respuesta. Quizás no la hay.\n\nCamina hacia el este. La Neue Wache está a doscientos metros. Ahí voy a decidir. Y tú también.',
    'EN': 'It is 10 May 1933. I am thirty years old.\n\nEight years have passed since I arrived at the Silhouetten. Eight years in which Berlin was the freest city on earth and then gradually stopped being so — slowly enough that it was easy not to notice, quickly enough that by the time you noticed it was already too late.\n\nI am on the Bebelplatz. The white building on your right is the Staatsoper Unter den Linden — I know it well, they built it in 1742 on the orders of Frederick the Great as the first freestanding opera house in Europe. Its neoclassical facade of Corinthian columns was designed by Georg Wenzeslaus von Knobelsdorff. Mozart, Beethoven, Richard Strauss performed here. Here the King of Prussia laid the foundations of what Germans call Kulturnation — the idea that a nation defines itself by its culture as much as by its borders.\n\nTonight, in front of that same building, there is fire in the square.\n\nBooks are burning. Freud\'s. Marx\'s. Remarque\'s. Heinrich Heine\'s — who wrote in 1820: where they burn books, they will ultimately burn people too. He wrote it here, in Berlin, about the Moors of Spain. No one imagined it would be a prophecy about this very ground.\n\nHeinrich is squeezing my hand so hard it hurts. I don\'t ask him to let go.\n\nA university student walks past carrying a pile of books, smiling. He is nineteen years old. I watch him and think: this boy was a baby once. His mother loved him. How do you get from that baby to this boy smiling while he burns books?\n\nI don\'t find the answer. Perhaps there isn\'t one.\n\nWalk east. The Neue Wache is two hundred metres away. There I will decide. And so will you.',
    'DE': 'Es ist der 10. Mai 1933. Ich bin dreißig Jahre alt.\n\nAcht Jahre sind vergangen, seit ich ins Silhouetten kam. Acht Jahre, in denen Berlin die freieste Stadt der Welt war und dann aufhörte, es zu sein – so langsam, dass man es leicht nicht bemerkte, so schnell, dass es zu spät war, wenn man es bemerkte.\n\nIch stehe auf der Bebelplatz. Das weiße Gebäude rechts von dir ist die Staatsoper Unter den Linden – ich kenne sie gut, sie wurde 1742 auf Befehl Friedrichs des Großen als erstes eigenständiges Operngebäude Europas gebaut. Ihre neoklassizistische Fassade mit korinthischen Säulen wurde von Georg Wenzeslaus von Knobelsdorff entworfen. Hier traten Mozart, Beethoven, Richard Strauss auf. Hier legte der König von Preußen den Grundstein für das, was die Deutschen Kulturnation nennen – die Idee, dass eine Nation sich durch ihre Kultur ebenso definiert wie durch ihre Grenzen.\n\nDiese Nacht, vor genau diesem Gebäude, brennt es auf dem Platz.\n\nSie verbrennen Bücher. Die von Freud. Die von Marx. Die von Remarque. Die von Heinrich Heine, der 1820 schrieb: Dort, wo man Bücher verbrennt, verbrennt man auch am Ende Menschen. Er schrieb das hier, in Berlin, über die Mauren in Spanien. Niemand ahnte, dass es eine Prophezeiung über diesen selben Boden sein würde.\n\nHeinrich drückt meine Hand so fest, dass es wehtut. Ich bitte ihn nicht, loszulassen.\n\nEin Universitätsstudent geht vorbei und trägt einen Stapel Bücher, lächelnd. Er ist neunzehn Jahre alt. Ich schaue ihn an und denke: Dieser Junge war einmal ein Baby. Seine Mutter hat ihn geliebt. Wie kommt man von diesem Baby zu diesem Jungen, der lächelt, während er Bücher verbrennt?\n\nIch finde keine Antwort. Vielleicht gibt es sie nicht.\n\nGeh nach Osten. Die Neue Wache ist zweihundert Meter entfernt. Dort werde ich entscheiden. Und du auch.',
    'IT': 'È il 10 maggio 1933. Ho trent\'anni.\n\nSono passati otto anni da quando sono arrivata al Silhouetten. Otto anni in cui Berlino è stata la città più libera della terra e poi ha smesso di esserlo – così lentamente che era facile non accorgersene, così velocemente che quando te ne accorgevi era già tardi.\n\nSono in piedi sulla Bebelplatz. L\'edificio bianco alla tua destra è la Staatsoper Unter den Linden – la conosco bene, fu costruita nel 1742 per ordine di Federico il Grande come primo edificio operistico indipendente d\'Europa. La sua facciata neoclassica con colonne corinzie fu progettata da Georg Wenzeslaus von Knobelsdorff. Qui si esibirono Mozart, Beethoven, Richard Strauss. Qui il re di Prussia pose le basi di ciò che i tedeschi chiamano Kulturnation – l\'idea che una nazione si definisca attraverso la sua cultura tanto quanto attraverso i suoi confini.\n\nStanotte, davanti a quello stesso edificio, c\'è il fuoco sulla piazza.\n\nStanno bruciando libri. Quelli di Freud. Quelli di Marx. Quelli di Remarque. Quelli di Heinrich Heine, che nel 1820 scrisse: dove si bruciano i libri, alla fine si bruciano anche le persone. Lo scrisse qui, a Berlino, sui mori di Spagna. Nessuno immaginò che sarebbe stata una profezia su questo stesso suolo.\n\nHeinrich stringe la mia mano così forte che fa male. Non gli chiedo di lasciarla andare.\n\nUno studente universitario passa portando una pila di libri, sorridendo. Ha diciannove anni. Lo guardo e penso: questo ragazzo era un bambino. Sua madre lo ha amato. Come si arriva da quel bambino a questo ragazzo che sorride mentre brucia libri?\n\nNon trovo la risposta. Forse non esiste.\n\nCammina verso est. La Neue Wache è a duecento metri. Lì deciderò. E anche tu.',
  },
  'lena_06': {
    'ES': 'Entra.\n\nLa Neue Wache la construyó Karl Friedrich Schinkel entre 1816 y 1818 — el arquitecto que más influyó en cómo Berlín decidió verse a sí misma. La diseñó como guardia real, con fachada de templo griego y seis columnas dóricas que dan a Unter den Linden. A lo largo del siglo XX cambió de uso tantas veces como cambió Alemania: memorial a los caídos en la Primera Guerra Mundial, lugar de honor nazi, memorial soviético a las víctimas del fascismo, y finalmente — desde 1993 — memorial central de la República Federal a las víctimas de la guerra y la tiranía.\n\nLo que hay dentro es deliberadamente sencillo: una sola escultura bajo una abertura circular en el techo por donde entra la lluvia, la nieve, el cielo. La escultura es una ampliación de la pieza de Käthe Kollwitz llamada Madre con hijo muerto. Kollwitz la hizo pensando en su propio hijo, que murió en la Primera Guerra Mundial. Y en su nieto, que murió en la Segunda. La misma madre. Dos guerras. El mismo peso insoportable.\n\nEntro sola. Le pido a Heinrich que espere fuera.\n\nMe quedo de pie frente a la escultura un tiempo que no sé medir. Pienso en mi madre enferma. En mis vecinos que tienen miedo. En Heinrich, que lleva tres semanas con los papeles listos.\n\nY tengo que elegir.\n\nAhora tú también tienes que elegir.\n\n¿Sigues a la Lena que decidió irse? Camina hacia el oeste, hacia el Memorial del Holocausto.\n\n¿O sigues a la Lena que decidió quedarse? Camina hacia el este, hacia el Lustgarten.\n\nNo hay respuesta correcta. Nunca la hubo.',
    'EN': 'Go inside.\n\nKarl Friedrich Schinkel built the Neue Wache between 1816 and 1818 — the architect who most influenced how Berlin decided to see itself. He designed it as the royal guardhouse, with a Greek temple facade and six Doric columns facing Unter den Linden. Over the course of the 20th century it changed purpose as many times as Germany changed: memorial to the fallen of the First World War, Nazi place of honour, Soviet memorial to the victims of fascism, and finally — since 1993 — the Federal Republic\'s central memorial to the victims of war and tyranny.\n\nWhat is inside is deliberately simple: a single sculpture beneath a circular opening in the roof through which rain, snow and sky enter. The sculpture is an enlargement of Käthe Kollwitz\'s piece called Mother with Dead Son. Kollwitz made it thinking of her own son, who died in the First World War. And of her grandson, who died in the Second. The same mother. Two wars. The same unbearable weight.\n\nI go in alone. I ask Heinrich to wait outside.\n\nI stand in front of the sculpture for a length of time I cannot measure. I think about my sick mother. About my neighbours who are frightened. About Heinrich, who has had the papers ready for three weeks.\n\nAnd I have to choose.\n\nNow you have to choose too.\n\nDo you follow the Lena who decided to leave? Walk west, toward the Holocaust Memorial.\n\nOr do you follow the Lena who decided to stay? Walk east, toward the Lustgarten.\n\nThere is no right answer. There never was.',
    'DE': 'Tritt ein.\n\nDie Neue Wache wurde von Karl Friedrich Schinkel zwischen 1816 und 1818 erbaut – dem Architekten, der am stärksten beeinflusste, wie Berlin sich selbst sehen wollte. Er entwarf sie als königliche Wache, mit einer Tempelfassade und sechs dorischen Säulen zur Unter den Linden. Im Laufe des 20. Jahrhunderts wechselte sie die Nutzung so oft wie Deutschland wechselte: Mahnmal für die Gefallenen des Ersten Weltkriegs, nationalsozialistischer Ehrenort, sowjetisches Mahnmal für die Opfer des Faschismus, und schließlich – seit 1993 – Zentrales Mahnmal der Bundesrepublik für die Opfer von Krieg und Gewaltherrschaft.\n\nWas sich drinnen befindet, ist bewusst schlicht: eine einzige Skulptur unter einer kreisförmigen Öffnung im Dach, durch die Regen, Schnee und Himmel hereinlassen. Die Skulptur ist eine Vergrößerung von Käthe Kollwitz\' Werk Mutter mit totem Sohn. Kollwitz schuf es in Gedanken an ihren eigenen Sohn, der im Ersten Weltkrieg gefallen war. Und an ihren Enkel, der im Zweiten starb. Dieselbe Mutter. Zwei Kriege. Dieselbe unerträgliche Last.\n\nIch trete allein ein. Ich bitte Heinrich, draußen zu warten.\n\nIch stehe eine nicht messbare Zeit vor der Skulptur. Ich denke an meine kranke Mutter. An meine Nachbarn, die Angst haben. An Heinrich, der seit drei Wochen mit den Papieren bereit ist.\n\nUnd ich muss wählen.\n\nJetzt musst auch du wählen.\n\nFolgst du der Lena, die sich entschieden hat zu gehen? Geh nach Westen, zum Holocaust-Mahnmal.\n\nOder folgst du der Lena, die sich entschieden hat zu bleiben? Geh nach Osten, zum Lustgarten.\n\nEs gibt keine richtige Antwort. Das hat es nie gegeben.',
    'IT': 'Entra.\n\nLa Neue Wache fu costruita da Karl Friedrich Schinkel tra il 1816 e il 1818 – l\'architetto che più influenzò il modo in cui Berlino decise di vedere se stessa. La progettò come guardia reale, con una facciata a tempio e sei colonne doriche che danno su Unter den Linden. Nel corso del XX secolo cambiò utilizzo tante volte quante cambiò la Germania: memoriale per i caduti della Prima Guerra Mondiale, luogo d\'onore nazista, memoriale sovietico alle vittime del fascismo, e infine – dal 1993 – Memoriale Centrale della Repubblica Federale alle vittime della guerra e della tirannia.\n\nCiò che si trova all\'interno è deliberatamente semplice: un\'unica scultura sotto un\'apertura circolare nel tetto da cui entra la pioggia, la neve, il cielo. La scultura è un ingrandimento dell\'opera di Käthe Kollwitz Madre con figlio morto. Kollwitz la creò pensando al proprio figlio, morto nella Prima Guerra Mondiale. E al nipote, morto nella Seconda. La stessa madre. Due guerre. Lo stesso peso insopportabile.\n\nEntro da sola. Chiedo a Heinrich di aspettare fuori.\n\nResto in piedi davanti alla scultura per un tempo che non so misurare. Penso a mia madre malata. Ai miei vicini che hanno paura. A Heinrich, che da tre settimane ha i documenti pronti.\n\nE devo scegliere.\n\nOra devi scegliere anche tu.\n\nSegui la Lena che ha deciso di andarsene? Cammina verso ovest, verso il Memoriale dell\'Olocausto.\n\nO segui la Lena che ha deciso di restare? Cammina verso est, verso il Lustgarten.\n\nNon c\'è una risposta giusta. Non c\'è mai stata.',
  },
  'lena_07a': {
    'ES': 'Camina despacio entre las estelas.\n\nNo voy a ver este memorial nunca. Lo inauguraron en 2005, dieciocho años después de mi muerte en París. Pero crucé por este terreno en enero de 1934, caminando hacia la estación con Heinrich y dos maletas.\n\nLo diseñó el arquitecto Peter Eisenman después de dieciséis años de debate público. El resultado son 2.711 bloques de hormigón de distintas alturas sobre un terreno levemente ondulado, sin inscripciones, sin nombres, sin explicación. Los bloques crecen a tu alrededor hasta que el cielo desaparece y estás solo en un corredor entre paredes grises sin fin visible. Cada persona que entra lo recorre de una manera diferente. Eso era parte del diseño.\n\nLo que dejé atrás no cabe en una lista. El zapatero que me arreglaba los tacones sin cobrarme. El olor a café del apartamento de mis vecinos. La luz de la tarde entrando por mi ventana exactamente a las cinco. Mi madre, que murió en Berlín en 1941 sin que yo pudiera estar con ella.\n\nEso es lo que significa irse. No la distancia. Lo que se queda.\n\nDurante años tuve una costumbre en París: cuando olía pan recién horneado, me detenía un segundo. Porque el olor me recordaba la panadería de la Rosenthaler Strasse. Y ese recuerdo era lo más cerca que podía estar de casa.\n\nSal por el lado oeste. La Puerta de Brandenburgo está a tres minutos.',
    'EN': 'Walk slowly between the stelae.\n\nI will never see this memorial. It was inaugurated in 2005, eighteen years after my death in Paris. But I walked through this ground in January 1934, heading for the station with Heinrich and two suitcases.\n\nThe architect Peter Eisenman designed it after sixteen years of public debate. The result is 2,711 concrete blocks of varying heights on gently undulating ground, with no inscriptions, no names, no explanation. The blocks rise around you until the sky disappears and you are alone in a corridor between grey walls with no visible end. Every person who enters walks through it differently. That was part of the design.\n\nWhat I left behind does not fit on a list. The cobbler who fixed my heels without charging. The smell of coffee from my neighbours\' apartment. The afternoon light coming through my window at exactly five o\'clock. My mother, who died in Berlin in 1941 while I was far away.\n\nThat is what leaving means. Not the distance. What stays behind.\n\nFor years in Paris I had a habit: when I smelled freshly baked bread, I stopped for a second. Because the smell reminded me of the bakery on Rosenthaler Strasse. And that memory was the closest I could get to home.\n\nLeave through the west side. The Brandenburg Gate is three minutes away.',
    'DE': 'Geh langsam zwischen den Stelen hindurch.\n\nIch werde dieses Mahnmal nie sehen. Es wurde 2005 eingeweiht, achtzehn Jahre nach meinem Tod in Paris. Aber ich durchquerte dieses Gelände im Januar 1934, als ich mit Heinrich und zwei Koffern zur Bahnhof lief.\n\nEr wurde vom Architekten Peter Eisenman nach sechzehn Jahren öffentlicher Debatte gestaltet. Das Ergebnis sind 2.711 Betonquader verschiedener Höhe auf einem leicht gewellten Gelände, ohne Inschriften, ohne Namen, ohne Erklärung. Die Blöcke wachsen um dich herum, bis der Himmel verschwindet und du allein in einem Korridor zwischen grenzenlosen grauen Wänden stehst. Jeder Mensch, der es betritt, geht es auf eine andere Weise ab. Das war Teil des Entwurfs.\n\nWas ich zurückließ, lässt sich nicht in einer Liste erfassen. Der Schuhmacher, der mir die Absätze reparierte, ohne etwas zu berechnen. Der Kaffeeduft aus der Wohnung meiner Nachbarn. Das Licht des Nachmittags, das um Punkt fünf Uhr durch mein Fenster fiel. Meine Mutter, die 1941 in Berlin starb, ohne dass ich bei ihr sein konnte.\n\nDas bedeutet Weggehen. Nicht die Entfernung. Was zurückbleibt.\n\nJahrelang hatte ich eine Gewohnheit in Paris: Wenn ich frisch gebackenes Brot roch, hielt ich einen Moment inne. Weil der Geruch mich an die Bäckerei in der Rosenthaler Straße erinnerte. Und diese Erinnerung war das Nächste, was ich der Heimat kommen konnte.\n\nGeh nach Westen hinaus. Das Brandenburger Tor ist drei Minuten entfernt.',
    'IT': 'Cammina lentamente tra le stele.\n\nNon vedrò mai questo memoriale. Fu inaugurato nel 2005, diciotto anni dopo la mia morte a Parigi. Ma attraversai questo terreno nel gennaio 1934, camminando verso la stazione con Heinrich e due valigie.\n\nFu progettato dall\'architetto Peter Eisenman dopo sedici anni di dibattito pubblico. Il risultato sono 2.711 blocchi di cemento di diverse altezze su un terreno leggermente ondulato, senza iscrizioni, senza nomi, senza spiegazioni. I blocchi crescono intorno a te finché il cielo scompare e sei solo in un corridoio tra pareti grigie senza fine visibile. Ogni persona che entra lo percorre in modo diverso. Faceva parte del progetto.\n\nCiò che lasciai dietro di me non sta in un elenco. Il calzolaio che mi riparava i tacchi senza farmi pagare. L\'odore di caffè dall\'appartamento dei miei vicini. La luce del pomeriggio che entrava dalla mia finestra esattamente alle cinque. Mia madre, morta a Berlino nel 1941 senza che potessi essere con lei.\n\nÈ questo che significa andarsene. Non la distanza. Ciò che rimane.\n\nPer anni a Parigi ebbi un\'abitudine: quando sentivo l\'odore del pane appena sfornato, mi fermavo un secondo. Perché quell\'odore mi ricordava la panetteria della Rosenthaler Strasse. E quel ricordo era quanto di più vicino alla casa potessi stare.\n\nEsci dal lato ovest. La Porta di Brandeburgo è a tre minuti.',
  },
  'lena_08a': {
    'ES': 'Enero de 1934. Hace frío.\n\nHeinrich y yo estamos parados aquí, frente a la Puerta, con dos maletas.\n\nLa Puerta de Brandenburgo la construyeron entre 1788 y 1791 como símbolo de paz — su nombre original era Friedenstor. Tiene 26 metros de alto y 65 de ancho, con seis pares de columnas dóricas inspiradas en los Propileos de la Acrópolis ateniense. En lo alto, la Cuadriga: cuatro caballos tirando del carro de Victoria, esculpida en bronce en 1793. Napoleón se la llevó a París en 1806. Volvió en 1814. Desde entonces no se ha movido.\n\nDurante veintiocho años, la Puerta estuvo en la franja de la muerte del Muro, inaccesible desde ambos lados. Pero eso todavía no ha pasado. Hoy es 1934 y yo la miro desde este lado por última vez.\n\nEn las maletas llevo: el vestido azul marino que mi madre me cosió para mi primera actuación. Las fotografías de mis vecinos. La partitura de la primera canción que canté la noche que Heinrich me vio. Un libro de Heine, quemado por los bordes pero legible.\n\nNo llevo: el escenario del Silhouetten. Los adoquines del Monbijoupark. La voz de mi madre. Esas cosas no caben en una maleta. Se quedan.\n\nMiro la Cuadriga en lo alto y pienso: la victoria no pertenece a quienes gritan más fuerte, sino a quienes sobreviven para contar lo que ocurrió.\n\nPasamos bajo la Puerta. En dirección a la estación. En dirección a París.\n\nCamina hacia el oeste por la Strasse des 17. Juni. La Columna de la Victoria está al final.',
    'EN': 'January 1934. It is cold.\n\nHeinrich and I are standing here, in front of the Gate, with two suitcases.\n\nThe Brandenburg Gate was built between 1788 and 1791 as a symbol of peace — its original name was Friedenstor, the Gate of Peace. It is 26 metres tall and 65 wide, with six pairs of Doric columns inspired by the Propylaea of the Athenian Acropolis. At the top, the Quadriga: four horses pulling the chariot of Victoria, cast in bronze in 1793. Napoleon took it to Paris in 1806 as a war trophy. It came back in 1814. It hasn\'t moved since.\n\nFor twenty-eight years, the Gate would stand in the death strip of the Wall, inaccessible from both sides. But that hasn\'t happened yet. Tonight it is 1934 and I am looking at it from this side for the last time.\n\nIn my suitcases I carry: the navy blue dress my mother sewed for my first performance. Photographs of my neighbours. The score of the first song I sang the night Heinrich saw me. A book by Heine, burnt at the edges but still legible.\n\nI do not carry: the stage at the Silhouetten. The cobblestones of Monbijoupark. My mother\'s voice. Those things don\'t fit in a suitcase. They stay.\n\nI look at the Quadriga above and think: victory doesn\'t belong to those who shout loudest, but to those who survive to tell what happened.\n\nWe pass under the Gate. Toward the station. Toward Paris.\n\nWalk west along Strasse des 17. Juni. The Victory Column is at the end.',
    'DE': 'Januar 1934. Es ist kalt.\n\nHeinrich und ich stehen hier vor dem Tor mit zwei Koffern.\n\nDas Brandenburger Tor wurde zwischen 1788 und 1791 als Friedenssymbol errichtet – sein ursprünglicher Name war Friedenstor. Es ist 26 Meter hoch und 65 Meter breit, mit sechs Paaren dorischer Säulen, inspiriert von den Propyläen der Athener Akropolis. Oben die Quadriga: vier Pferde, die den Wagen der Victoria ziehen, 1793 in Bronze gegossen. Napoleon entführte sie 1806 nach Paris. Sie kehrte 1814 zurück. Seitdem hat sie sich nicht mehr bewegt.\n\nAchtundzwanzig Jahre lang stand das Tor im Todesstreifen der Mauer, von beiden Seiten unzugänglich. Aber das ist noch nicht geschehen. Heute ist 1934 und ich schaue es von dieser Seite zum letzten Mal an.\n\nIn den Koffern: das marineblaue Kleid, das meine Mutter für meinen ersten Auftritt nähte. Die Fotografien meiner Nachbarn. Die Partitur des ersten Liedes, das ich in der Nacht sang, in der Heinrich mich sah. Ein Buch von Heine, an den Rändern versengt, aber lesbar.\n\nNicht dabei: die Bühne des Silhouetten. Das Pflaster des Monbijouparks. Die Stimme meiner Mutter. Diese Dinge passen nicht in einen Koffer. Sie bleiben.\n\nIch schaue zur Quadriga hinauf und denke: Der Sieg gehört nicht denen, die am lautesten schreien, sondern denen, die überleben, um zu erzählen, was geschah.\n\nWir gehen durch das Tor. Richtung Bahnhof. Richtung Paris.\n\nGeh nach Westen entlang der Straße des 17. Juni. Die Siegessäule ist am Ende.',
    'IT': 'Gennaio 1934. Fa freddo.\n\nHeinrich e io siamo in piedi qui davanti alla Porta con due valigie.\n\nLa Porta di Brandeburgo fu costruita tra il 1788 e il 1791 come simbolo di pace – il suo nome originale era Friedenstor. È alta 26 metri e larga 65, con sei coppie di colonne doriche ispirate ai Propilei dell\'Acropoli ateniese. In cima, la Quadriga: quattro cavalli che trainano il carro di Vittoria, fusa in bronzo nel 1793. Napoleone la portò a Parigi nel 1806. Tornò nel 1814. Da allora non si è più mossa.\n\nPer ventotto anni, la Porta rimase nella striscia della morte del Muro, inaccessibile da entrambi i lati. Ma questo non è ancora accaduto. Oggi è il 1934 e io la guardo da questo lato per l\'ultima volta.\n\nNelle valigie: il vestito blu marino che mia madre cucì per il mio primo spettacolo. Le fotografie dei miei vicini. Lo spartito della prima canzone che cantai la notte in cui Heinrich mi vide. Un libro di Heine, bruciato ai bordi ma leggibile.\n\nNon ci sono: il palcoscenico del Silhouetten. I ciottoli del Monbijoupark. La voce di mia madre. Queste cose non stanno in una valigia. Rimangono.\n\nGuardo la Quadriga in cima e penso: la vittoria non appartiene a chi urla più forte, ma a chi sopravvive per raccontare ciò che accadde.\n\nPassiamo sotto la Porta. In direzione della stazione. In direzione di Parigi.\n\nCammina verso ovest lungo la Strasse des 17. Juni. La Colonna della Vittoria è in fondo.',
  },
  'lena_09a': {
    'ES': 'Esta es la última parada.\n\nLa Siegessäule — la Columna de la Victoria — la construyeron en 1873 para celebrar las tres guerras de unificación alemana. Originalmente estaba frente al Reichstag. En 1939 Hitler la hizo trasladar aquí, al centro del Tiergarten, y la elevó de 51 a 67 metros añadiendo un tambor adicional, para que fuera visible desde más lejos. Fue parte del proyecto Germania — el plan de Albert Speer para convertir Berlín en la capital del mundo. La figura dorada en lo alto es Victoria, mirando hacia el oeste. La columna está recubierta con los cañones capturados a los enemigos vencidos.\n\nLa vi por primera vez en 1962, cuando volví a Berlín con mi hija Clara. Me quedé mirándola un momento largo. Luego dije: sigue aquí.\n\nClara preguntó: ¿eso te sorprende?\n\nDije: me sorprende que haya sobrevivido más que la mayoría de las personas que la construyeron.\n\nLos monumentos al poder sobreviven a los poderes que los levantan. Berlín está llena de cosas construidas por personas que creían que durarían para siempre — y que no duraron. Y sin embargo las cosas siguen aquí, mirando hacia el oeste, indiferentes.\n\nMorí en París en 1987, a los 84 años, rodeada de mi familia. La última cosa que dije fue en alemán. Nadie en la habitación entendió exactamente qué dije. Pero todos dijeron que sonó como el principio de una canción.\n\nEsa es mi historia. La de la que se fue. La que amó Berlín desde lejos con la intensidad específica de las cosas que no puedes tocar.\n\nBerlín es una ciudad que ha sido destruida y reconstruida tantas veces que ha aprendido a llevar sus cicatrices como ornamento. Una ciudad que no finge que su historia no ocurrió. Una ciudad que sobrevivió al Imperio, a la República, al nazismo, a los bombardeos, a la división, y sigue aquí — demasiado terca, demasiado contradictoria, demasiado viva para dejarse definir por ninguna de las versiones que otros intentaron imponerle.\n\nHas llegado al final de mi recorrido. Berlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'This is the last stop.\n\nThe Siegessäule — the Victory Column — was built in 1873 to celebrate the three wars of German unification. It originally stood in front of the Reichstag. In 1939 Hitler had it moved here, to the centre of the Tiergarten, and raised from 51 to 67 metres by adding an extra drum section, so it could be seen from further away. It was part of the Germania project — Albert Speer\'s plan to turn Berlin into the capital of the world. The golden figure at the top is Victoria, looking west. The column is clad with cannons captured from defeated enemies.\n\nI saw it for the first time in 1962, when I came back to Berlin with my daughter Clara. I stood looking at it for a long moment. Then I said: it\'s still here.\n\nClara asked: does that surprise you?\n\nI said: it surprises me that it outlasted most of the people who built it.\n\nMonuments to power outlast the powers that raise them. Berlin is full of things built by people who believed they would last forever — and they didn\'t. And yet the things remain, looking west, indifferent.\n\nI died in Paris in 1987, aged 84, surrounded by my family. The last thing I said was in German. No one in the room understood exactly what I said. But everyone said it sounded like the beginning of a song.\n\nThat is my story. The one who left. The one who loved Berlin from a distance with the specific intensity of things you cannot touch.\n\nBerlin is a city that has been destroyed and rebuilt so many times it has learned to wear its scars as ornament. A city that does not pretend its history didn\'t happen. A city that survived the Empire, the Republic, Nazism, the bombs, the division, and is still here — too stubborn, too contradictory, too alive to be defined by any of the versions others tried to impose on it.\n\nYou have reached the end of my journey. Berlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Das ist die letzte Station.\n\nDie Siegessäule wurde 1873 errichtet, um die drei deutschen Einigungskriege zu feiern. Ursprünglich stand sie vor dem Reichstag. 1939 ließ Hitler sie hierher versetzen, in die Mitte des Tiergartens, und erhöhte sie von 51 auf 67 Meter, indem er ein weiteres Trommelgeschoss hinzufügte, damit sie von weiter sichtbar wäre. Es war Teil des Projekts Germania – Albert Speers Plan, Berlin zur Welthauptstadt zu machen. Die goldene Figur oben ist Victoria, mit Blick nach Westen. Die Säule ist mit den Kanonen überzogener Feinde bedeckt.\n\nIch sah sie zum ersten Mal 1962, als ich mit meiner Tochter Clara nach Berlin zurückkehrte. Ich betrachtete sie einen langen Augenblick. Dann sagte ich: Sie steht noch.\n\nClara fragte: Überrascht dich das?\n\nIch sagte: Es überrascht mich, dass sie mehr überlebt hat als die meisten Menschen, die sie erbaut haben.\n\nDenkmäler der Macht überdauern die Mächte, die sie errichteten. Berlin ist voll von Dingen, die von Menschen gebaut wurden, die glaubten, sie würden ewig dauern – und die nicht dauerten. Und dennoch stehen die Dinge noch hier, mit Blick nach Westen, gleichgültig.\n\nIch starb 1987 in Paris, mit 84 Jahren, umgeben von meiner Familie. Das Letzte, was ich sagte, war auf Deutsch. Niemand im Zimmer verstand genau, was ich sagte. Aber alle sagten, es klang wie der Anfang eines Liedes.\n\nDas ist meine Geschichte. Die der Weggegangenen. Die, die Berlin aus der Ferne mit der spezifischen Intensität der Dinge liebte, die man nicht berühren kann.\n\nBerlin ist eine Stadt, die so oft zerstört und wieder aufgebaut wurde, dass sie gelernt hat, ihre Narben als Schmuck zu tragen. Eine Stadt, die nicht so tut, als wäre ihre Geschichte nicht geschehen. Eine Stadt, die das Kaiserreich, die Republik, den Nationalsozialismus, die Bombardierungen, die Teilung überlebt hat und noch immer hier ist – zu stur, zu widersprüchlich, zu lebendig, um sich von einer der Versionen definieren zu lassen, die andere ihr aufzwingen wollten.\n\nDu hast das Ende meines Rundgangs erreicht. Berlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Questa è l\'ultima tappa.\n\nLa Siegessäule – la Colonna della Vittoria – fu costruita nel 1873 per celebrare le tre guerre di unificazione tedesca. Originariamente si trovava davanti al Reichstag. Nel 1939 Hitler la fece spostare qui, al centro del Tiergarten, e la elevò da 51 a 67 metri aggiungendo un tamburo supplementare, perché fosse visibile da più lontano. Faceva parte del progetto Germania – il piano di Albert Speer per trasformare Berlino nella capitale del mondo. La figura dorata in cima è Vittoria, con lo sguardo rivolto a ovest. La colonna è rivestita con i cannoni catturati ai nemici sconfitti.\n\nLa vidi per la prima volta nel 1962, quando tornai a Berlino con mia figlia Clara. La guardai a lungo. Poi dissi: è ancora qui.\n\nClara chiese: ti sorprende?\n\nDissi: mi sorprende che abbia sopravvissuto a più persone di quante ne abbiano costruita.\n\nI monumenti al potere sopravvivono ai poteri che li erigono. Berlino è piena di cose costruite da persone che credevano sarebbero durate per sempre – e che non durarono. Eppure le cose sono ancora qui, con lo sguardo rivolto a ovest, indifferenti.\n\nMorì a Parigi nel 1987, a 84 anni, circondata dalla mia famiglia. L\'ultima cosa che dissi fu in tedesco. Nessuno nella stanza capì esattamente cosa dissi. Ma tutti dissero che sembrava l\'inizio di una canzone.\n\nQuesta è la mia storia. Quella di chi se ne andò. Chi amò Berlino da lontano con l\'intensità specifica delle cose che non puoi toccare.\n\nBerlino è una città che è stata distrutta e ricostruita così tante volte da aver imparato a portare le proprie cicatrici come ornamento. Una città che non finge che la sua storia non sia accaduta. Una città che sopravvisse all\'Impero, alla Repubblica, al nazismo, ai bombardamenti, alla divisione, ed è ancora qui – troppo testarda, troppo contraddittoria, troppo viva per lasciarsi definire da nessuna delle versioni che altri cercarono di imporle.\n\nHai raggiunto la fine del mio percorso. Berlino è ancora qui. E anche tu. Per ora basta così.',
  },
  'lena_07b': {
    'ES': 'Enero de 1934. Hace frío.\n\nEstoy sola en el Lustgarten, sentada en un banco frente al río. Heinrich se fue hace tres semanas. Lo convencí de que se fuera sin esperarme — que era más seguro, que lo seguiría en cuanto arreglara algunas cosas. Esas cosas resultaron no ser arreglables.\n\nEl Lustgarten tiene detrás el Berliner Dom y delante el Spree. Entre 1573 y 1713 fue el jardín de placer de los electores de Brandeburgo — huerta, jardín botánico, campo de maniobras, parque público. En 1934 es el espacio donde los nazis celebrarán sus concentraciones masivas — decenas de miles de personas con antorchas y banderas frente a la misma catedral que siempre odié por lo que representaba. Un año después pavimentarán el césped con adoquines. La plaza de placer se convertirá en plaza de poder.\n\nPero esta tarde de enero todavía hay hierba. Y estoy sentada en ella.\n\n¿Por qué me quedé? Es una pregunta que me haré el resto de mi vida. Me quedé porque mi madre estaba enferma. Porque mis vecinos tenían miedo. Porque pensé que lo peor ya había pasado. Y porque Berlín era mía: sus calles, sus adoquines, su olor a río y a carbón y a café.\n\nUno no deja su ciudad tan fácilmente aunque su ciudad se haya convertido en algo que ya no reconoce.\n\nEl Spree pasa frente a mí, gris y quieto. Los ríos no tienen opiniones sobre la historia. Solo siguen fluyendo.\n\nCamina hacia el norte por la orilla de la isla. El Neues Museum está a cuatro minutos.',
    'EN': 'January 1934. It is cold.\n\nI am alone in the Lustgarten, sitting on a bench facing the river. Heinrich left three weeks ago. I convinced him to go without waiting for me — that it was safer, that I would follow in a few weeks once I sorted some things out. Those things turned out not to be sortable.\n\nThe Lustgarten has the Berliner Dom behind it and the Spree in front. Between 1573 and 1713 it was the pleasure garden of the Electors of Brandenburg — kitchen garden, botanical garden, military drill ground, public park. In 1934 it is the space where the Nazis will hold their mass gatherings — tens of thousands of people with torches and flags in front of the same cathedral I always hated for what it represented. A year later they will pave the grass with cobblestones. The pleasure garden will become a power square.\n\nBut on this January afternoon there is still grass. And I am sitting on it.\n\nWhy did I stay? It is a question I will ask myself for the rest of my life. I stayed because my mother was ill. Because my neighbours were frightened. Because I thought the worst had already passed. And because Berlin was mine: its streets, its cobblestones, its smell of river and coal and coffee.\n\nYou don\'t leave your city easily, even when your city has become something you no longer recognise.\n\nThe Spree flows in front of me, grey and quiet. Rivers have no opinions about history. They just keep flowing.\n\nWalk north along the island\'s embankment. The Neues Museum is four minutes away.',
    'DE': 'Januar 1934. Es ist kalt.\n\nIch bin allein im Lustgarten, auf einer Bank vor dem Fluss sitzend. Heinrich ist vor drei Wochen gegangen. Ich hatte ihn überredet, ohne mich zu gehen – es sei sicherer so, ich würde folgen, sobald einige Dinge geregelt seien. Diese Dinge erwiesen sich als nicht regelbar.\n\nDer Lustgarten hat hinter sich den Berliner Dom und vor sich die Spree. Zwischen 1573 und 1713 war er der Vergnügungsgarten der Kurfürsten von Brandenburg – Gemüsegarten, botanischer Garten, Exerzierfeld, öffentlicher Park. 1934 ist er ein offener Raum ohne klare Funktion im Herzen des sozialistischen Berlins, wie eine Lücke, die niemand so recht zu füllen weiß. Ein Jahr später werden sie den Rasen mit Pflastersteinen bedecken. Der Lustgarten wird zum Machtplatz.\n\nAber an diesem Januarnachmittag gibt es noch Gras. Und ich sitze darin.\n\nWarum bin ich geblieben? Das ist eine Frage, die ich mir den Rest meines Lebens stellen werde. Ich blieb, weil meine Mutter krank war. Weil meine Nachbarn Angst hatten. Weil ich dachte, das Schlimmste sei bereits geschehen. Und weil Berlin meins war: seine Straßen, sein Pflaster, sein Geruch nach Fluss und Kohle und Kaffee.\n\nMan verlässt seine Stadt nicht so leicht, auch wenn sie zu etwas geworden ist, das man nicht mehr erkennt.\n\nDie Spree fließt vor mir, grau und still. Flüsse haben keine Meinungen über Geschichte. Sie fließen einfach weiter.\n\nGeh nach Norden entlang der Inselufer. Das Neue Museum ist vier Minuten entfernt.',
    'IT': 'Gennaio 1934. Fa freddo.\n\nSono sola nel Lustgarten, seduta su una panchina davanti al fiume. Heinrich se n\'è andato tre settimane fa. L\'avevo convinto ad andarsene senza aspettarmi – era più sicuro così, l\'avrei seguito non appena avessi sistemato alcune cose. Quelle cose si rivelarono impossibili da sistemare.\n\nIl Lustgarten ha alle spalle il Berliner Dom e davanti la Spree. Tra il 1573 e il 1713 fu il giardino del piacere degli elettori del Brandeburgo – orto, giardino botanico, campo di manovra, parco pubblico. Nel 1934 è uno spazio aperto senza una funzione chiara nel centro della Berlino socialista, come un vuoto che nessuno sa bene come riempire. Un anno dopo lastricheranno il prato con i selci. Il giardino del piacere diventerà piazza del potere.\n\nMa questo pomeriggio di gennaio c\'è ancora l\'erba. E io sono seduta su di essa.\n\nPerché sono rimasta? È una domanda che mi porrò per il resto della mia vita. Sono rimasta perché mia madre era malata. Perché i miei vicini avevano paura. Perché pensavo che il peggio fosse già passato. E perché Berlino era mia: le sue strade, i suoi ciottoli, il suo odore di fiume e carbone e caffè.\n\nNon si lascia la propria città così facilmente anche quando si è trasformata in qualcosa che non si riconosce più.\n\nLa Spree scorre davanti a me, grigia e quieta. I fiumi non hanno opinioni sulla storia. Continuano semplicemente a scorrere.\n\nCammina verso nord lungo la riva dell\'isola. Il Neues Museum è a quattro minuti.',
  },
  'lena_08b': {
    'ES': 'Conozco este museo de memoria.\n\nLo construyeron entre 1843 y 1855, como expansión de la Museumsinsel. Sus paredes interiores estaban cubiertas de frescos que recorrían la historia de la humanidad desde Egipto hasta Roma. En 1945 una bomba lo dejó en ruinas — el techo colapsado, las esculturas enterradas bajo escombros, los frescos destruidos para siempre. Permaneció cerrado durante sesenta años. Cuando reabrió en 2009, el arquitecto David Chipperfield tomó la decisión deliberada de no restaurarlo por completo: las cicatrices de la guerra quedaron visibles, integradas en el nuevo diseño. Las heridas como parte del edificio. Las heridas como parte de la historia.\n\nEn el tercer piso hay un busto que viajó desde Egipto en 1913. Nefertiti, reina de Egipto, esposa de Akhenaton. Esculpida hace más de 3.300 años. El cuello largo, la corona azul, los ojos asimétricos — el derecho sin pupila, el izquierdo perfecto. Una expresión que nunca supe describir del todo. No es orgullo. No es tristeza. Es la cara de alguien que ha visto demasiado y ha decidido que eso no le va a quitar la dignidad.\n\nSobreviví la guerra en un sótano de Prenzlauer Berg. Cuando salí, Berlín estaba en ruinas. El Silhouetten no existía. Mi madre había muerto en 1941 y no pude estar con ella al final. Fue la cosa que más me pesó el resto de mi vida.\n\nPero estaba viva.\n\nMe senté frente a Nefertiti en 1957 y pensé: tres mil años. Dos guerras mundiales. Un muro que va a partir esta ciudad en dos. Y tú sigues aquí con esa cara.\n\nAlgo en eso me pareció la respuesta más honesta que había recibido nunca.\n\nSal por la entrada norte. El Pergamon Panorama está a doscientos metros.',
    'EN': 'I know this museum by heart.\n\nThey built it between 1843 and 1855, as an expansion of the Museumsinsel. Its interior walls were covered in frescoes tracing the history of humanity from Egypt to Rome. In 1945 a bomb left it in ruins — the roof collapsed, sculptures buried under rubble, frescoes destroyed forever. It remained closed for sixty years. When it reopened in 2009, the architect David Chipperfield made the deliberate decision not to restore it completely: the scars of the war were left visible, integrated into the new design. The wounds as part of the building. The wounds as part of the history.\n\nOn the third floor there is a bust that travelled from Egypt in 1913. Nefertiti, Queen of Egypt, wife of Akhenaten. Sculpted more than 3,300 years ago. The long neck, the blue crown, the asymmetric eyes — the right without a pupil, the left perfect. An expression I could never quite describe. It is not pride. It is not sadness. It is the face of someone who has seen too much and decided that won\'t take away her dignity.\n\nI survived the war in a basement in Prenzlauer Berg. When I came out, Berlin was in ruins. The Silhouetten no longer existed. My mother had died in 1941 and I hadn\'t been able to be with her at the end. That was the thing that weighed most heavily on me for the rest of my life.\n\nBut I was alive.\n\nI sat in front of Nefertiti in 1957 and thought: three thousand years. Two world wars. A wall about to divide this city in two. And you are still here with that face.\n\nSomething in that seemed to me the most honest answer I had ever received.\n\nLeave through the north entrance. The Pergamon Panorama is two hundred metres away.',
    'DE': 'Ich kenne dieses Museum auswendig.\n\nEs wurde zwischen 1843 und 1855 als Erweiterung der Museumsinsel gebaut. Seine Innenwände waren mit Fresken bedeckt, die die Geschichte der Menschheit von Ägypten bis Rom nachzeichneten. 1945 ließ eine Bombe es in Trümmer fallen – das Dach eingestürzt, die Skulpturen unter Schutt begraben, die Fresken für immer zerstört. Sechzig Jahre lang blieb es geschlossen. Als es 2009 wiedereröffnete, traf der Architekt David Chipperfield die bewusste Entscheidung, es nicht vollständig zu restaurieren: die Kriegsnarben blieben sichtbar, in das neue Design integriert. Die Wunden als Teil des Gebäudes. Die Wunden als Teil der Geschichte.\n\nIm dritten Stockwerk befindet sich eine Büste, die 1913 aus Ägypten hierher gebracht wurde. Nofretete, Königin Ägyptens, Gemahlin Echnatons. Vor mehr als 3.300 Jahren erschaffen. Der lange Hals, die blaue Krone, die asymmetrischen Augen – das rechte ohne Pupille, das linke perfekt. Ein Ausdruck, den ich nie ganz zu beschreiben wusste. Es ist kein Stolz. Es ist keine Trauer. Es ist das Gesicht von jemandem, der zu viel gesehen hat und sich entschieden hat, dass das seine Würde nicht rauben soll.\n\nIch überlebte den Krieg in einem Keller in Prenzlauer Berg. Als ich herauskam, lag Berlin in Trümmern. Das Silhouetten existierte nicht mehr. Meine Mutter war 1941 gestorben und ich hatte nicht bei ihr sein können bis zum Schluss. Das war die Sache, die mich den Rest meines Lebens am schwersten lastete.\n\nAber ich lebte.\n\nIch saß 1957 vor Nofretete und dachte: Dreitausend Jahre. Zwei Weltkriege. Eine Mauer, die diese Stadt in zwei teilen wird. Und du stehst noch hier mit diesem Gesicht.\n\nIrgendwie schien mir das die ehrlichste Antwort, die ich je bekommen hatte.\n\nGeh nach Norden durch den Eingang. Das Pergamon-Panorama ist zweihundert Meter entfernt.',
    'IT': 'Conosco questo museo a memoria.\n\nFu costruito tra il 1843 e il 1855 come espansione della Museumsinsel. Le sue pareti interne erano coperte di affreschi che ripercorrevano la storia dell\'umanità dall\'Egitto a Roma. Nel 1945 una bomba lo ridusse in macerie – il tetto crollato, le sculture sepolte sotto le macerie, gli affreschi distrutti per sempre. Rimase chiuso per sessant\'anni. Quando riaprì nel 2009, l\'architetto David Chipperfield prese la decisione deliberata di non restaurarlo completamente: le cicatrici della guerra rimasero visibili, integrate nel nuovo progetto. Le ferite come parte dell\'edificio. Le ferite come parte della storia.\n\nAl terzo piano c\'è un busto che arrivò dall\'Egitto nel 1913. Nefertiti, regina d\'Egitto, sposa di Akhenaton. Scolpita più di 3.300 anni fa. Il collo lungo, la corona blu, gli occhi asimmetrici – il destro senza pupilla, il sinistro perfetto. Un\'espressione che non seppi mai descrivere del tutto. Non è orgoglio. Non è tristezza. È il viso di qualcuno che ha visto troppo e ha deciso che questo non gli toglierà la dignità.\n\nSopravvissi alla guerra in uno scantinato di Prenzlauer Berg. Quando uscii, Berlino era in macerie. Il Silhouetten non esisteva più. Mia madre era morta nel 1941 e non avevo potuto essere con lei alla fine. Fu la cosa che mi pesò di più per il resto della vita.\n\nMa ero viva.\n\nNel 1957 mi sedetti davanti a Nefertiti e pensai: tremila anni. Due guerre mondiali. Un muro che dividerà questa città in due. E tu sei ancora qui con quella faccia.\n\nIn qualche modo quella mi sembrò la risposta più onesta che avessi mai ricevuto.\n\nEsci dall\'ingresso nord. Il Pergamon Panorama è a duecento metri.',
  },
  'lena_09b': {
    'ES': 'Esta es la última parada.\n\nEl Museo de Pérgamo guarda lo que ningún otro museo en el mundo puede guardar: arquitecturas enteras transportadas desde sus lugares de origen. El Altar de Pérgamo, construido en el siglo II a.C. — sus frisos de mármol representan la batalla de los dioses contra los gigantes con una energía que después de veintidós siglos todavía no se ha agotado. La Puerta de Ishtar de Babilonia, levantada por Nabucodonosor II en el siglo VI a.C., recubierta de azulejos azules con leones y dragones. La Fachada del Mercado de Mileto, del siglo II d.C. Tres imperios. Tres continentes. Tres historias que sobrevivieron a todos los poderes que intentaron borrarlas.\n\nPensaba en eso en los años difíciles. Que la Puerta de Ishtar había sobrevivido a Nabucodonosor, a Alejandro Magno, a dos guerras mundiales, y seguía aquí — mirando a los turistas con la misma indiferencia con que había mirado a los reyes.\n\nDespués de la guerra volví a cantar. En sótanos primero. Berlín se reconstruía cantando en sótanos, como siempre lo había hecho. Mi voz había cambiado — más oscura, más lenta, con más peso. Pero seguía teniendo esa cosa rota dentro que Heinrich había reconocido la primera noche.\n\nHeinrich me escribió desde París en 1946. Nos vimos una última vez en 1955. Tomamos un café. Nos despedimos con un abrazo que duró más de lo normal.\n\nMorí en Berlín Oriental en 1978, a los 75 años. Nunca dejé la ciudad. Hasta el final, cuando me preguntaban por qué me había quedado, daba siempre la misma respuesta: alguien tenía que quedarse para poder contar lo que ocurrió.\n\nBerlín es una ciudad que guarda sus heridas a la vista. Que no restaura lo que fue destruido sin dejar visible la destrucción. Que construye memoriales donde hubo horror y parques donde hubo palacios y museos donde hubo ruinas. Una ciudad que ha aprendido, a fuerza de catástrofes, que la memoria no es una carga — es lo único que impide repetir lo mismo.\n\nHas llegado al final de mi recorrido. Berlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'This is the last stop.\n\nThe Pergamon Museum holds what no other museum in the world can hold: entire architectures transported from their places of origin. The Pergamon Altar, built in the 2nd century BC — its marble friezes depict the battle of gods against giants with an energy that after twenty-two centuries has still not exhausted itself. The Ishtar Gate of Babylon, erected by Nebuchadnezzar II in the 6th century BC, covered in blue tiles with lions and dragons. The Market Gate of Miletus, from the 2nd century AD. Three empires. Three continents. Three stories that survived all the powers that tried to erase them.\n\nI thought about that in the hard years. That the Ishtar Gate had outlasted Nebuchadnezzar, Alexander the Great, two world wars, and was still here — looking at tourists with the same indifference with which it had looked at kings.\n\nAfter the war I sang again. In basements first. Berlin was rebuilding itself singing in basements, as it always had. My voice had changed — darker, slower, heavier. But it still had that broken thing inside that Heinrich had recognised on the first night.\n\nHeinrich wrote from Paris in 1946. We met one last time in 1955. We had coffee. We said goodbye with an embrace that lasted longer than normal.\n\nI died in East Berlin in 1978, aged 75. I never left the city. Until the end, when people asked me why I had stayed, I always gave the same answer: someone had to stay to be able to tell what happened.\n\nBerlin is a city that keeps its wounds in plain sight. That does not restore what was destroyed without leaving the destruction visible. That builds memorials where there was horror and parks where there were palaces and museums where there were ruins. A city that has learned, through catastrophe, that memory is not a burden — it is the only thing that prevents repeating the same thing.\n\nYou have reached the end of my journey. Berlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Das ist die letzte Station.\n\nDas Pergamonmuseum bewahrt, was kein anderes Museum der Welt bewahren kann: ganze Architekturen, die von ihren Ursprungsorten hierher transportiert wurden. Der Pergamonaltar, erbaut im 2. Jahrhundert v. Chr. – seine Marmorfriesel stellen die Schlacht der Götter gegen die Giganten dar mit einer Energie, die nach zweiundzwanzig Jahrhunderten noch nicht erschöpft ist. Das Ischtar-Tor von Babylon, errichtet von Nebukadnezar II. im 6. Jahrhundert v. Chr., bedeckt mit blauen Kacheln mit Löwen und Drachen. Die Markttor von Milet, aus dem 2. Jahrhundert n. Chr. Drei Imperien. Drei Kontinente. Drei Geschichten, die alle Mächte überlebten, die sie auszulöschen versuchten.\n\nIch dachte in den schweren Jahren daran. Dass das Ischtar-Tor Nebukadnezar, Alexander den Großen, zwei Weltkriege überlebt hatte und noch hier stand – und die Touristen mit derselben Gleichgültigkeit betrachtete, mit der es einst die Könige betrachtet hatte.\n\nNach dem Krieg begann ich wieder zu singen. Erst in Kellern. Berlin baute sich singend in Kellern wieder auf, wie es das immer getan hatte. Meine Stimme hatte sich verändert – dunkler, langsamer, mit mehr Gewicht. Aber sie hatte noch immer dieses zerbrochene Etwas darin, das Heinrich in der ersten Nacht erkannt hatte.\n\nHeinrich schrieb mir 1946 aus Paris. Wir sahen uns ein letztes Mal 1955. Wir tranken einen Kaffee. Wir verabschiedeten uns mit einer Umarmung, die länger dauerte als normal.\n\nIch starb 1978 in Ostberlin, mit 75 Jahren. Ich verließ die Stadt nie. Bis zum Ende, wenn man mich fragte, warum ich geblieben sei, gab ich immer dieselbe Antwort: Jemand musste bleiben, um erzählen zu können, was geschehen war.\n\nBerlin ist eine Stadt, die ihre Wunden offen trägt. Die das Zerstörte nicht restauriert, ohne die Zerstörung sichtbar zu lassen. Die Mahnmäler dort baut, wo Schrecken war, und Parks, wo Paläste waren, und Museen, wo Ruinen waren. Eine Stadt, die durch Katastrophen gelernt hat, dass Erinnerung keine Last ist – sondern das Einzige, das verhindert, dasselbe zu wiederholen.\n\nDu hast das Ende meines Rundgangs erreicht. Berlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Questa è l\'ultima tappa.\n\nIl Museo di Pergamo custodisce ciò che nessun altro museo al mondo può custodire: architetture intere trasportate dai loro luoghi d\'origine. L\'Altare di Pergamo, costruito nel II secolo a.C. – i suoi fregi di marmo raffigurano la battaglia degli dèi contro i giganti con un\'energia che dopo ventidue secoli non si è ancora esaurita. La Porta di Ishtar di Babilonia, eretta da Nabucodonosor II nel VI secolo a.C., rivestita di mattonelle azzurre con leoni e draghi. La Porta del Mercato di Mileto, del II secolo d.C. Tre imperi. Tre continenti. Tre storie che sopravvissero a tutti i poteri che cercarono di cancellarle.\n\nCi pensavo negli anni difficili. Che la Porta di Ishtar aveva sopravvissuto a Nabucodonosor, ad Alessandro Magno, a due guerre mondiali, ed era ancora qui – guardando i turisti con la stessa indifferenza con cui aveva guardato i re.\n\nDopo la guerra tornai a cantare. Prima in scantinati. Berlino si ricostruiva cantando in scantinati, come aveva sempre fatto. La mia voce era cambiata – più scura, più lenta, con più peso. Ma aveva ancora quella cosa rotta dentro che Heinrich aveva riconosciuto la prima notte.\n\nHeinrich mi scrisse da Parigi nel 1946. Ci vedemmo un\'ultima volta nel 1955. Prendemmo un caffè. Ci salutammo con un abbraccio che durò più del normale.\n\nMorì a Berlino Est nel 1978, a 75 anni. Non lasciai mai la città. Fino alla fine, quando mi chiedevano perché fossi rimasta, davo sempre la stessa risposta: qualcuno doveva restare per poter raccontare ciò che era accaduto.\n\nBerlino è una città che porta le proprie ferite in vista. Che non restaura ciò che fu distrutto senza lasciare visibile la distruzione. Che costruisce memoriali dove ci fu orrore, parchi dove c\'erano palazzi e musei dove c\'erano rovine. Una città che ha imparato, a forza di catastrofi, che la memoria non è un peso – è l\'unica cosa che impedisce di ripetere le stesse cose.\n\nHai raggiunto la fine del mio percorso. Berlino è ancora qui. E anche tu. Per ora basta così.',
  },
  'klaus_01': {
    'ES': 'Berlín Oriental, 17 de noviembre de 1975.\n\nSon las 7:42 de la mañana. Me llamo Klaus Brenner. Y todavía no sé que este es mi último día.\n\nLlevo once años trabajando para el Ministerium für Staatssicherheit. Once años mirando a las personas sin que ellas lo sepan. Siguiéndolas. Anotando sus conversaciones, sus visitas, sus silencios. Once años aprendiendo que la lealtad no es una virtud — es una herramienta que el Estado afila y usa cuando le conviene.\n\nEsta mañana tengo una misión. Simple, dicen. Rutinaria. Pero hay algo en la forma en que mi superior pronunció esa palabra — rutinaria — que me sonó falsa.\n\nMiro el Weltzeituhr. El reloj mundial fue instalado aquí en 1969 y marca la hora en veinticuatro zonas horarias simultáneamente — Moscú, La Habana, Hanói, Pekín. Las ciudades del mundo correcto, el que ganó. Lo rodea una ciudad construida desde cero sobre las ruinas de la guerra: la Alexanderplatz socialista con su geometría de hormigón, sus bloques uniformes, su escala diseñada para hacer sentir al individuo pequeño ante la grandeza del colectivo. El arquitecto Hermann Henselmann proyectó esta plaza como declaración ideológica. Cada piedra dice lo mismo: el Estado es permanente. El individuo es temporal.\n\nLlevo once años viviendo en esa declaración.\n\nEsta mañana la miro de otra manera.\n\nCamina hacia la Torre de la Televisión. Está a tres minutos.',
    'EN': 'East Berlin, 17 November 1975.\n\nIt is 7:42 in the morning. My name is Klaus Brenner. And I don\'t yet know that this is my last day.\n\nI have spent eleven years working for the Ministerium für Staatssicherheit. Eleven years watching people without their knowing. Following them. Recording their conversations, their visits, their silences. Eleven years learning that loyalty is not a virtue — it is a tool the State sharpens and uses when convenient.\n\nThis morning I have a mission. Simple, they say. Routine. But there was something in the way my superior pronounced that word — routine — that sounded false to me.\n\nI look at the Weltzeituhr. The world clock was installed here in 1969 and shows the time in twenty-four time zones simultaneously — Moscow, Havana, Hanoi, Beijing. The cities of the right world, the one that won. Around it stands a city built from scratch on the ruins of the war: the socialist Alexanderplatz with its concrete geometry, its uniform blocks, its scale designed to make the individual feel small before the grandeur of the collective. The architect Hermann Henselmann conceived this square as an ideological declaration. Every stone says the same thing: the State is permanent. The individual is temporary.\n\nI have spent eleven years living inside that declaration.\n\nThis morning I look at it differently.\n\nWalk toward the Television Tower. It is three minutes away.',
    'DE': 'Ostberlin, 17. November 1975.\n\nEs ist 7:42 Uhr morgens. Ich heiße Klaus Brenner. Und ich weiß noch nicht, dass dies mein letzter Tag ist.\n\nSeit elf Jahren arbeite ich für das Ministerium für Staatssicherheit. Elf Jahre lang Menschen beobachten, ohne dass sie es wissen. Ihnen folgen. Ihre Gespräche, ihre Besuche, ihre Schweigen notieren. Elf Jahre damit verbracht zu lernen, dass Loyalität keine Tugend ist – sie ist ein Werkzeug, das der Staat schärft und benutzt, wenn es ihm passt.\n\nHeute Morgen habe ich einen Auftrag. Einfach, sagen sie. Routine. Aber da ist etwas in der Art, wie mein Vorgesetzter das Wort aussprach – Routine –, das falsch klang.\n\nIch schaue auf die Weltzeituhr. Die Weltzeituhr wurde 1969 hier aufgestellt und zeigt gleichzeitig vierundzwanzig Zeitzonen an – Moskau, Havanna, Hanoi, Peking. Die Städte der richtigen Welt, der, die gewann. Sie steht inmitten einer Stadt, die von Grund auf neu auf den Trümmern des Krieges gebaut wurde: der sozialistische Alexanderplatz mit seiner Betongeometrie, seinen gleichförmigen Blöcken, seiner Maßstäblichkeit, die darauf ausgelegt ist, das Individuum vor der Größe des Kollektivs klein erscheinen zu lassen. Der Architekt Hermann Henselmann entwarf diesen Platz als ideologische Aussage. Jeder Stein sagt dasselbe: Der Staat ist dauerhaft. Das Individuum ist vorübergehend.\n\nElf Jahre lang habe ich in dieser Aussage gelebt.\n\nHeute Morgen schaue ich sie anders an.\n\nGeh zum Fernsehturm. Er ist drei Minuten entfernt.',
    'IT': 'Berlino Est, 17 novembre 1975.\n\nSono le 7:42 del mattino. Mi chiamo Klaus Brenner. E non so ancora che questo è il mio ultimo giorno.\n\nDa undici anni lavoro per il Ministerium für Staatssicherheit. Undici anni a osservare le persone senza che lo sappiano. A seguirle. A registrare le loro conversazioni, le loro visite, i loro silenzi. Undici anni imparando che la lealtà non è una virtù – è uno strumento che lo Stato affila e usa quando gli conviene.\n\nStamattina ho una missione. Semplice, dicono. Routine. Ma c\'è qualcosa nel modo in cui il mio superiore ha pronunciato quella parola – routine – che suonava falso.\n\nGuardo il Weltzeituhr. L\'orologio mondiale fu installato qui nel 1969 e segna l\'ora in ventiquattro fusi orari simultaneamente – Mosca, L\'Avana, Hanoi, Pechino. Le città del mondo giusto, quello che vinse. Lo circonda una città costruita da zero sulle rovine della guerra: l\'Alexanderplatz socialista con la sua geometria di cemento, i suoi blocchi uniformi, la sua scala progettata per far sentire l\'individuo piccolo davanti alla grandezza del collettivo. L\'architetto Hermann Henselmann progettò questa piazza come dichiarazione ideologica. Ogni pietra dice la stessa cosa: lo Stato è permanente. L\'individuo è temporaneo.\n\nDa undici anni vivo in quella dichiarazione.\n\nStamattina la guardo in modo diverso.\n\nCammina verso la Torre della Televisione. È a tre minuti.',
  },
  'klaus_02': {
    'ES': 'La Torre de la Televisión tiene 368 metros. Se puede ver desde cualquier punto de Berlín Oriental — y desde Berlín Occidental también. Eso no es un accidente.\n\nFue construida entre 1965 y 1969 por el arquitecto Hermann Henselmann y el ingeniero Günter Franke. El Estado la concibió como respuesta visible al Funkturm del oeste — 368 metros de acero y hormigón para decir: nosotros también podemos construir el futuro. El problema fue que cuando el sol da en la esfera de acero inoxidable a cierto ángulo, aparece un reflejo en forma de cruz. Los berlineses occidentales llamaron al fenómeno la Rache des Papstes — la venganza del Papa. El Estado socialista ateo había construido, sin quererlo, una cruz brillante visible desde medio Berlín. Nunca encontraron la manera de eliminarla.\n\nSé exactamente cuánto costó construirla. En 1969, cuando la inauguraron, fui parte del equipo de seguridad. Mi primer trabajo importante. Tenía veintisiete años y creía en algo.\n\nAhora tengo treinta y ocho y no estoy seguro de qué creo.\n\nLa misión de hoy implica a Dieter Hofmann. Profesor de filosofía en la Humboldt. Llevo cuatro meses siguiéndolo. Sé que escucha radio occidental en su apartamento. Sé que tiene un hermano en Munich. Sé que sospecha que alguien lo vigila, porque ha empezado a mirar hacia atrás cuando camina. Lo sé porque yo lo enseñé a mirar hacia atrás. A todos los que vigilamos durante suficiente tiempo terminamos enseñándoles eso.\n\nLo que no sé es por qué me ordenaron terminar la vigilancia hoy. De golpe. Sin explicación.\n\nBaja hacia el Spree. El Marx-Engels-Forum está a cuatro minutos al oeste.',
    'EN': 'The Television Tower is 368 metres tall. It can be seen from any point in East Berlin — and from West Berlin too. That is not an accident.\n\nIt was built between 1965 and 1969 by the architect Hermann Henselmann and the engineer Günter Franke. The State conceived it as a visible answer to the west\'s Funkturm — 368 metres of steel and concrete to say: we too can build the future. The problem was that when the sun hits the stainless steel sphere at certain angles, a reflection appears in the shape of a cross. West Berliners called the phenomenon the Rache des Papstes — the Pope\'s Revenge. The atheist socialist State had built, without intending to, a shining cross visible from half of Berlin. They never found a way to remove it.\n\nI know exactly how much it cost to build. In 1969, when it was inaugurated, I was part of the security team. My first important assignment. I was twenty-seven years old and I believed in something.\n\nNow I am thirty-eight and I am not sure what I believe.\n\nToday\'s mission concerns Dieter Hofmann. Professor of philosophy at the Humboldt. I have been following him for four months. I know he listens to western radio in his apartment. I know he has a brother in Munich. I know he suspects someone is watching him, because he has started looking over his shoulder when he walks. I know because I taught him that. Everyone we follow long enough we eventually teach that.\n\nWhat I don\'t know is why I was ordered to end the surveillance today. Suddenly. Without explanation.\n\nHead down toward the Spree. The Marx-Engels-Forum is four minutes to the west.',
    'DE': 'Der Fernsehturm ist 368 Meter hoch. Er ist von jedem Punkt Ostberlins aus zu sehen – und auch von Westberlin. Das ist kein Zufall.\n\nEr wurde zwischen 1965 und 1969 vom Architekten Hermann Henselmann und dem Ingenieur Günter Franke gebaut. Der Staat konzipierte ihn als sichtbare Antwort auf den Funkturm im Westen – 368 Meter Stahl und Beton, um zu sagen: Auch wir können die Zukunft bauen. Das Problem war, dass wenn die Sonne in einem bestimmten Winkel auf die Kugel aus Edelstahl trifft, ein kreuzförmiger Reflex erscheint. Die Westberliner nannten das Phänomen die Rache des Papstes. Der atheistische sozialistische Staat hatte unbeabsichtigt ein leuchtendes Kreuz gebaut, das von halb Berlin aus zu sehen war. Sie fanden nie einen Weg, es zu beseitigen.\n\nIch weiß genau, was es gekostet hat, ihn zu bauen. 1969, als er eingeweiht wurde, war ich Teil des Sicherheitsteams. Mein erster wichtiger Einsatz. Ich war siebenundzwanzig Jahre alt und glaubte an etwas.\n\nJetzt bin ich achtunddreißig und nicht mehr sicher, was ich glaube.\n\nDer heutige Auftrag betrifft Dieter Hofmann. Professor für Philosophie an der Humboldt. Ich beobachte ihn seit vier Monaten. Ich weiß, dass er in seiner Wohnung Westradio hört. Ich weiß, dass er einen Bruder in München hat. Ich weiß, dass er ahnt, dass ihn jemand beobachtet, weil er angefangen hat, sich beim Gehen umzuschauen. Ich weiß das, weil ich es ihm beigebracht habe, sich umzuschauen. Allen, die wir lange genug beobachten, bringen wir das am Ende bei.\n\nWas ich nicht weiß, ist, warum mir befohlen wurde, die Überwachung heute zu beenden. Plötzlich. Ohne Erklärung.\n\nGeh zur Spree hinunter. Das Marx-Engels-Forum ist vier Minuten westlich.',
    'IT': 'La Torre della Televisione è alta 368 metri. Si può vedere da ogni punto di Berlino Est – e anche da Berlino Ovest. Non è un caso.\n\nFu costruita tra il 1965 e il 1969 dall\'architetto Hermann Henselmann e dall\'ingegnere Günter Franke. Lo Stato la concepì come risposta visibile al Funkturm dell\'ovest – 368 metri di acciaio e cemento per dire: anche noi possiamo costruire il futuro. Il problema fu che quando il sole colpisce la sfera di acciaio inossidabile a un certo angolo, appare un riflesso a forma di croce. I berlinesi dell\'ovest chiamarono il fenomeno la Rache des Papstes – la vendetta del Papa. Lo Stato socialista ateo aveva costruito, senza volerlo, una croce luminosa visibile da mezza Berlino. Non trovarono mai il modo di eliminarla.\n\nSo esattamente quanto costò costruirla. Nel 1969, quando fu inaugurata, facevo parte del team di sicurezza. Il mio primo incarico importante. Avevo ventisette anni e credevo in qualcosa.\n\nOra ho trentotto anni e non sono sicuro di cosa creda.\n\nLa missione di oggi riguarda Dieter Hofmann. Professore di filosofia alla Humboldt. Lo seguo da quattro mesi. So che ascolta la radio occidentale nel suo appartamento. So che ha un fratello a Monaco. So che sospetta che qualcuno lo sorveglia, perché ha iniziato a guardarsi indietro mentre cammina. Lo so perché sono io che gliel\'ho insegnato a guardarsi indietro. A tutti quelli che sorvegliamo abbastanza a lungo finiamo per insegnarglielo.\n\nQuello che non so è perché mi è stato ordinato di terminare la sorveglianza oggi. Di colpo. Senza spiegazione.\n\nScendi verso la Spree. Il Marx-Engels-Forum è a quattro minuti a ovest.',
  },
  'klaus_03': {
    'ES': 'El espacio frente al Spree está deliberadamente vacío esta mañana de noviembre.\n\nLas estatuas de bronce de Marx y Engels no se instalarán hasta 1986 — once años a partir de hoy. Por ahora solo hay silencio, bancos de madera, el río gris, y el perfil de la Museumsinsel al fondo. En los años treinta este era el corazón del Berlín judío y bohemio — el Scheunenviertel, los cabarets, los editores, los periódicos. Hoy es un espacio abierto sin función clara en medio del Berlín socialista, como un hueco que nadie sabe muy bien cómo llenar.\n\nMe siento y saco un cigarrillo.\n\nHay algo que no me cuadra en el expediente de Hofmann. En el informe del martes, mi colega Werner anotó que Hofmann salió a las 6:15 y regresó a las 8:40. Noventa y cinco minutos sin destino registrado. Le pregunté. Me dijo que no lo sabía. Werner siempre sabe.\n\nLlevo tres noches pensando en esos noventa y cinco minutos.\n\nEsta mañana, antes de salir, revisé mi propio expediente. Todos los agentes tenemos uno. Es política. Lo que no es política es que alguien había accedido al mío hace cuarenta y ocho horas. Sin autorización registrada.\n\nAplasto el cigarrillo.\n\nCamina hacia el Nikolaiviertel. Cruza el puente sobre el Spree — cinco minutos.',
    'EN': 'The space facing the Spree is deliberately empty this November morning.\n\nThe bronze statues of Marx and Engels won\'t be installed until 1986 — eleven years from now. For the moment there is only silence, wooden benches, the grey river, and the profile of the Museumsinsel in the background. In the thirties this was the heart of Jewish and bohemian Berlin — the Scheunenviertel, the cabarets, the publishers, the newspapers. Today it is an open space without a clear function in the middle of socialist Berlin, like a gap that no one quite knows how to fill.\n\nI sit down and light a cigarette.\n\nSomething doesn\'t add up in Hofmann\'s file. In Tuesday\'s report, my colleague Werner noted that Hofmann left at 6:15 and returned at 8:40. Ninety-five minutes with no recorded destination. I asked. He said he didn\'t know. Werner always knows.\n\nI\'ve spent three nights thinking about those ninety-five minutes.\n\nThis morning, before leaving, I checked my own file. All agents have one. That\'s policy. What isn\'t policy is that someone had accessed mine forty-eight hours ago. With no registered authorisation.\n\nI stub out the cigarette.\n\nWalk toward the Nikolaiviertel. Cross the bridge over the Spree — five minutes.',
    'DE': 'Der Raum vor der Spree ist an diesem Novembermorgen absichtlich leer.\n\nDie Bronzestatuen von Marx und Engels werden erst 1986 aufgestellt – elf Jahre von heute. Im Moment gibt es nur Stille, Holzbänke, den grauen Fluss und die Silhouette der Museumsinsel im Hintergrund. In den dreißiger Jahren war dies das Herz des jüdischen und bohemischen Berlins – das Scheunenviertel, die Kabaretts, die Verleger, die Zeitungen. Heute ist es ein offener Raum ohne klare Funktion im Herzen des sozialistischen Berlins, wie eine Lücke, die niemand so recht zu füllen weiß.\n\nIch setze mich und zünde mir eine Zigarette an.\n\nEtwas stimmt nicht in Hofmanns Akte. Im Bericht vom Dienstag notierte mein Kollege Werner, dass Hofmann um 6:15 Uhr wegging und um 8:40 Uhr zurückkam. Fünfundneunzig Minuten ohne registriertes Ziel. Ich fragte ihn. Er sagte, er wisse es nicht. Werner weiß immer Bescheid.\n\nSeit drei Nächten denke ich an diese fünfundneunzig Minuten.\n\nHeute Morgen, bevor ich losging, überprüfte ich meine eigene Akte. Alle Agenten haben eine. Das ist Politik. Was nicht Politik ist, ist dass jemand vor achtundvierzig Stunden ohne registrierte Genehmigung darauf zugegriffen hatte.\n\nIch drücke die Zigarette aus.\n\nGeh zum Nikolaiviertel. Überquere die Brücke über die Spree – fünf Minuten.',
    'IT': 'Lo spazio davanti alla Spree è deliberatamente vuoto in questo mattino di novembre.\n\nLe statue di bronzo di Marx e Engels non saranno installate fino al 1986 – undici anni da oggi. Per ora c\'è solo silenzio, panchine di legno, il fiume grigio e il profilo della Museumsinsel sullo sfondo. Negli anni trenta questo era il cuore della Berlino ebraica e bohémien – lo Scheunenviertel, i cabaret, gli editori, i giornali. Oggi è uno spazio aperto senza una funzione chiara nel cuore della Berlino socialista, come un vuoto che nessuno sa bene come riempire.\n\nMi siedo e tiro fuori una sigaretta.\n\nC\'è qualcosa che non torna nella pratica di Hofmann. Nel rapporto di martedì, il mio collega Werner annotò che Hofmann uscì alle 6:15 e tornò alle 8:40. Novantacinque minuti senza destinazione registrata. Gli chiesi. Disse che non lo sapeva. Werner sa sempre.\n\nDa tre notti penso a quei novantacinque minuti.\n\nStamattina, prima di uscire, controllai la mia stessa pratica. Tutti gli agenti ne hanno una. È politica. Quello che non è politica è che qualcuno vi aveva avuto accesso quarantotto ore fa. Senza autorizzazione registrata.\n\nSpengo la sigaretta.\n\nCammina verso il Nikolaiviertel. Attraversa il ponte sulla Spree – cinque minuti.',
  },
  'klaus_04': {
    'ES': 'El Nikolaiviertel es el barrio más antiguo de Berlín. La Nikolaikirche, que ves al fondo, fue fundada en torno a 1230 — es el edificio más viejo de la ciudad, el origen de todo lo que vino después. Las dos torres gemelas de ladrillo rojo, la nave gótica con sus ventanales estrechos, los adoquines irregulares alrededor. En 1975 el barrio está tranquilo y casi olvidado, esperando la restauración que comenzará en 1981 para los 750 años de la ciudad. Por ahora es un lugar donde los turistas no llegan y los funcionarios no pasan. Exactamente el tipo de lugar donde alguien deja un mensaje.\n\nEncuentro el sobre debajo de la cuarta piedra a la izquierda de la entrada norte de la Nikolaikirche. Exactamente donde acordamos. Lo abro de pie, con la espalda contra la pared.\n\nDentro hay una sola línea escrita a máquina:\n\nNo vayas a la reunión de las once.\n\nSin firma. Sin contexto. Solo eso.\n\nLo leo tres veces. Lo doblo en cuatro y lo guardo en el bolsillo interior de mi abrigo, junto al esternón. No por sentimentalismo sino porque es el lugar menos probable de ser revisado en un cacheo rápido. Once años de trabajo te enseñan esas cosas.\n\nLa reunión de las once es con mi superior. En la sede central. Iba a entregar el informe final sobre Hofmann.\n\nCamina hacia el Rotes Rathaus. Está a tres minutos al norte.',
    'EN': 'The Nikolaiviertel is the oldest neighbourhood in Berlin. The Nikolaikirche, which you can see ahead, was founded around 1230 — the oldest building in the city, the origin of everything that came after. The twin red-brick towers, the Gothic nave with its narrow windows, the uneven cobblestones around it. In 1975 the neighbourhood is quiet and almost forgotten, waiting for the restoration that will begin in 1981 for the city\'s 750th anniversary. For now it is a place tourists don\'t reach and officials don\'t pass through. Exactly the kind of place where someone leaves a message.\n\nI find the envelope under the fourth stone to the left of the north entrance of the Nikolaikirche. Exactly where we agreed. I open it standing, back against the wall.\n\nInside there is a single line typed on a machine:\n\nDo not go to the eleven o\'clock meeting.\n\nNo signature. No context. Just that.\n\nI read it three times. I fold it in four and tuck it into the inner pocket of my coat, against my sternum. Not out of sentimentality — it\'s the place least likely to be checked in a quick search. Eleven years of work teach you those things.\n\nThe eleven o\'clock meeting is with my superior. At the central office. I was going to deliver the final report on Hofmann.\n\nWalk toward the Rotes Rathaus. It is three minutes to the north.',
    'DE': 'Das Nikolaiviertel ist der älteste Stadtteil Berlins. Die Nikolaikirche, die du im Hintergrund siehst, wurde um 1230 gegründet – es ist das älteste Gebäude der Stadt, der Ursprung von allem, was danach kam. Die beiden roten Backsteinzwillingstürme, das gotische Schiff mit seinen schmalen Fenstern, das unebene Pflaster ringsum. 1975 ist das Viertel ruhig und fast vergessen, in Erwartung der Restaurierung, die 1981 für das 750-jährige Jubiläum der Stadt beginnen wird. Im Moment ist es ein Ort, an den keine Touristen kommen und keine Beamten vorbeigehen. Genau die Art von Ort, wo jemand eine Nachricht hinterlässt.\n\nIch finde den Umschlag unter dem vierten Stein links vom Nordeingang der Nikolaikirche. Genau dort, wo wir es vereinbart hatten. Ich öffne ihn stehend, mit dem Rücken zur Wand.\n\nDrinnen steht eine einzige mit Schreibmaschine geschriebene Zeile:\n\nGeh nicht zu dem Treffen um elf.\n\nKeine Unterschrift. Kein Kontext. Nur das.\n\nIch lese es dreimal. Ich falte es viermal und verstaue es in der Innentasche meines Mantels, neben dem Brustbein. Nicht aus Sentimentalität, sondern weil es der unwahrscheinlichste Ort ist, der bei einer schnellen Durchsuchung kontrolliert wird. Elf Jahre Arbeit lehren einem solche Dinge.\n\nDas Treffen um elf ist mit meinem Vorgesetzten. In der Zentrale. Ich sollte den Abschlussbericht über Hofmann übergeben.\n\nGeh zum Roten Rathaus. Es ist drei Minuten nördlich.',
    'IT': 'Il Nikolaiviertel è il quartiere più antico di Berlino. La Nikolaikirche, che vedi in fondo, fu fondata intorno al 1230 – è l\'edificio più vecchio della città, l\'origine di tutto ciò che venne dopo. Le due gemelle torri di mattoni rossi, la navata gotica con le sue strette finestre, il selciato irregolare tutt\'intorno. Nel 1975 il quartiere è tranquillo e quasi dimenticato, in attesa del restauro che inizierà nel 1981 per i 750 anni della città. Per ora è un posto dove i turisti non arrivano e i funzionari non passano. Esattamente il tipo di posto dove qualcuno lascia un messaggio.\n\nTrovo la busta sotto la quarta pietra a sinistra dall\'ingresso nord della Nikolaikirche. Esattamente dove avevamo concordato. La apro in piedi, con la schiena contro il muro.\n\nDentro c\'è una sola riga scritta a macchina:\n\nNon andare alla riunione delle undici.\n\nNessuna firma. Nessun contesto. Solo quello.\n\nLo leggo tre volte. Lo piego in quattro e lo ripongo nella tasca interna del cappotto, vicino allo sterno. Non per sentimentalismo, ma perché è il posto meno probabile di essere controllato in una perquisizione rapida. Undici anni di lavoro ti insegnano queste cose.\n\nLa riunione delle undici è con il mio superiore. Alla sede centrale. Dovevo consegnare il rapporto finale su Hofmann.\n\nCammina verso il Rotes Rathaus. È a tre minuti a nord.',
  },
  'klaus_05': {
    'ES': 'El Rotes Rathaus fue construido entre 1861 y 1869 por Hermann Friedrich Waesemann. Se llama así por el color de los ladrillos — rojo oscuro, casi marrón, el mismo tono que el barro seco del suelo de Brandeburgo. El edificio tiene 97 metros de torre central y una banda de terracota que rodea el exterior a la altura del primer piso con representaciones de la historia de Berlín: figuras en bajorrelieve que muestran la ciudad desde su fundación medieval hasta el siglo XIX. En 1975 es la sede del gobierno de Berlín Oriental, el lugar donde se toman las decisiones administrativas de la ciudad correcta.\n\nMe paro frente a él y hago lo que llevo once años haciendo: observo.\n\nHay un hombre apoyado en la farola de la esquina izquierda. Abrigo gris, sombrero oscuro. Lee un periódico. Los ojos no se mueven. Sé reconocer a alguien que finge leer porque yo mismo he fingido leer cientos de veces.\n\nMe están siguiendo.\n\nLa pregunta no es quién. La pregunta es desde cuándo. ¿Desde esta mañana? ¿Desde ayer? ¿Desde hace cuatro meses, mientras yo seguía a Hofmann?\n\nTengo dos opciones. Ir a la reunión de las once y ver qué pasa. O no ir.\n\nEl sobre decía que no fuera. Quien escribió ese sobre sabía de la reunión. Eso significa que es alguien de adentro.\n\nCamina hacia el sur. El Gendarmenmarkt está a quince minutos — sigue Französische Strasse.',
    'EN': 'The Rotes Rathaus was built between 1861 and 1869 by Hermann Friedrich Waesemann. It takes its name from the colour of its bricks — dark red, almost brown, the same shade as the dry clay of the Brandenburg soil. The building has a 97-metre central tower and a terracotta frieze running around the exterior at first-floor height depicting the history of Berlin: bas-relief figures showing the city from its medieval founding through to the 19th century. In 1975 it is the seat of the East Berlin government, the place where administrative decisions are made for the right city.\n\nI stop in front of it and do what I have spent eleven years doing: observe.\n\nThere is a man leaning against the lamp post on the left corner. Grey coat, dark hat. He is reading a newspaper. His eyes aren\'t moving. I know how to recognise someone who is pretending to read because I have pretended to read hundreds of times myself.\n\nI am being followed.\n\nThe question is not who. The question is since when. Since this morning? Since yesterday? Since four months ago, while I was following Hofmann?\n\nI have two options. Go to the eleven o\'clock meeting and see what happens. Or not go.\n\nThe envelope said not to go. Whoever wrote it knew about the meeting. That means it\'s someone from inside.\n\nWalk south. The Gendarmenmarkt is fifteen minutes away — follow Französische Strasse.',
    'DE': 'Das Rote Rathaus wurde zwischen 1861 und 1869 von Hermann Friedrich Waesemann erbaut. Es heißt so wegen der Farbe der Ziegel – dunkelrot, fast braun, derselbe Ton wie der trockene Lehm des Brandenburger Bodens. Das Gebäude hat einen 97 Meter hohen Mittelturm und ein Terrakottaband, das die Außenwand auf Höhe des ersten Stockwerks umläuft, mit Darstellungen der Berliner Geschichte: Relieffiguren, die die Stadt von ihrer mittelalterlichen Gründung bis ins 19. Jahrhundert zeigen. Im Jahr 1975 ist es der Sitz der Ostberliner Regierung, der Ort, wo die Verwaltungsentscheidungen der richtigen Stadt getroffen werden.\n\nIch stelle mich davor hin und tue, was ich seit elf Jahren tue: ich beobachte.\n\nEin Mann lehnt an der Laterne an der linken Ecke. Grauer Mantel, dunkler Hut. Er liest eine Zeitung. Die Augen bewegen sich nicht. Ich erkenne jemanden, der so tut als würde er lesen, weil ich selbst hunderte Male so getan habe als würde ich lesen.\n\nIch werde verfolgt.\n\nDie Frage ist nicht wer. Die Frage ist seit wann. Seit heute Morgen? Seit gestern? Seit vier Monaten, während ich Hofmann beschattete?\n\nIch habe zwei Möglichkeiten. Zum Elf-Uhr-Treffen gehen und sehen, was passiert. Oder nicht gehen.\n\nDer Umschlag sagte, ich soll nicht gehen. Wer diesen Umschlag schrieb, wusste von dem Treffen. Das bedeutet, es ist jemand von innen.\n\nGeh nach Süden. Der Gendarmenmarkt ist fünfzehn Minuten entfernt – folge der Französischen Straße.',
    'IT': 'Il Rotes Rathaus fu costruito tra il 1861 e il 1869 da Hermann Friedrich Waesemann. Si chiama così per il colore dei mattoni – rosso scuro, quasi marrone, lo stesso tono dell\'argilla secca del suolo del Brandeburgo. L\'edificio ha una torre centrale di 97 metri e una fascia di terracotta che corre all\'esterno all\'altezza del primo piano con rappresentazioni della storia di Berlino: figure in bassorilievo che mostrano la città dalla sua fondazione medievale fino al XIX secolo. Nel 1975 è la sede del governo di Berlino Est, il luogo dove vengono prese le decisioni amministrative della città giusta.\n\nMi fermo davanti ad esso e faccio quello che faccio da undici anni: osservo.\n\nC\'è un uomo appoggiato al lampione all\'angolo sinistro. Cappotto grigio, cappello scuro. Legge un giornale. Gli occhi non si muovono. So riconoscere qualcuno che finge di leggere perché io stesso ho finto di leggere centinaia di volte.\n\nMi stanno seguendo.\n\nLa domanda non è chi. La domanda è da quando. Da stamattina? Da ieri? Da quattro mesi, mentre seguivo Hofmann?\n\nHo due opzioni. Andare alla riunione delle undici e vedere cosa succede. O non andare.\n\nLa busta diceva di non andare. Chi scrisse quella busta sapeva della riunione. Questo significa che è qualcuno dall\'interno.\n\nCammina verso sud. Il Gendarmenmarkt è a quindici minuti – segui la Französische Strasse.',
  },
  'klaus_06': {
    'ES': 'El Gendarmenmarkt es la plaza más hermosa de Berlín. Lo era antes de la guerra y lo sigue siendo, aunque en 1975 todavía lleva las marcas de los bombardeos y la reconstrucción incompleta.\n\nEl conjunto lo forman tres edificios del siglo XVIII: el Französischer Dom al norte, el Deutscher Dom al sur, y el Konzerthaus en el centro. El Französischer Dom — la Catedral Francesa — fue construido en 1705 para la comunidad hugonota que Federico I invitó a establecerse en Berlín después de que Luis XIV los expulsara de Francia. Cincuenta mil hugonotes llegaron a Prusia trayendo sus oficios, su lengua, su conocimiento de la seda y el vidrio. Un tercio de la población de Berlín era hugonota a principios del siglo XVIII. La ciudad que hoy existe se construyó en parte con lo que trajeron los que fueron expulsados de otro lugar.\n\nMe siento en los escalones del Konzerthaus.\n\nTengo tres cosas en los bolsillos: el sobre con el mensaje, mi documento de identidad de la Stasi, y una fotografía que no debería tener. Es una foto de mi hermana Margit, que cruzó al oeste en 1968. La reporté. Era mi obligación. Margit nunca lo supo — o quizás sí lo supo y por eso nunca intentó contactarme. La fotografía llegó hace tres semanas a mi buzón, sin remitente. Alguien sabe que tengo una hermana en el oeste.\n\nEste es el momento. Lo siento con la misma claridad con que se siente el frío.\n\nAquí la historia se divide. Camina hacia el oeste, hacia el Bebelplatz, si Klaus va a cruzar. Camina hacia el este si Klaus va a la reunión.',
    'EN': 'The Gendarmenmarkt is the most beautiful square in Berlin. It was before the war and it still is, though in 1975 it still carries the marks of the bombings and the incomplete reconstruction.\n\nThe ensemble consists of three 18th-century buildings: the Französischer Dom to the north, the Deutscher Dom to the south, and the Konzerthaus in the centre. The Französischer Dom — the French Cathedral — was built in 1705 for the Huguenot community that Frederick I invited to settle in Berlin after Louis XIV expelled them from France. Fifty thousand Huguenots came to Prussia bringing their trades, their language, their knowledge of silk and glass. A third of Berlin\'s population was Huguenot in the early 18th century. The city that exists today was built partly from what was brought by those expelled from somewhere else.\n\nI sit on the steps of the Konzerthaus.\n\nI have three things in my pockets: the envelope with the message, my Stasi identity document, and a photograph I shouldn\'t have. It\'s a photo of my sister Margit, who crossed to the west in 1968. I reported her. That was my obligation. Margit never knew — or perhaps she did know and that\'s why she never tried to contact me. The photograph arrived in my letterbox three weeks ago, with no sender. Someone knows I have a sister in the west.\n\nThis is the moment. I feel it with the same clarity as cold — not as a thought but as something physical, in the chest.\n\nThe story divides here. Walk west toward the Bebelplatz if Klaus is going to cross. Walk east if Klaus is going to the meeting.',
    'DE': 'Der Gendarmenmarkt ist der schönste Platz in Berlin. Das war er vor dem Krieg und ist er noch immer, obwohl er 1975 noch die Spuren der Bombardierungen und des unvollendeten Wiederaufbaus trägt.\n\nDas Ensemble besteht aus drei Gebäuden des 18. Jahrhunderts: dem Französischen Dom im Norden, dem Deutschen Dom im Süden und dem Konzerthaus in der Mitte. Der Französische Dom wurde 1705 für die Hugenottengemeinde gebaut, die Friedrich I. einlud, sich in Berlin niederzulassen, nachdem Ludwig XIV. sie aus Frankreich vertrieben hatte. Fünfzigtausend Hugenotten kamen nach Preußen und brachten ihre Handwerke, ihre Sprache, ihr Wissen über Seide und Glas mit. Ein Drittel der Berliner Bevölkerung war Anfang des 18. Jahrhunderts hugenottisch. Die Stadt, die heute existiert, wurde zum Teil mit dem aufgebaut, was die Vertriebenen von anderswo mitbrachten.\n\nIch setze mich auf die Stufen des Konzerthauses.\n\nIch habe drei Dinge in meinen Taschen: den Umschlag mit der Nachricht, meinen Stasi-Ausweis und ein Foto, das ich nicht haben sollte. Es ist ein Foto meiner Schwester Margit, die 1968 in den Westen gegangen ist. Ich meldete es. Es war meine Pflicht. Margit wusste es nie – oder vielleicht wusste sie es doch, weshalb sie nie versuchte, mich zu kontaktieren. Das Foto kam vor drei Wochen in meinen Briefkasten, ohne Absender. Jemand weiß, dass ich eine Schwester im Westen habe.\n\nDies ist der Moment. Ich spüre es mit derselben Klarheit, mit der man die Kälte spürt.\n\nHier teilt sich die Geschichte. Geh nach Westen, zur Bebelplatz, wenn Klaus hinübergehen will. Geh nach Osten, wenn Klaus zum Treffen geht.',
    'IT': 'Il Gendarmenmarkt è la piazza più bella di Berlino. Lo era prima della guerra e lo è ancora, anche se nel 1975 porta ancora i segni dei bombardamenti e della ricostruzione incompiuta.\n\nL\'insieme è formato da tre edifici del XVIII secolo: il Französischer Dom a nord, il Deutscher Dom a sud e il Konzerthaus al centro. Il Französischer Dom fu costruito nel 1705 per la comunità ugonotta che Federico I invitò a stabilirsi a Berlino dopo che Luigi XIV li aveva espulsi dalla Francia. Cinquantamila ugonotti arrivarono in Prussia portando i loro mestieri, la loro lingua, la loro conoscenza della seta e del vetro. Un terzo della popolazione di Berlino era ugonotta all\'inizio del XVIII secolo. La città che esiste oggi fu costruita in parte con ciò che portarono coloro che furono espulsi da un altro posto.\n\nMi siedo sui gradini del Konzerthaus.\n\nHo tre cose in tasca: la busta con il messaggio, il mio documento d\'identità della Stasi e una fotografia che non dovrei avere. È una foto di mia sorella Margit, che è passata all\'ovest nel 1968. La segnalai. Era mio dovere. Margit non lo seppe mai – o forse lo seppe e per questo non cercò mai di contattarmi. La fotografia arrivò tre settimane fa nella mia cassetta delle lettere, senza mittente. Qualcuno sa che ho una sorella all\'ovest.\n\nQuesto è il momento. Lo sento con la stessa chiarezza con cui si sente il freddo.\n\nQui la storia si divide. Cammina verso ovest, verso la Bebelplatz, se Klaus vuole attraversare. Cammina verso est se Klaus va alla riunione.',
  },
  'klaus_07a': {
    'ES': 'Camino por Unter den Linden hacia el oeste.\n\nEs la calle más importante de Berlín Oriental — dos kilómetros de ancho bulevar con cuatro carriles, los tilos en el centro, los edificios neoclásicos a ambos lados. Federico el Grande la diseñó en el siglo XVIII como el eje de la ciudad culta. Hoy sus edificios albergan la Humboldt-Universität, la Staatsoper, la Biblioteca Estatal. La calle que lleva al conocimiento. A la cultura. A la idea de que Alemania fue, antes de todo lo demás, una nación de pensadores.\n\nMe detengo en la Bebelplatz.\n\nEn 1933, los estudiantes nazis quemaron aquí decenas de miles de libros. Los de Freud, Marx, Remarque, Kästner, Tucholsky. El evento lo llamaron Aktion wider den undeutschen Geist — Acción contra el espíritu no alemán. Asistieron rectores universitarios, profesores, funcionarios. El conocimiento ardiendo frente a la universidad. Heine lo había escrito en 1820: donde queman libros, al final también queman personas. Lo enseñamos en las escuelas como advertencia sobre el fascismo. Nadie menciona que el Estado actual tampoco publica a Heine sin censura.\n\nHoy hay una placa en el suelo y adoquines sobre la placa. Debajo, según dicen, una sala vacía con estantes blancos y sin libros. Una biblioteca con la forma exacta de lo que fue destruido.\n\nSigo caminando. Checkpoint Charlie está a veinte minutos.',
    'EN': 'I walk along Unter den Linden toward the west.\n\nIt is the most important street in East Berlin — two kilometres of wide boulevard with four lanes, linden trees down the centre, neoclassical buildings on both sides. Frederick the Great designed it in the 18th century as the axis of the cultured city. Today its buildings house the Humboldt-Universität, the Staatsoper, the State Library. The street that leads to knowledge. To culture. To the idea that Germany was, before everything else, a nation of thinkers.\n\nI stop at the Bebelplatz.\n\nIn 1933, Nazi students burned tens of thousands of books here. Freud\'s, Marx\'s, Remarque\'s, Kästner\'s, Tucholsky\'s. They called the event Aktion wider den undeutschen Geist — Action against the un-German spirit. University rectors, professors and officials attended. Knowledge burning in front of the university. Heine had written it in 1820: where they burn books, they will ultimately burn people. We teach it in schools as a warning about fascism. No one mentions that the current State also doesn\'t publish Heine uncensored.\n\nToday there is a plaque in the ground and cobblestones over the plaque. Underneath, they say, an empty room with white shelves and no books. A library with the exact shape of what was destroyed.\n\nI keep walking. Checkpoint Charlie is twenty minutes away.',
    'DE': 'Ich gehe die Unter den Linden nach Westen.\n\nSie ist die wichtigste Straße Ostberlins – zwei Kilometer breiter Boulevard mit vier Fahrspuren, den Linden in der Mitte, den neoklassizistischen Gebäuden auf beiden Seiten. Friedrich der Große entwarf ihn im 18. Jahrhundert als Achse der kultivierten Stadt. Heute beherbergen seine Gebäude die Humboldt-Universität, die Staatsoper, die Staatsbibliothek. Die Straße, die zum Wissen führt. Zur Kultur. Zur Idee, dass Deutschland vor allem anderen eine Nation von Denkern war.\n\nIch halte an der Bebelplatz an.\n\n1933 verbrannten die Nazi-Studenten hier Zehntausende von Büchern. Die von Freud, Marx, Remarque, Kästner, Tucholsky. Die Veranstaltung nannten sie Aktion wider den undeutschen Geist. Universitätsrektoren, Professoren, Beamte nahmen teil. Das Wissen, das vor der Universität brennt. Heine hatte es 1820 geschrieben: Dort, wo man Bücher verbrennt, verbrennt man auch am Ende Menschen. Wir lehren es in den Schulen als Warnung vor dem Faschismus. Niemand erwähnt, dass der aktuelle Staat Heine auch nicht ohne Zensur verlegt.\n\nHeute liegt dort eine Gedenktafel und Pflastersteine über der Tafel. Darunter, so sagt man, ein leerer Raum mit weißen Regalen und ohne Bücher. Eine Bibliothek in der Form von dem, was zerstört wurde.\n\nIch gehe weiter. Checkpoint Charlie ist zwanzig Minuten entfernt.',
    'IT': 'Cammino lungo Unter den Linden verso ovest.\n\nÈ la strada più importante di Berlino Est – due chilometri di ampio viale con quattro corsie, i tigli al centro, gli edifici neoclassici su entrambi i lati. Federico il Grande la progettò nel XVIII secolo come asse della città colta. Oggi i suoi edifici ospitano la Humboldt-Universität, la Staatsoper, la Biblioteca di Stato. La strada che porta alla conoscenza. Alla cultura. All\'idea che la Germania fosse, prima di tutto, una nazione di pensatori.\n\nMi fermo alla Bebelplatz.\n\nNel 1933 gli studenti nazisti bruciarono qui decine di migliaia di libri. Quelli di Freud, Marx, Remarque, Kästner, Tucholsky. L\'evento lo chiamarono Aktion wider den undeutschen Geist – Azione contro lo spirito non tedesco. Vi parteciparono rettori universitari, professori, funzionari. La conoscenza che brucia davanti all\'università. Heine lo aveva scritto nel 1820: dove si bruciano i libri, alla fine si bruciano anche le persone. Lo insegniamo nelle scuole come avvertimento contro il fascismo. Nessuno menziona che lo Stato attuale non pubblica nemmeno Heine senza censura.\n\nOggi c\'è una targa sul pavimento e dei selci sopra la targa. Sotto, a quanto si dice, una stanza vuota con scaffali bianchi e senza libri. Una biblioteca con la forma esatta di ciò che fu distrutto.\n\nContinuo a camminare. Checkpoint Charlie è a venti minuti.',
  },
  'klaus_08a': {
    'ES': 'Entro a la Neue Wache.\n\nEl edificio fue construido por Schinkel en 1818 como guardia real. En la República Democrática Alemana se convirtió en el Mahnmal für die Opfer des Faschismus und Militarismus — memorial para las víctimas del fascismo y el militarismo. Aquí se celebraban los actos oficiales. Aquí los líderes del Estado depositaban coronas de flores frente a la llama eterna. Aquí yo mismo estuve formado en uniforme hace doce años, durante mi primera semana en el servicio. Me sentí parte de algo más grande que yo mismo.\n\nLa llama tiembla levemente. Hay dos soldados inmóviles. Los miro. Son jóvenes — diecinueve, veinte años. Llevan el uniforme con la seriedad de quien todavía cree que el uniforme significa algo.\n\nYo tenía esa seriedad. La recuerdo con claridad y sin nostalgia.\n\nConsulto mi reloj: las 10:23. Si voy a hacerlo, tengo que hacerlo ahora.\n\nDesde este momento, Klaus Brenner deja de ser un agente de la Stasi. Todavía no lo sabe nadie más. Solo yo.\n\nCamina hacia el sur por Friedrichstrasse. Checkpoint Charlie está a veinte minutos.',
    'EN': 'I enter the Neue Wache.\n\nThe building was constructed by Schinkel in 1818 as the royal guardhouse. In the German Democratic Republic it became the Mahnmal für die Opfer des Faschismus und Militarismus — memorial for the victims of fascism and militarism. Official ceremonies took place here. The State\'s leaders laid wreaths before the eternal flame. I myself stood here in uniform twelve years ago, during my first week in the service. I felt part of something larger than myself.\n\nThe flame trembles slightly. Two soldiers stand motionless. I look at them. They are young — nineteen, twenty years old. They wear the uniform with the seriousness of someone who still believes the uniform means something.\n\nI had that seriousness. I remember it clearly and without nostalgia.\n\nI check my watch: 10:23. If I am going to do this, I have to do it now.\n\nFrom this moment, Klaus Brenner is no longer a Stasi agent. No one else knows yet. Only me.\n\nWalk south along Friedrichstrasse. Checkpoint Charlie is twenty minutes away.',
    'DE': 'Ich betrete die Neue Wache.\n\nDas Gebäude wurde von Schinkel 1818 als Königswache gebaut. In der Deutschen Demokratischen Republik wurde es zum Mahnmal für die Opfer des Faschismus und Militarismus. Hier fanden die offiziellen Akte statt. Hier legten die Staatsführer Kränze vor der ewigen Flamme nieder. Hier stand ich vor zwölf Jahren selbst in Uniform in der Formation, während meiner ersten Woche im Dienst. Ich fühlte mich Teil von etwas Größerem als ich selbst.\n\nDie Flamme flackert leicht. Zwei Soldaten stehen reglos. Ich betrachte sie. Sie sind jung – neunzehn, zwanzig Jahre. Sie tragen die Uniform mit dem Ernst von jemandem, der noch immer glaubt, die Uniform bedeute etwas.\n\nIch hatte diesen Ernst. Ich erinnere mich daran klar und ohne Nostalgie.\n\nIch schaue auf meine Uhr: 10:23 Uhr. Wenn ich es tun will, muss ich es jetzt tun.\n\nAb diesem Moment ist Klaus Brenner kein Stasi-Agent mehr. Noch weiß das sonst niemand. Nur ich.\n\nGeh nach Süden die Friedrichstraße entlang. Checkpoint Charlie ist zwanzig Minuten entfernt.',
    'IT': 'Entro nella Neue Wache.\n\nL\'edificio fu costruito da Schinkel nel 1818 come guardia reale. Nella Repubblica Democratica Tedesca divenne il Mahnmal für die Opfer des Faschismus und Militarismus – memoriale per le vittime del fascismo e del militarismo. Qui si svolgevano gli atti ufficiali. Qui i leader dello Stato deponevano corone di fiori davanti alla fiamma eterna. Qui io stesso stetti in formazione in uniforme dodici anni fa, durante la mia prima settimana di servizio. Mi sentii parte di qualcosa più grande di me stesso.\n\nLa fiamma trema leggermente. Due soldati sono immobili. Li guardo. Sono giovani – diciannove, vent\'anni. Indossano l\'uniforme con la serietà di chi crede ancora che l\'uniforme significhi qualcosa.\n\nAvevo quella serietà. La ricordo chiaramente e senza nostalgia.\n\nGuardo il mio orologio: le 10:23. Se devo farlo, devo farlo adesso.\n\nDa questo momento, Klaus Brenner non è più un agente della Stasi. Ancora nessun altro lo sa. Solo io.\n\nCammina verso sud lungo la Friedrichstrasse. Checkpoint Charlie è a venti minuti.',
  },
  'klaus_09a': {
    'ES': 'Checkpoint Charlie. El paso fronterizo entre los sectores americano y soviético, entre el mundo libre y el mundo correcto, entre los que pueden salir y los que no.\n\nLo conozco mejor que casi nadie. Sé qué documentos revisan, qué preguntas hacen, en qué orden. Sé dónde están las cámaras — yo mismo ayudé a instalar dos de ellas en 1971. Sé que hay tres agentes del Ministerium trabajando ahora mismo en este control, disfrazados de policías de tráfico. Los conozco de vista. Probablemente ellos también me conocen.\n\nSaco mi documento de identidad.\n\nLos documentos de la Stasi tienen un código de color en la esquina inferior derecha. Verde: agente activo en misión. No estoy en misión oficial. Pero el código dice que sí.\n\nRespiro.\n\nCruzo.\n\nAl otro lado, en la caseta americana, un soldado joven me mira sin entender bien qué acaba de pasar. Yo tampoco entiendo bien qué acaba de pasar. Pero ha pasado.\n\nEstoy al otro lado.\n\nEn los años que siguen, Klaus Brenner dará información a los servicios de inteligencia occidentales sobre las redes de la Stasi. Algunos de los nombres que entregue salvarán vidas. Otros no cambiarán de destino. Esa distinción le quitará el sueño durante años.\n\nBerlín fue construida para no poder cruzarse. Muros, alambradas, torres de vigilancia — toda la ingeniería del siglo XX puesta al servicio de mantener a las personas en su lugar. Y sin embargo los berlineses la cruzaron. En globo, en coche modificado, en túnel, en maletero, en uniforme prestado. Ciento cuarenta personas murieron intentándolo. Miles lo consiguieron.\n\nLos muros no duran tanto como creen quienes los construyen. Este cayó en 1989. Quince años después de este día, Klaus Brenner estuvo entre la multitud que lo vio caer.\n\nBerlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'Checkpoint Charlie. The border crossing between the American and Soviet sectors, between the free world and the right world, between those who can leave and those who cannot.\n\nI know it better than almost anyone. I know which documents they check, which questions they ask, in what order. I know where the cameras are — I helped install two of them in 1971. I know there are three Ministry agents working this control right now, disguised as traffic police. I know them by sight. They probably know me too.\n\nI take out my identity document.\n\nStasi documents have a colour code in the lower right corner. Green: active agent on a mission. I am not on an official mission. But the code says I am.\n\nI breathe.\n\nI cross.\n\nOn the other side, in the American booth, a young soldier looks at me without quite understanding what just happened. I don\'t quite understand what just happened either. But it has happened.\n\nI am on the other side.\n\nIn the years that follow, Klaus Brenner will provide intelligence services in the west with information about Stasi networks. Some of the names he gives will save lives. Others won\'t change their fate. That distinction will cost him sleep for years.\n\nBerlin was built not to be crossed. Walls, barbed wire, watchtowers — all of 20th-century engineering put in the service of keeping people in their place. And yet Berliners crossed it. By hot-air balloon, in modified cars, through tunnels, in car boots, in borrowed uniforms. A hundred and forty people died trying. Thousands succeeded.\n\nWalls don\'t last as long as those who build them believe. This one fell in 1989. Fifteen years after this day, Klaus Brenner was in the crowd that watched it fall.\n\nBerlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Checkpoint Charlie. Der Grenzübergang zwischen dem amerikanischen und sowjetischen Sektor, zwischen der freien Welt und der richtigen Welt, zwischen denen, die raus können, und denen, die es nicht können.\n\nIch kenne es besser als fast jeder andere. Ich weiß, welche Dokumente sie prüfen, welche Fragen sie stellen, in welcher Reihenfolge. Ich weiß, wo die Kameras sind – ich half selbst dabei, zwei von ihnen 1971 zu installieren. Ich weiß, dass es drei Ministerium-Agenten gibt, die gerade an diesem Kontrollpunkt arbeiten, als Verkehrspolizisten verkleidet. Ich kenne sie vom Sehen. Wahrscheinlich kennen sie mich auch.\n\nIch ziehe meinen Ausweis heraus.\n\nStasi-Ausweise haben einen Farbcode in der unteren rechten Ecke. Grün: aktiver Agent im Einsatz. Ich bin nicht in einem offiziellen Einsatz. Aber der Code sagt, ich bin es.\n\nIch atme durch.\n\nIch überquere.\n\nAuf der anderen Seite, in der amerikanischen Kabine, schaut mich ein junger Soldat an, ohne genau zu verstehen, was gerade passiert ist. Ich verstehe auch nicht genau, was gerade passiert ist. Aber es ist passiert.\n\nIch bin auf der anderen Seite.\n\nIn den folgenden Jahren wird Klaus Brenner den westlichen Geheimdiensten Informationen über die Stasi-Netzwerke liefern. Einige der Namen, die er nennt, werden Leben retten. Andere werden ihr Schicksal nicht ändern. Diese Unterscheidung wird ihn jahrelang um den Schlaf bringen.\n\nBerlin wurde gebaut, um nicht durchquert werden zu können. Mauern, Stacheldraht, Wachtürme – die gesamte Ingenieurkunst des 20. Jahrhunderts im Dienst daran, die Menschen an ihrem Platz zu halten. Und dennoch überquerten die Berliner sie. Im Ballon, im umgebauten Auto, im Tunnel, im Kofferraum, in geliehener Uniform. Hundertundvierzig Menschen starben beim Versuch. Tausende schafften es.\n\nMauern halten nicht so lange, wie ihre Erbauer glauben. Diese fiel 1989. Fünfzehn Jahre nach diesem Tag war Klaus Brenner unter der Menge, die ihren Fall erlebte.\n\nBerlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Checkpoint Charlie. Il valico di frontiera tra il settore americano e quello sovietico, tra il mondo libero e il mondo giusto, tra quelli che possono uscire e quelli che non possono.\n\nLo conosco meglio di quasi chiunque altro. So quali documenti controllano, quali domande fanno, in quale ordine. So dove sono le telecamere – io stesso aiutai a installarne due nel 1971. So che ci sono tre agenti del Ministerium che lavorano proprio in questo posto di controllo in questo momento, travestiti da poliziotti del traffico. Li conosco di vista. Probabilmente anche loro conoscono me.\n\nTiro fuori il mio documento d\'identità.\n\nI documenti della Stasi hanno un codice colore nell\'angolo in basso a destra. Verde: agente attivo in missione. Non sono in una missione ufficiale. Ma il codice dice di sì.\n\nRespiro.\n\nAttraverso.\n\nDall\'altra parte, nella cabina americana, un giovane soldato mi guarda senza capire bene cosa sia appena successo. Nemmeno io capisco bene cosa sia appena successo. Ma è successo.\n\nSono dall\'altra parte.\n\nNegli anni che seguono, Klaus Brenner fornirà informazioni ai servizi segreti occidentali sulle reti della Stasi. Alcuni dei nomi che consegnerà salveranno vite. Altri non cambieranno il loro destino. Questa distinzione gli toglierà il sonno per anni.\n\nBerlino fu costruita per non poter essere attraversata. Muri, filo spinato, torri di guardia – tutta l\'ingegneria del XX secolo messa al servizio di tenere le persone al loro posto. Eppure i berlinesi la attraversarono. In mongolfiera, in automobile modificata, in tunnel, nel bagagliaio, in uniforme presa in prestito. Centoquaranta persone morirono nel tentativo. Migliaia ci riuscirono.\n\nI muri non durano quanto credono quelli che li costruiscono. Questo cadde nel 1989. Quindici anni dopo quel giorno, Klaus Brenner era tra la folla che lo vide cadere.\n\nBerlino è ancora qui. E anche tu. Per ora basta così.',
  },
  'klaus_07b': {
    'ES': 'Doblo el papel. Lo guardo. Me levanto.\n\nVoy a ir a la reunión.\n\nMe digo que el sobre era una trampa — alguien quería ver si mostraría señales de deslealtad. He pasado la prueba. El hombre del abrigo gris era protección, no vigilancia. El acceso a mi expediente fue una revisión rutinaria. Todo tiene explicación. Todo encaja.\n\nLlevo once años construyendo versiones de los hechos que encajan. Es mi habilidad principal.\n\nCamino por Unter den Linden. Me detengo un momento en la Bebelplatz.\n\nEn 1933 los nazis quemaron libros aquí. En 1975 los libros que no pueden publicarse en la República Democrática Alemana son distintos — pero siguen sin poder publicarse. La lista incluye a Solzhenitsyn, a Nabokov, a Orwell. Sobre todo a Orwell. Eso siempre me ha parecido una admisión involuntaria.\n\nMe quedo mirando los adoquines unos segundos.\n\nHay una placa en el suelo. Debajo, según dicen, una sala vacía con estantes blancos. Una biblioteca sin libros. Un hueco con la forma exacta de lo que fue destruido.\n\nSon las 10:31. Tengo que seguir.\n\nCamina hacia el este por Unter den Linden. La Neue Wache está a dos minutos.',
    'EN': 'I fold the paper. Pocket it. I stand up.\n\nI am going to the meeting.\n\nI tell myself the envelope was a trap — someone wanted to see if I would show signs of disloyalty. I have passed the test. The man in the grey coat was protection, not surveillance. The access to my file was a routine review. Everything has an explanation. Everything fits.\n\nI have spent eleven years constructing versions of events that fit. It is my main skill.\n\nI walk along Unter den Linden. I stop for a moment at the Bebelplatz.\n\nIn 1933 the Nazis burned books here. In 1975 the books that cannot be published in the German Democratic Republic are different — but they still cannot be published. The list includes Solzhenitsyn, Nabokov, Orwell. Especially Orwell. I have always found that an involuntary admission.\n\nI stand looking at the cobblestones for a few seconds.\n\nThere is a plaque in the ground. Underneath, they say, an empty room with white shelves. A library without books. A gap with the exact shape of what was destroyed.\n\nIt is 10:31. I have to keep moving.\n\nWalk east along Unter den Linden. The Neue Wache is two minutes away.',
    'DE': 'Ich falte das Papier. Ich verstaue es. Ich stehe auf.\n\nIch werde zum Treffen gehen.\n\nIch sage mir, der Umschlag war eine Falle – jemand wollte sehen, ob ich Anzeichen von Illoyalität zeigen würde. Ich habe die Probe bestanden. Der Mann im grauen Mantel war Schutz, keine Überwachung. Der Zugriff auf meine Akte war eine Routineüberprüfung. Alles hat eine Erklärung. Alles fügt sich zusammen.\n\nElf Jahre lang habe ich Versionen der Ereignisse gebaut, die zusammenpassen. Das ist meine Hauptfähigkeit.\n\nIch gehe die Unter den Linden entlang. Ich halte kurz an der Bebelplatz an.\n\n1933 verbrannten die Nazis hier Bücher. 1975 sind die Bücher, die in der Deutschen Demokratischen Republik nicht verlegt werden können, andere – aber sie sind immer noch nicht verlegbar. Die Liste umfasst Solschenizyn, Nabokov, Orwell. Vor allem Orwell. Das erschien mir immer wie ein unbeabsichtigtes Geständnis.\n\nIch stehe ein paar Sekunden und schaue auf das Pflaster.\n\nEs liegt eine Gedenktafel im Boden. Darunter, so sagt man, ein leerer Raum mit weißen Regalen. Eine Bibliothek ohne Bücher. Eine Lücke in der Form von dem, was zerstört wurde.\n\nEs ist 10:31 Uhr. Ich muss weitergehen.\n\nGeh nach Osten entlang der Unter den Linden. Die Neue Wache ist zwei Minuten entfernt.',
    'IT': 'Piego il foglio. Lo ripongo. Mi alzo.\n\nAndrò alla riunione.\n\nMi dico che la busta era una trappola – qualcuno voleva vedere se avrei mostrato segni di slealtà. Ho superato la prova. L\'uomo con il cappotto grigio era protezione, non sorveglianza. L\'accesso alla mia pratica è stato una revisione di routine. Tutto ha una spiegazione. Tutto torna.\n\nDa undici anni costruisco versioni degli eventi che tornano. È la mia abilità principale.\n\nCammino lungo Unter den Linden. Mi fermo un momento alla Bebelplatz.\n\nNel 1933 i nazisti bruciarono libri qui. Nel 1975 i libri che non possono essere pubblicati nella Repubblica Democratica Tedesca sono diversi – ma continuano a non poter essere pubblicati. La lista include Solženicyn, Nabokov, Orwell. Soprattutto Orwell. Questo mi è sempre sembrato un\'ammissione involontaria.\n\nResto a guardare i selci per qualche secondo.\n\nC\'è una targa nel pavimento. Sotto, a quanto si dice, una stanza vuota con scaffali bianchi. Una biblioteca senza libri. Un vuoto con la forma esatta di ciò che fu distrutto.\n\nSono le 10:31. Devo continuare.\n\nCammina verso est lungo Unter den Linden. La Neue Wache è a due minuti.',
  },
  'klaus_08b': {
    'ES': 'Me detengo frente a la Neue Wache sin entrar.\n\nSchinkel lo construyó en 1818 como guardia real. Seis columnas dóricas, frontón triangular, una austeridad que se parece a la honestidad aunque no lo sea. En la República Democrática es el memorial oficial para las víctimas del fascismo — aquí el Estado deposita sus coronas, aquí los soldados hacen guardia, aquí la historia oficial se pone firme y saluda.\n\nMiro la llama que arde al fondo, a través de las columnas. Me pregunto cuántas versiones de la verdad han ardido aquí, presentadas como la única verdad posible.\n\nEl hombre del abrigo gris ya no está. Pero hay otro hombre ahora, en la esquina de Unter den Linden con Friedrichstrasse. Abrigo azul marino. Tampoco lee su periódico.\n\nDos seguimientos en el mismo día no son rutina. Dos seguimientos significan que alguien quiere asegurarse de que llegue a un lugar determinado. O de que no llegue.\n\nMiro mi reloj: las 10:48. Doce minutos para la reunión.\n\nSigo caminando. Ya no porque crea en la reunión. Sino porque quiero ver quién me está esperando.\n\nCamina hacia el este. Una última parada antes de la sede.',
    'EN': 'I stop in front of the Neue Wache without going in.\n\nSchinkel built it in 1818 as the royal guardhouse. Six Doric columns, triangular pediment, an austerity that resembles honesty without being it. In the Democratic Republic it is the official memorial for the victims of fascism — here the State lays its wreaths, here the soldiers stand guard, here the official history stands to attention and salutes.\n\nI look at the flame burning in the background, through the columns. I wonder how many versions of the truth have burned there, presented as the only possible truth.\n\nThe man in the grey coat is no longer at the lamp post. But there is another man now, on the corner of Unter den Linden and Friedrichstrasse. Dark blue coat. He is also not reading his newspaper.\n\nTwo tails on the same day is not routine. Two tails mean someone wants to make sure I reach a certain place. Or that I don\'t.\n\nI check my watch: 10:48. Twelve minutes until the meeting.\n\nI keep walking. No longer because I believe in the meeting. But because I want to see who is waiting for me.\n\nWalk east. One last stop before the headquarters.',
    'DE': 'Ich bleibe vor der Neue Wache stehen, ohne einzutreten.\n\nSchinkel baute sie 1818 als Königswache. Sechs dorische Säulen, Dreiecksgiebel, eine Nüchternheit, die der Ehrlichkeit ähnelt, ohne es zu sein. In der Deutschen Demokratischen Republik ist es das offizielle Mahnmal für die Opfer des Faschismus – hier legt der Staat seine Kränze nieder, hier stehen die Soldaten Wache, hier steht die offizielle Geschichte stramm und salutiert.\n\nIch schaue auf die Flamme, die hinten durch die Säulen brennt. Ich frage mich, wie viele Versionen der Wahrheit hier verbrannt wurden und als die einzig mögliche Wahrheit präsentiert wurden.\n\nDer Mann mit dem grauen Mantel ist nicht mehr da. Aber jetzt ist ein anderer Mann da, an der Ecke Unter den Linden und Friedrichstraße. Dunkelblauer Mantel. Er liest auch seine Zeitung nicht.\n\nZwei Beschattungen am selben Tag sind keine Routine. Zwei Beschattungen bedeuten, dass jemand sicherstellen will, dass ich an einem bestimmten Ort ankomme. Oder nicht ankomme.\n\nIch schaue auf meine Uhr: 10:48 Uhr. Zwölf Minuten bis zum Treffen.\n\nIch gehe weiter. Nicht mehr, weil ich an das Treffen glaube. Sondern weil ich sehen will, wer auf mich wartet.\n\nGeh nach Osten. Eine letzte Station vor der Zentrale.',
    'IT': 'Mi fermo davanti alla Neue Wache senza entrare.\n\nSchinkel la costruì nel 1818 come guardia reale. Sei colonne doriche, frontone triangolare, un\'austerità che assomiglia all\'onestà senza esserlo. Nella Repubblica Democratica Tedesca è il memoriale ufficiale per le vittime del fascismo – qui lo Stato depone le sue corone, qui i soldati fanno la guardia, qui la storia ufficiale si mette sull\'attenti e saluta.\n\nGuardo la fiamma che arde in fondo, attraverso le colonne. Mi chiedo quante versioni della verità siano bruciate qui, presentate come l\'unica verità possibile.\n\nL\'uomo con il cappotto grigio non c\'è più. Ma ora c\'è un altro uomo, all\'angolo tra Unter den Linden e Friedrichstrasse. Cappotto blu marino. Nemmeno lui legge il suo giornale.\n\nDue pedinamenti nello stesso giorno non sono routine. Due pedinamenti significano che qualcuno vuole assicurarsi che arrivi in un posto determinato. O che non ci arrivi.\n\nGuardo il mio orologio: le 10:48. Dodici minuti alla riunione.\n\nContinuo a camminare. Non più perché creda nella riunione. Ma perché voglio vedere chi mi sta aspettando.\n\nCammina verso est. Un\'ultima tappa prima della sede centrale.',
  },
  'klaus_09b': {
    'ES': 'Vuelvo al Nikolaiviertel. No por lógica — por instinto. Once años de trabajo me han enseñado que cuando no sabes qué hacer, vuelves al último punto donde tuviste información.\n\nLa Nikolaikirche fue fundada en torno a 1230 y es el edificio más antiguo de Berlín. Ha sobrevivido la Guerra de los Treinta Años, el incendio de 1380, los bombardeos de 1944 que la dejaron en ruinas, y la reconstrucción parcial de los años cincuenta. Sus paredes de ladrillo rojo han visto pasar ocho siglos de ciudad — imperios que llegaron y se fueron, muros que se levantaron y cayeron, versiones de la verdad que se sucedieron como los gobiernos. El edificio no tiene opinión sobre ninguna de ellas. Sigue de pie.\n\nMe siento en un banco frente a la iglesia. Saco el sobre. Lo leo por cuarta vez.\n\nNo vayas a la reunión de las once.\n\nSon las 11:03.\n\nAcabo de no ir a la reunión. No fue una decisión — fueron mis pies. Eso también es una decisión.\n\nEscucho pasos detrás de mí. No me doy la vuelta de inmediato. Termino de doblar el papel, lo guardo, cuento hasta tres.\n\nCuando me doy la vuelta hay dos hombres de pie a cuatro metros. No llevan uniforme. Eso es peor que si lo llevaran.\n\nLos miro. Me miran.\n\nNadie dice nada durante un momento que parece más largo de lo que es.\n\nEntonces sonrío. Y digo, con once años de práctica en decir lo que la situación requiere:\n\nLlegaba tarde a buscar algo que olvidé.\n\nBerlín fue una ciudad donde durante cuarenta años nadie podía estar seguro de quién estaba mirando. Donde los archivos de la Stasi contenían información sobre seis millones de personas — en una ciudad de tres. Donde los vecinos informaban sobre vecinos, los hijos sobre padres, los amantes sobre amantes.\n\nCuando el Muro cayó en 1989, los archivos fueron abiertos. Millones de personas descubrieron quién había informado sobre ellas. Berlín aprendió que la historia no se divide limpiamente en héroes y villanos. Se divide en personas que tomaron decisiones con la información que tenían, en el momento que les tocó vivir, con el miedo que cargaban.\n\nBerlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'I go back to the Nikolaiviertel. Not for logic — for instinct. Eleven years of work have taught me that when you don\'t know what to do, you go back to the last point where you had information.\n\nThe Nikolaikirche was founded around 1230 and is the oldest building in Berlin. It has survived the Thirty Years\' War, the fire of 1380, the 1944 bombings that left it in ruins, and the partial reconstruction of the fifties. Its red-brick walls have seen eight centuries of city pass — empires that came and went, walls that rose and fell, versions of the truth that succeeded each other like governments. The building has no opinion on any of them. It is still standing.\n\nI sit on a bench in front of the church. I take out the envelope. I read it for the fourth time.\n\nDo not go to the eleven o\'clock meeting.\n\nIt is 11:03.\n\nI have just not gone to the meeting. It wasn\'t a decision — it was my feet. That is also a decision.\n\nI hear footsteps behind me. I don\'t turn around immediately. I finish folding the paper, put it away, count to three.\n\nWhen I turn around there are two men standing four metres away. They are not in uniform. That is worse than if they were.\n\nI look at them. They look at me.\n\nNo one speaks for a moment that seems longer than it is.\n\nThen I smile. And say, with eleven years of practice in saying what the situation requires:\n\nI was late coming back for something I forgot.\n\nBerlin was a city where for forty years no one could be sure who was watching. Where the Stasi files held information on six million people — in a city of three. Where neighbours informed on neighbours, children on parents, lovers on lovers.\n\nWhen the Wall fell in 1989, the files were opened. Millions of people discovered who had informed on them. Berlin learned that history does not divide cleanly into heroes and villains. It divides into people who made decisions with the information they had, in the moment they were given to live, carrying the fear they carried.\n\nBerlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Ich kehre ins Nikolaiviertel zurück. Nicht aus Logik – aus Instinkt. Elf Jahre Arbeit haben mich gelehrt, dass man, wenn man nicht weiß, was man tun soll, zum letzten Punkt zurückkehrt, an dem man Informationen hatte.\n\nDie Nikolaikirche wurde um 1230 gegründet und ist das älteste Gebäude Berlins. Sie hat den Dreißigjährigen Krieg überlebt, den Brand von 1380, die Bombenangriffe von 1944, die sie in Ruinen legten, und den teilweisen Wiederaufbau der fünfziger Jahre. Ihre roten Backsteinmauern haben acht Jahrhunderte Stadt vorüberziehen sehen – Imperien, die kamen und gingen, Mauern, die errichtet wurden und fielen, Versionen der Wahrheit, die sich wie Regierungen abwechselten. Das Gebäude hat keine Meinung zu keiner von ihnen. Es steht noch.\n\nIch setze mich auf eine Bank vor der Kirche. Ich nehme den Umschlag heraus. Ich lese ihn zum vierten Mal.\n\nGeh nicht zu dem Treffen um elf.\n\nEs ist 11:03 Uhr.\n\nIch bin gerade nicht zu dem Treffen gegangen. Es war keine Entscheidung – es waren meine Füße. Das ist auch eine Entscheidung.\n\nIch höre Schritte hinter mir. Ich drehe mich nicht sofort um. Ich falte das Papier fertig, verstaue es, zähle bis drei.\n\nAls ich mich umdrehe, stehen zwei Männer vier Meter entfernt. Sie tragen keine Uniform. Das ist schlimmer als wenn sie eine hätten.\n\nIch schaue sie an. Sie schauen mich an.\n\nEinen Moment lang, der länger scheint als er ist, sagt niemand etwas.\n\nDann lächele ich. Und sage, mit elf Jahren Übung darin, das zu sagen, was die Situation erfordert:\n\nIch kam zu spät, um etwas abzuholen, das ich vergessen hatte.\n\nBerlin war vierzig Jahre lang eine Stadt, in der niemand sicher sein konnte, wer zuschaute. Wo die Stasi-Akten Informationen über sechs Millionen Menschen enthielten – in einer Stadt mit drei Millionen Einwohnern. Wo Nachbarn über Nachbarn berichteten, Kinder über Eltern, Liebhaber über Liebhaber.\n\nAls die Mauer 1989 fiel, wurden die Akten geöffnet. Millionen von Menschen erfuhren, wer über sie berichtet hatte. Berlin lernte, dass die Geschichte sich nicht sauber in Helden und Schurken unterteilt. Sie unterteilt sich in Menschen, die Entscheidungen mit den Informationen trafen, die sie hatten, in dem Moment, in dem sie lebten, mit der Angst, die sie trugen.\n\nBerlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Torno al Nikolaiviertel. Non per logica – per istinto. Undici anni di lavoro mi hanno insegnato che quando non sai cosa fare, torni all\'ultimo punto dove hai avuto informazioni.\n\nLa Nikolaikirche fu fondata intorno al 1230 ed è l\'edificio più antico di Berlino. Ha sopravvissuto alla Guerra dei Trent\'anni, all\'incendio del 1380, ai bombardamenti del 1944 che la ridussero in macerie, e alla ricostruzione parziale degli anni cinquanta. Le sue mura di mattoni rossi hanno visto passare otto secoli di città – imperi che vennero e andarono, muri che si alzarono e caddero, versioni della verità che si succedettero come i governi. L\'edificio non ha opinione su nessuna di esse. È ancora in piedi.\n\nMi siedo su una panchina davanti alla chiesa. Tiro fuori la busta. La leggo per la quarta volta.\n\nNon andare alla riunione delle undici.\n\nSono le 11:03.\n\nHo appena non partecipato alla riunione. Non fu una decisione – furono i miei piedi. Anche quello è una decisione.\n\nSento dei passi dietro di me. Non mi giro subito. Finisco di piegare il foglio, lo ripongo, conto fino a tre.\n\nQuando mi giro ci sono due uomini in piedi a quattro metri. Non indossano l\'uniforme. È peggio che se la indossassero.\n\nLi guardo. Mi guardano.\n\nNessuno dice nulla per un momento che sembra più lungo di quanto sia.\n\nPoi sorrido. E dico, con undici anni di pratica nel dire ciò che la situazione richiede:\n\nEro in ritardo per recuperare qualcosa che avevo dimenticato.\n\nBerlino è stata per quarant\'anni una città in cui nessuno poteva essere sicuro di chi stesse guardando. Dove i fascicoli della Stasi contenevano informazioni su sei milioni di persone – in una città di tre milioni. Dove i vicini denunciavano i vicini, i figli i genitori, gli amanti gli amanti.\n\nQuando il Muro cadde nel 1989, i fascicoli furono aperti. Milioni di persone scoprirono chi aveva denunciato su di loro. Berlino imparò che la storia non si divide pulitamente in eroi e villain. Si divide in persone che presero decisioni con le informazioni che avevano, nel momento in cui vissero, con la paura che portavano.\n\nBerlino è ancora qui. E anche tu. Per ora basta così.',
  },
  'clara_01': {
    'ES': 'Berlín, primavera de 1946.\n\nMe llamo Clara. Tengo nueve años y tres cuartos — los tres cuartos son importantes, por favor no los olvides.\n\nVivo en Kreuzberg con mi madre y mi abuela Oma Else. Papá no volvió de la guerra. Oma Else dice que está en un lugar mejor. Yo no sé dónde es ese lugar, pero a veces cuando el cielo se pone muy rojo por las tardes pienso que quizás se puede ver desde allá arriba.\n\nEsta mañana encontré algo.\n\nLo encontré aquí, en las ruinas de la Anhalter Bahnhof. Antes era la estación de trenes más grande de Europa — eso me lo contó el señor Krause del segundo piso, que lleva setenta y dos años en Berlín y lo sabe casi todo. La inauguraron en 1880 y llegó a tener dieciséis andenes y una sala de espera tan grande que cabían tres mil personas. Venían trenes desde Roma, desde Atenas, desde Estambul. Berlín era el lugar al que llegabas cuando venías de Europa. Ahora queda solo una pared sola que se niega a caerse. A mí me parece valiente.\n\nDebajo de un ladrillo suelto, en el rincón donde siempre juego, encontré una caja de metal pequeña. Dentro hay un papel doblado y algo más que todavía no he mirado bien.\n\nEl papel dice un nombre: Hannah Goldberg. Y una dirección.\n\nCamina cinco minutos hacia el norte. La Topographie des Terrors está justo al lado.',
    'EN': 'Berlin, spring 1946.\n\nMy name is Clara. I am nine and three-quarters years old — the three-quarters matter, please don\'t forget them.\n\nI live in Kreuzberg with my mother and my grandmother Oma Else. Papa didn\'t come back from the war. Oma Else says he is in a better place. I don\'t know where that place is, but sometimes when the sky turns very red in the evenings I think maybe you can see it from up there.\n\nThis morning I found something.\n\nI found it here, in the ruins of Anhalter Bahnhof. It used to be the largest train station in Europe — that\'s what Mr Krause on the second floor told me; he has lived in Berlin for seventy-two years and knows almost everything. It opened in 1880 and had sixteen platforms and a waiting room big enough for three thousand people. Trains came from Rome, from Athens, from Istanbul. Berlin was the place you arrived at when you came from Europe. Now there is just a single wall standing, refusing to fall. I think that\'s brave.\n\nUnder a loose brick, in the corner where I always play, I found a small metal box. Inside there is a folded piece of paper and something else I haven\'t looked at closely yet.\n\nThe paper says a name: Hannah Goldberg. And an address.\n\nWalk five minutes north. The Topographie des Terrors is just beside it.',
    'DE': 'Berlin, Frühjahr 1946.\n\nIch heiße Clara. Ich bin neun Jahre und drei Viertel alt – die drei Viertel sind wichtig, bitte vergiss sie nicht.\n\nIch lebe in Kreuzberg mit meiner Mutter und meiner Oma Else. Papa kam nicht aus dem Krieg zurück. Oma Else sagt, er ist an einem besseren Ort. Ich weiß nicht, wo dieser Ort ist, aber manchmal, wenn der Himmel nachmittags sehr rot wird, denke ich, dass man ihn vielleicht von dort oben sehen kann.\n\nHeute Morgen habe ich etwas gefunden.\n\nIch habe es hier gefunden, in den Ruinen des Anhalter Bahnhofs. Früher war er der größte Bahnhof Europas – das hat mir Herr Krause aus dem zweiten Stock erzählt, der seit zweiundsiebzig Jahren in Berlin lebt und fast alles weiß. Er wurde 1880 eingeweiht und hatte sechzehn Bahnsteige und eine Wartehalle, in die dreitausend Menschen passten. Züge kamen aus Rom, aus Athen, aus Istanbul. Berlin war der Ort, an dem man ankam, wenn man aus Europa kam. Jetzt bleibt nur eine einzelne Wand übrig, die sich weigert umzufallen. Mir scheint das mutig.\n\nUnter einem losen Ziegelstein, in der Ecke, wo ich immer spiele, fand ich eine kleine Metalldose. Darin liegt ein gefaltetes Papier und noch etwas, das ich noch nicht genau angeschaut habe.\n\nAuf dem Papier steht ein Name: Hannah Goldberg. Und eine Adresse.\n\nGeh fünf Minuten nach Norden. Die Topographie des Terrors ist gleich nebenan.',
    'IT': 'Berlino, primavera 1946.\n\nMi chiamo Clara. Ho nove anni e tre quarti – i tre quarti sono importanti, per favore non dimenticarli.\n\nVivo a Kreuzberg con mia madre e mia nonna Oma Else. Papà non è tornato dalla guerra. Oma Else dice che è in un posto migliore. Non so dove sia quel posto, ma a volte quando il cielo diventa molto rosso nel pomeriggio penso che forse si può vedere da lassù.\n\nStamattina ho trovato qualcosa.\n\nL\'ho trovato qui, tra le rovine dell\'Anhalter Bahnhof. Prima era la stazione ferroviaria più grande d\'Europa – me l\'ha detto il signor Krause del secondo piano, che vive a Berlino da settantadue anni e sa quasi tutto. Fu inaugurata nel 1880 e aveva sedici binari e una sala d\'attesa così grande che ci stavano tremila persone. Arrivavano treni da Roma, da Atene, da Istanbul. Berlino era il posto in cui arrivavi quando venivi dall\'Europa. Ora rimane solo un muro solitario che si rifiuta di cadere. A me sembra coraggioso.\n\nSotto un mattone allentato, nell\'angolo dove gioco sempre, ho trovato una piccola scatola di metallo. Dentro c\'è un foglio piegato e qualcos\'altro che non ho ancora guardato bene.\n\nIl foglio dice un nome: Hannah Goldberg. E un indirizzo.\n\nCammina cinque minuti verso nord. La Topographie des Terrors è proprio accanto.',
  },
  'clara_02': {
    'ES': 'Aquí hubo un edificio muy grande y muy malo.\n\nEn este solar, entre 1933 y 1945, estaban las oficinas centrales de la Gestapo, las SS y el SD — los servicios secretos del régimen nazi. Desde aquí se planificó y coordinó el terror de doce años: los campos de concentración, las deportaciones, las ejecuciones. Las personas que trabajaban en estos edificios llevaban uniformes y tenían escritorios y archivos y tomaban café por las mañanas. Esa es la parte que más me cuesta entender cuando el maestro lo explica: que las cosas más malas de la historia las hicieron personas normales con café.\n\nLos edificios fueron destruidos por los bombardeos de 1945. Ahora solo quedan los sótanos — los cimientos de algo que existió y que nadie quiere reconstruir. Me parecen las raíces de un árbol enorme que ya no existe. El árbol cayó, pero las raíces siguen debajo, recordando.\n\nBusqué el nombre del papel. En la dirección de Hannah Goldberg no vive nadie que se llame así. La vecina del primero, la señora Brandt, me dijo que los Goldberg se fueron hace mucho tiempo. No quiso decir adónde.\n\nPero yo sé adónde se fue la gente que se fue. Lo aprendí en el colegio aunque la maestra no lo dijo con esas palabras exactas.\n\nDentro de la caja, además del papel, hay una llave pequeña y dorada.\n\nCamina hacia el norte por Friedrichstrasse. Checkpoint Charlie está a ocho minutos.',
    'EN': 'There was a very large and very bad building here.\n\nIn this plot of ground, between 1933 and 1945, stood the central offices of the Gestapo, the SS and the SD — the secret services of the Nazi regime. From here the terror of twelve years was planned and coordinated: the concentration camps, the deportations, the executions. The people who worked in these buildings wore uniforms and had desks and files and drank coffee in the mornings. That is the part I find hardest to understand when the teacher explains it: that the worst things in history were done by ordinary people with coffee.\n\nThe buildings were destroyed by the 1945 bombings. Now only the basements remain — the foundations of something that existed and that no one wants to rebuild. They seem to me like the roots of an enormous tree that no longer exists. The tree fell, but the roots are still below, remembering.\n\nI looked up the name on the paper. At Hannah Goldberg\'s address, no one by that name lives there. The neighbour on the first floor, Mrs Brandt, told me the Goldbergs left a long time ago. She didn\'t want to say where.\n\nBut I know where the people who left went. I learned it at school, even if the teacher didn\'t say it in those exact words.\n\nInside the box, besides the paper, there is a small golden key.\n\nWalk north along Friedrichstrasse. Checkpoint Charlie is eight minutes away.',
    'DE': 'Hier stand ein sehr großes und sehr böses Gebäude.\n\nAuf diesem Gelände standen zwischen 1933 und 1945 die Hauptquartiere der Gestapo, der SS und des SD – die Geheimdienste des Nazi-Regimes. Von hier aus wurden der Terror von zwölf Jahren geplant und koordiniert: die Konzentrationslager, die Deportationen, die Hinrichtungen. Die Menschen, die in diesen Gebäuden arbeiteten, trugen Uniformen und hatten Schreibtische und Akten und tranken morgens Kaffee. Das ist der Teil, den ich am schwersten verstehen kann, wenn der Lehrer es erklärt: dass die schlimmsten Dinge der Geschichte von normalen Menschen mit Kaffee gemacht wurden.\n\nDie Gebäude wurden durch die Bombenangriffe von 1945 zerstört. Jetzt sind nur noch die Keller übrig – die Fundamente von etwas, das existierte und das niemand wiederaufbauen möchte. Sie erscheinen mir wie die Wurzeln eines riesigen Baumes, der nicht mehr existiert. Der Baum fiel, aber die Wurzeln sind noch unten und erinnern sich.\n\nIch suchte nach dem Namen auf dem Zettel. An der Adresse von Hannah Goldberg wohnt niemand mit diesem Namen. Die Nachbarin aus dem ersten Stock, Frau Brandt, sagte mir, die Goldbergs seien vor langer Zeit weggegangen. Sie wollte nicht sagen, wohin.\n\nAber ich weiß, wohin die Menschen gegangen sind, die weggegangen sind. Das habe ich in der Schule gelernt, auch wenn die Lehrerin es nicht mit genau diesen Worten sagte.\n\nIn der Dose gibt es außer dem Papier noch einen kleinen goldenen Schlüssel.\n\nGeh nach Norden entlang der Friedrichstraße. Checkpoint Charlie ist acht Minuten entfernt.',
    'IT': 'Qui c\'era un edificio molto grande e molto cattivo.\n\nIn questo terreno, tra il 1933 e il 1945, si trovavano i quartieri generali della Gestapo, delle SS e dell\'SD – i servizi segreti del regime nazista. Da qui fu pianificato e coordinato il terrore di dodici anni: i campi di concentramento, le deportazioni, le esecuzioni. Le persone che lavoravano in questi edifici indossavano uniformi e avevano scrivanie e fascicoli e bevevano caffè la mattina. Questa è la parte che faccio più fatica a capire quando il maestro lo spiega: che le cose peggiori della storia le hanno fatte persone normali con il caffè.\n\nGli edifici furono distrutti dai bombardamenti del 1945. Ora rimangono solo le cantine – le fondamenta di qualcosa che esistette e che nessuno vuole ricostruire. Mi sembrano le radici di un albero enorme che non esiste più. L\'albero cadde, ma le radici sono ancora sotto, a ricordare.\n\nHo cercato il nome sul foglio. All\'indirizzo di Hannah Goldberg non vive nessuno con quel nome. La vicina del primo piano, la signora Brandt, mi disse che i Goldberg se ne erano andati molto tempo fa. Non volle dire dove.\n\nMa io so dove andò la gente che se ne andò. L\'ho imparato a scuola anche se la maestra non lo disse con quelle parole esatte.\n\nNella scatola, oltre al foglio, c\'è una piccola chiave dorata.\n\nCammina verso nord lungo la Friedrichstrasse. Checkpoint Charlie è a otto minuti.',
  },
  'clara_03': {
    'ES': 'Aquí Berlín se parte en dos.\n\nDe un lado están los americanos. Del otro están los soviéticos. En el medio hay una caseta y unos soldados que miran a todo el mundo con cara seria. Yo los miro también con cara seria, para que sepan que yo también soy seria.\n\nEl Checkpoint Charlie lleva abierto desde 1961, cuando construyeron el Muro. Antes de eso, Berlín era una sola ciudad aunque estuviera dividida en cuatro sectores. Ahora hay alambre de espino y torres de vigilancia y una franja de tierra en el medio donde nadie puede entrar. Los americanos llaman a ese paso Charlie porque en el alfabeto fonético de la OTAN la C es Charlie — el tercer punto de control después de Alfa y Bravo. Mi ciudad tiene un nombre sacado de un alfabeto de guerra.\n\nOma Else dice que antes era una sola ciudad. Yo no me acuerdo — tenía tres años cuando empezó la guerra. Para mí Berlín siempre ha sido un sitio lleno de ruinas y de soldados con banderas distintas.\n\nLe pregunté a un soldado americano — el más joven, que a veces me da chocolate — si sabía algo de una familia Goldberg. Me miró muy serio y me dijo en alemán con acento raro: niña, hay cosas que es mejor no preguntar.\n\nTodo el mundo me dice eso. Eso me hace querer preguntar más.\n\nCamina hacia el norte por Friedrichstrasse y luego gira a la izquierda. El Gendarmenmarkt está a ocho minutos.',
    'EN': 'Here Berlin breaks in two.\n\nOn one side are the Americans. On the other are the Soviets. In the middle there is a booth and some soldiers who look at everyone with a serious face. I look at them seriously too, so they know I am serious as well.\n\nCheckpoint Charlie has been open since 1961, when they built the Wall. Before that, Berlin was one city even if it was divided into four sectors. Now there is barbed wire and watchtowers and a strip of land in the middle where no one can go. The Americans call the crossing Charlie because in the NATO phonetic alphabet C is Charlie — the third checkpoint after Alpha and Bravo. My city has a name taken from a war alphabet.\n\nOma Else says it used to be one city. I don\'t remember — I was three when the war started. For me Berlin has always been a place full of ruins and soldiers with different flags.\n\nI asked one of the American soldiers — the youngest one, who sometimes gives me chocolate — whether he knew anything about a family called Goldberg. He looked at me very seriously and said in German with a strange accent: little girl, there are some things it\'s better not to ask about.\n\nEveryone says that to me. That makes me want to ask more.\n\nWalk north along Friedrichstrasse and then turn left. The Gendarmenmarkt is eight minutes away.',
    'DE': 'Hier teilt sich Berlin in zwei.\n\nAuf einer Seite sind die Amerikaner. Auf der anderen die Sowjets. Dazwischen gibt es eine Hütte und Soldaten, die alle ernst anschauen. Ich schaue sie auch ernst an, damit sie wissen, dass ich auch ernst bin.\n\nCheckpoint Charlie ist seit 1961 offen, als sie die Mauer bauten. Davor war Berlin eine einzige Stadt, auch wenn sie in vier Sektoren aufgeteilt war. Jetzt gibt es Stacheldraht und Wachtürme und einen Streifen Land in der Mitte, wo niemand betreten darf. Die Amerikaner nennen den Übergang Charlie, weil im NATO-Buchstabieralphabet das C Charlie ist – der dritte Kontrollpunkt nach Alpha und Bravo. Meine Stadt trägt einen Namen aus einem Kriegsalphabet.\n\nOma Else sagt, früher war es eine einzige Stadt. Ich erinnere mich nicht daran – ich war drei Jahre alt, als der Krieg begann. Für mich war Berlin immer ein Ort voller Ruinen und Soldaten mit verschiedenen Fahnen.\n\nIch fragte einen amerikanischen Soldaten – den jüngsten, der mir manchmal Schokolade gibt – ob er etwas von einer Familie Goldberg wüsste. Er schaute mich sehr ernst an und sagte auf Deutsch mit komischem Akzent: Mädchen, es gibt Dinge, nach denen man besser nicht fragt.\n\nAlle sagen mir das. Das macht mich wollen, noch mehr zu fragen.\n\nGeh nach Norden entlang der Friedrichstraße und biege dann links ab. Der Gendarmenmarkt ist acht Minuten entfernt.',
    'IT': 'Qui Berlino si divide in due.\n\nDa un lato ci sono gli americani. Dall\'altro i sovietici. In mezzo c\'è una guardiola e dei soldati che guardano tutti con faccia seria. Li guardo anch\'io con faccia seria, così sanno che anch\'io sono seria.\n\nIl Checkpoint Charlie è aperto dal 1961, quando costruirono il Muro. Prima Berlino era una città sola anche se divisa in quattro settori. Ora c\'è filo spinato e torri di guardia e una striscia di terra nel mezzo dove nessuno può entrare. Gli americani chiamano quel valico Charlie perché nell\'alfabeto fonetico della NATO la C è Charlie – il terzo punto di controllo dopo Alfa e Bravo. La mia città ha un nome preso da un alfabeto di guerra.\n\nOma Else dice che prima era una città sola. Non me lo ricordo – avevo tre anni quando iniziò la guerra. Per me Berlino è sempre stato un posto pieno di rovine e soldati con bandiere diverse.\n\nChiesi a un soldato americano – il più giovane, che a volte mi dà il cioccolato – se sapesse qualcosa di una famiglia Goldberg. Mi guardò molto serio e disse in tedesco con uno strano accento: bambina, ci sono cose che è meglio non chiedere.\n\nMe lo dicono tutti. Questo mi fa venir voglia di chiedere ancora di più.\n\nCammina verso nord lungo la Friedrichstrasse e poi gira a sinistra. Il Gendarmenmarkt è a otto minuti.',
  },
  'clara_04': {
    'ES': 'El Gendarmenmarkt es la plaza más bonita de Berlín. Eso lo dice todo el mundo — o lo decía, antes. Ahora está un poco rota, como casi todo, pero aun así se puede ver que fue muy bonita y que lo volverá a ser.\n\nHay dos iglesias iguales, una a cada lado, como si fueran gemelas que se miran sin cansarse. El Französischer Dom — la Catedral Francesa — fue construido en 1705 para los hugonotes, los protestantes franceses que huyeron de Francia cuando el rey los expulsó. Eran cincuenta mil personas que llegaron a Prusia con sus oficios y su lengua y sus costumbres. El Gendarmenmarkt lo construyeron para ellos, en el centro de su barrio. Oma Else me explicó que Berlín siempre ha sido una ciudad de gente que llegó de otro lugar buscando quedarse.\n\nMe siento en los escalones del Konzerthaus y abro la caja otra vez.\n\nAdemás de la llave y el papel, hay una fotografía del tamaño de un sello de correos. En la foto hay una niña. Tiene más o menos mi edad. El pelo oscuro y rizado y mira a la cámara como si acabara de pensar algo importante.\n\nAl dorso, con letra muy pequeña: Hannah, 1938.\n\nLa miro mucho rato. Ella también tenía nueve años. O casi.\n\nCamina hacia el norte. La Bebelplatz está a ocho minutos.',
    'EN': 'The Gendarmenmarkt is the most beautiful square in Berlin. That\'s what everyone says — or used to say. Now it\'s a little broken, like almost everything, but you can still see that it was very beautiful and will be again.\n\nThere are two identical churches, one on each side, as if they were twins looking at each other without getting tired. The Französischer Dom — the French Cathedral — was built in 1705 for the Huguenots, the French Protestants who fled France when the king expelled them. They were fifty thousand people who came to Prussia with their trades and their language and their customs. The Gendarmenmarkt was built for them, in the centre of their neighbourhood. Oma Else explained that Berlin has always been a city of people who came from somewhere else looking to stay.\n\nI sit on the steps of the Konzerthaus and open the box again.\n\nBesides the key and the paper, there is a photograph the size of a postage stamp. In the photo there is a girl. She is about my age. Dark curly hair and she looks at the camera as if she has just thought of something important.\n\nOn the back, in very small writing: Hannah, 1938.\n\nI look at her for a long time. She was nine years old too. Or nearly.\n\nWalk north. The Bebelplatz is eight minutes away.',
    'DE': 'Der Gendarmenmarkt ist der schönste Platz Berlins. Das sagen alle – oder sagten es, früher. Jetzt ist er ein bisschen kaputt, wie fast alles, aber man kann trotzdem sehen, dass er sehr schön war und es wieder sein wird.\n\nEs gibt zwei identische Kirchen, eine auf jeder Seite, wie Zwillinge, die sich ohne Ermüdung anschauen. Der Französische Dom wurde 1705 für die Hugenotten gebaut, die protestantischen Franzosen, die aus Frankreich flohen, als der König sie vertrieb. Es waren fünfzigtausend Menschen, die nach Preußen kamen mit ihren Handwerken und ihrer Sprache und ihren Bräuchen. Der Gendarmenmarkt wurde für sie gebaut, im Zentrum ihres Viertels. Oma Else erklärte mir, dass Berlin immer eine Stadt von Menschen war, die von woanders kamen und nach einem Zuhause suchten.\n\nIch setze mich auf die Stufen des Konzerthauses und öffne die Dose wieder.\n\nAußer dem Schlüssel und dem Papier gibt es ein Foto in der Größe einer Briefmarke. Auf dem Foto ist ein Mädchen. Sie ist ungefähr in meinem Alter. Das Haar ist dunkel und lockig und sie schaut in die Kamera, als hätte sie gerade etwas Wichtiges gedacht.\n\nAuf der Rückseite, in sehr kleiner Schrift: Hannah, 1938.\n\nIch schaue sie lange an. Sie war auch neun Jahre alt. Oder fast.\n\nGeh nach Norden. Die Bebelplatz ist acht Minuten entfernt.',
    'IT': 'Il Gendarmenmarkt è la piazza più bella di Berlino. Lo dicono tutti – o lo dicevano, prima. Ora è un po\' rotta, come quasi tutto, ma si vede lo stesso che fu molto bella e che lo sarà di nuovo.\n\nCi sono due chiese identiche, una per lato, come se fossero gemelle che si guardano senza stancarsi. Il Französischer Dom fu costruito nel 1705 per gli ugonotti, i protestanti francesi che fuggirono dalla Francia quando il re li espulse. Erano cinquantamila persone che arrivarono in Prussia con i loro mestieri e la loro lingua e le loro usanze. Il Gendarmenmarkt fu costruito per loro, nel centro del loro quartiere. Oma Else mi spiegò che Berlino è sempre stata una città di gente arrivata da un altro posto in cerca di restare.\n\nMi siedo sui gradini del Konzerthaus e apro di nuovo la scatola.\n\nOltre alla chiave e al foglio, c\'è una fotografia delle dimensioni di un francobollo. Nella foto c\'è una bambina. Ha più o meno la mia età. I capelli sono scuri e ricci e guarda la macchina fotografica come se avesse appena pensato qualcosa di importante.\n\nSul retro, con scrittura molto piccola: Hannah, 1938.\n\nLa guardo a lungo. Anche lei aveva nove anni. O quasi.\n\nCammina verso nord. La Bebelplatz è a otto minuti.',
  },
  'clara_05': {
    'ES': 'Aquí quemaron libros.\n\nEl 10 de mayo de 1933, en esta misma plaza, estudiantes universitarios y profesores trajeron camiones cargados de libros y los quemaron en una hoguera. Más de veinte mil libros en una sola noche. Los de Freud, que escribió sobre la mente humana. Los de Marx, que escribió sobre la economía. Los de Kästner, que escribió sobre los niños — su libro Emil und die Detektive lo quemaron mientras él miraba desde la multitud. Kästner fue el único de los autores perseguidos que se quedó para ver cómo quemaban sus propios libros.\n\nFrente a esta plaza está la Staatsoper, la ópera más antigua de Prusia, construida por Federico el Grande en 1742. Y la Biblioteca Estatal, donde hay cientos de miles de libros. Los nazis quemaron libros delante de una biblioteca. Eso también me cuesta entenderlo.\n\nMe quedo parada en el centro de la plaza y miro el suelo. Adoquines y más adoquines. Si te quedas muy quieta puedes casi escuchar el silencio de todos esos libros que ya no existen.\n\nLa llave dorada brilla en mi mano. Pienso en Hannah mirando a la cámara en 1938 con cara de estar pensando algo importante. Me pregunto si la llave abre algo que escondió antes de irse.\n\nCamina hacia el este por Unter den Linden. El bulevar grande con los tilos — dos minutos.',
    'EN': 'They burned books here.\n\nOn 10 May 1933, in this very square, university students and professors brought trucks loaded with books and burned them in a bonfire. More than twenty thousand books in a single night. Freud\'s, who wrote about the human mind. Marx\'s, who wrote about economics. Kästner\'s, who wrote about children — his book Emil and the Detectives was burned while he watched from the crowd. Kästner was the only one of the persecuted authors who stayed to watch his own books burn.\n\nIn front of this square stands the Staatsoper, the oldest opera house in Prussia, built by Frederick the Great in 1742. And the State Library, where there are hundreds of thousands of books. The Nazis burned books in front of a library. That is also something I find hard to understand.\n\nI stand in the centre of the square and look at the ground. Cobblestones and more cobblestones. If you stay very still you can almost hear the silence of all those books that no longer exist.\n\nThe golden key shines in my hand. I think about Hannah looking at the camera in 1938 with a face like she is thinking about something important. I wonder if the key opens something she hid before she left.\n\nWalk east along Unter den Linden. The wide boulevard with the linden trees — two minutes.',
    'DE': 'Hier haben sie Bücher verbrannt.\n\nAm 10. Mai 1933, auf genau diesem Platz, brachten Universitätsstudenten und Professoren Lastwagen voller Bücher und verbrannten sie in einem Feuer. Mehr als zwanzigtausend Bücher in einer einzigen Nacht. Die von Freud, der über den menschlichen Geist schrieb. Die von Marx, der über Wirtschaft schrieb. Die von Kästner, der über Kinder schrieb – sein Buch Emil und die Detektive verbrannten sie, während er von der Menge aus zuschaute. Kästner war der einzige der verfolgten Autoren, der blieb, um zu sehen, wie seine eigenen Bücher verbrannt wurden.\n\nGegenüber diesem Platz steht die Staatsoper, die älteste Oper Preußens, 1742 von Friedrich dem Großen erbaut. Und die Staatsbibliothek, wo es Hunderttausende von Büchern gibt. Die Nazis verbrannten Bücher vor einer Bibliothek. Das verstehe ich auch schwer.\n\nIch stehe in der Mitte des Platzes und schaue auf den Boden. Pflastersteine und mehr Pflastersteine. Wenn man ganz still bleibt, kann man fast die Stille all der Bücher hören, die nicht mehr existieren.\n\nDer goldene Schlüssel glänzt in meiner Hand. Ich denke an Hannah, die 1938 in die Kamera schaut mit dem Gesicht von jemandem, der gerade etwas Wichtiges denkt. Ich frage mich, ob der Schlüssel etwas öffnet, das sie versteckte, bevor sie wegging.\n\nGeh nach Osten entlang der Unter den Linden. Der große Boulevard mit den Linden – zwei Minuten.',
    'IT': 'Qui hanno bruciato i libri.\n\nIl 10 maggio 1933, in questa stessa piazza, studenti universitari e professori portarono camion carichi di libri e li bruciarono in un rogo. Più di ventimila libri in una sola notte. Quelli di Freud, che scrisse della mente umana. Quelli di Marx, che scrisse di economia. Quelli di Kästner, che scrisse di bambini – il suo libro Emil und die Detektive lo bruciarono mentre lui guardava dalla folla. Kästner fu l\'unico degli autori perseguitati che rimase a vedere bruciare i propri libri.\n\nDi fronte a questa piazza c\'è la Staatsoper, la più antica opera della Prussia, costruita da Federico il Grande nel 1742. E la Biblioteca di Stato, dove ci sono centinaia di migliaia di libri. I nazisti bruciarono libri davanti a una biblioteca. Anche questo faccio fatica a capirlo.\n\nRimango in piedi al centro della piazza e guardo il pavimento. Selci e ancora selci. Se stai molto ferma puoi quasi sentire il silenzio di tutti quei libri che non esistono più.\n\nLa chiave dorata brilla nella mia mano. Penso a Hannah che guarda la macchina fotografica nel 1938 con la faccia di qualcuno che sta pensando qualcosa di importante. Mi chiedo se la chiave apra qualcosa che nascose prima di andarsene.\n\nCammina verso est lungo Unter den Linden. Il viale grande con i tigli – due minuti.',
  },
  'clara_06': {
    'ES': 'Unter den Linden significa bajo los tilos. Es el bulevar más importante de Berlín — dos kilómetros desde el Palacio hasta la Puerta de Brandenburgo, con cuatro filas de tilos en el centro que en verano hacen sombra y huelen muy bien. Federico el Grande lo mandó plantar con nogales en el siglo XVII. Los nogales fueron sustituidos por tilos en el siglo XIX. En 1935 los nazis los talaron para hacer el bulevar más ancho para los desfiles. Los replantaron en 1952. Ahora tienen cuatro años y todavía son pequeños — hojitas nuevas, brillantes, como si la calle estuviera estrenando algo.\n\nLa dirección del papel dice Unter den Linden 17. Hay un solar vacío donde hubo un edificio. Pero justo al lado hay una puerta que no pertenece a ningún edificio. Una puerta sola, de madera oscura, con una cerradura pequeña y dorada.\n\nMiro la cerradura. Miro la llave.\n\nLas cerraduras y las llaves se reconocen. Como las personas que se conocen de antes.\n\nMeto la llave. Gira.\n\nLa puerta abre a un sótano pequeño con una escalera de piedra. Abajo hay luz — no mucha, pero hay. Y libros. Muchísimos libros apilados hasta el techo, con letras que reconozco porque Oma Else me enseñó: letras hebreas.\n\nHannah escondió una biblioteca.\n\nAquí la historia se divide. Si decides contarlo, camina hacia la Neue Wache. Si decides guardarlo, camina hacia el Nikolaiviertel.',
    'EN': 'Unter den Linden means under the linden trees. It is Berlin\'s most important boulevard — two kilometres from the Palace to the Brandenburg Gate, with four rows of linden trees down the centre that give shade in summer and smell wonderful. Frederick the Great had it planted with walnut trees in the 17th century. The walnuts were replaced by lindens in the 19th century. In 1935 the Nazis cut them all down to widen the boulevard for parades. They were replanted in 1952. Now they are four years old and still small — little new leaves, shiny, as if the street is wearing something new.\n\nThe address on the paper says Unter den Linden 17. There is an empty lot where a building once stood. But right next to the lot there is a door that doesn\'t belong to any building. A single door, dark wood, with a small golden lock.\n\nI look at the lock. I look at the key.\n\nLocks and keys recognise each other. Like people who know each other from before.\n\nI put the key in. It turns.\n\nThe door opens to a small basement with a stone staircase. Below there is light — not much, but there is some. And books. Many many books stacked to the ceiling, with letters I recognise because Oma Else taught me: Hebrew letters.\n\nHannah hid a library.\n\nThe story divides here. If you decide to tell someone, walk toward the Neue Wache. If you decide to keep the secret, walk toward the Nikolaiviertel.',
    'DE': 'Unter den Linden bedeutet unter den Linden. Es ist der wichtigste Boulevard Berlins – zwei Kilometer vom Schloss bis zum Brandenburger Tor, mit vier Lindenreihen in der Mitte, die im Sommer Schatten spenden und wunderbar duften. Friedrich der Große ließ ihn im 17. Jahrhundert mit Walnussbäumen bepflanzen. Die Walnussbäume wurden im 19. Jahrhundert durch Linden ersetzt. 1935 fällten die Nazis sie, um den Boulevard für Aufmärsche zu verbreitern. Sie wurden 1952 neu gepflanzt. Jetzt sind sie vier Jahre alt und noch klein – neue, glänzende Blättchen, als würde die Straße gerade etwas Neues anziehen.\n\nDie Adresse auf dem Zettel lautet Unter den Linden 17. Es gibt ein leeres Grundstück, wo einmal ein Gebäude stand. Aber gleich daneben gibt es eine Tür, die zu keinem Gebäude gehört. Eine einzelne Tür aus dunklem Holz, mit einem kleinen goldenen Schloss.\n\nIch schaue auf das Schloss. Ich schaue auf den Schlüssel.\n\nSchlösser und Schlüssel erkennen sich. Wie Menschen, die sich von früher kennen.\n\nIch stecke den Schlüssel rein. Er dreht sich.\n\nDie Tür öffnet sich zu einem kleinen Keller mit einer Steintreppe. Unten ist Licht – nicht viel, aber es ist da. Und Bücher. Sehr viele Bücher, bis zur Decke gestapelt, mit Buchstaben, die ich erkenne, weil Oma Else sie mir beibrachte: hebräische Buchstaben.\n\nHannah hat eine Bibliothek versteckt.\n\nHier teilt sich die Geschichte. Wenn du dich entscheidest, es zu erzählen, geh zur Neue Wache. Wenn du dich entscheidest, es zu bewahren, geh zum Nikolaiviertel.',
    'IT': 'Unter den Linden significa sotto i tigli. È il viale più importante di Berlino – due chilometri dal Palazzo alla Porta di Brandeburgo, con quattro file di tigli al centro che d\'estate fanno ombra e profumano molto bene. Federico il Grande lo fece piantare con noci nel XVII secolo. I noci furono sostituiti dai tigli nel XIX secolo. Nel 1935 i nazisti li abbatterono per allargare il viale per le sfilate. Li ripiantarono nel 1952. Ora hanno quattro anni e sono ancora piccoli – foglioline nuove, lucenti, come se la strada stesse indossando qualcosa di nuovo.\n\nL\'indirizzo sul foglio dice Unter den Linden 17. C\'è un terreno vuoto dove c\'era un edificio. Ma proprio accanto c\'è una porta che non appartiene a nessun edificio. Una porta solitaria di legno scuro, con una piccola serratura dorata.\n\nGuardo la serratura. Guardo la chiave.\n\nLe serrature e le chiavi si riconoscono. Come le persone che si conoscono da prima.\n\nInfilo la chiave. Gira.\n\nLa porta si apre su una piccola cantina con una scala di pietra. Sotto c\'è luce – non molta, ma c\'è. E libri. Moltissimi libri accatastati fino al soffitto, con lettere che riconosco perché Oma Else me le ha insegnate: lettere ebraiche.\n\nHannah ha nascosto una biblioteca.\n\nQui la storia si divide. Se decidi di raccontarlo, cammina verso la Neue Wache. Se decidi di tenerlo segreto, cammina verso il Nikolaiviertel.',
  },
  'clara_07a': {
    'ES': 'Decido contarlo.\n\nCamino hacia la Neue Wache. Es un memorial — un lugar donde la gente recuerda a los que se fueron. Me parece el lugar correcto para pensar antes de hablar.\n\nLa Neue Wache fue construida en 1818 por Karl Friedrich Schinkel, el arquitecto más importante del Berlín del siglo XIX. Schinkel diseñó la ciudad entera: puentes, museos, teatros, iglesias. Quería que Berlín tuviera una coherencia visual, que cada edificio hablara con los demás. La Neue Wache tiene seis columnas y un frontón y parece un templo griego pequeño y serio en el medio de Unter den Linden. Por fuera parece saber exactamente lo que es. Por dentro es más complicado.\n\nEntro. Hay una llama pequeña que arde sola en el centro del cuarto oscuro. Hay silencio. No el silencio vacío sino el silencio lleno — como cuando una habitación tiene muchas personas que no hablan pero piensan todas al mismo tiempo.\n\nMe siento en el suelo frío.\n\nPienso en Hannah guardando esos libros uno por uno. Llevándolos al sótano de noche, con cuidado, para que no los vieran. Una niña de nueve años haciendo algo que los adultos no se atrevieron a hacer.\n\nSi cuento el secreto, los libros vivirán. Si los libros viven, algo de Hannah vive también.\n\nMe levanto. Ya sé lo que voy a hacer.\n\nCamina hacia el este. El Lustgarten está a cinco minutos.',
    'EN': 'I decide to tell someone.\n\nI walk toward the Neue Wache. It is a memorial — a place where people remember those who are gone. It seems the right place to think before speaking.\n\nThe Neue Wache was built in 1818 by Karl Friedrich Schinkel, the most important architect of 19th-century Berlin. Schinkel designed the whole city: bridges, museums, theatres, churches. He wanted Berlin to have visual coherence, for each building to speak to the others. The Neue Wache has six columns and a pediment and looks like a small serious Greek temple in the middle of Unter den Linden. On the outside it seems to know exactly what it is. Inside it is more complicated.\n\nI go in. There is a small flame burning alone in the centre of the dark room. There is silence. Not the empty silence but the full silence — like when a room has many people who are not speaking but all thinking at the same time.\n\nI sit down on the cold floor.\n\nI think about Hannah carrying those books one by one. Bringing them to the basement at night, carefully, so no one would see. A nine-year-old girl doing something that grown-ups didn\'t dare to do.\n\nIf I tell the secret, the books will live. If the books live, something of Hannah lives too.\n\nI stand up. I know what I am going to do.\n\nWalk east. The Lustgarten is five minutes away.',
    'DE': 'Ich entscheide mich, es zu erzählen.\n\nIch gehe zur Neue Wache. Es ist ein Mahnmal – ein Ort, an dem Menschen derer gedenken, die gegangen sind. Es erscheint mir der richtige Ort, um nachzudenken, bevor ich spreche.\n\nDie Neue Wache wurde 1818 von Karl Friedrich Schinkel erbaut, dem wichtigsten Architekten Berlins des 19. Jahrhunderts. Schinkel entwarf die ganze Stadt: Brücken, Museen, Theater, Kirchen. Er wollte, dass Berlin eine visuelle Kohärenz hat, dass jedes Gebäude mit den anderen spricht. Die Neue Wache hat sechs Säulen und einen Giebel und sieht aus wie ein kleiner, ernster griechischer Tempel in der Mitte der Unter den Linden. Von außen scheint sie genau zu wissen, was sie ist. Von innen ist es komplizierter.\n\nIch betrete sie. Es gibt eine kleine Flamme, die allein in der Mitte des dunklen Raums brennt. Es herrscht Stille. Nicht die leere Stille, sondern die volle – wie wenn ein Zimmer viele Menschen hat, die nicht reden, aber alle gleichzeitig denken.\n\nIch setze mich auf den kalten Boden.\n\nIch denke an Hannah, die diese Bücher einen nach dem anderen einlagerte. Sie nachts in den Keller trug, vorsichtig, damit niemand sie sah. Ein neunjähriges Mädchen, das etwas tat, das die Erwachsenen sich nicht trauten.\n\nWenn ich das Geheimnis erzähle, werden die Bücher leben. Wenn die Bücher leben, lebt auch etwas von Hannah.\n\nIch stehe auf. Ich weiß jetzt, was ich tun werde.\n\nGeh nach Osten. Der Lustgarten ist fünf Minuten entfernt.',
    'IT': 'Decido di raccontarlo.\n\nCammino verso la Neue Wache. È un memoriale – un posto dove la gente ricorda chi se ne andò. Mi sembra il posto giusto per pensare prima di parlare.\n\nLa Neue Wache fu costruita nel 1818 da Karl Friedrich Schinkel, l\'architetto più importante della Berlino del XIX secolo. Schinkel progettò l\'intera città: ponti, musei, teatri, chiese. Voleva che Berlino avesse una coerenza visiva, che ogni edificio parlasse con gli altri. La Neue Wache ha sei colonne e un frontone e sembra un piccolo, serio tempio greco in mezzo a Unter den Linden. Dall\'esterno sembra sapere esattamente cosa è. Dall\'interno è più complicato.\n\nEntro. C\'è una piccola fiamma che brucia da sola al centro della stanza buia. C\'è silenzio. Non il silenzio vuoto, ma quello pieno – come quando una stanza ha molte persone che non parlano ma pensano tutte allo stesso tempo.\n\nMi siedo sul pavimento freddo.\n\nPenso a Hannah che portava quei libri uno per uno. Li portava nella cantina di notte, con cautela, perché nessuno la vedesse. Una bambina di nove anni che faceva qualcosa che gli adulti non osavano fare.\n\nSe racconto il segreto, i libri vivranno. Se i libri vivono, vive anche qualcosa di Hannah.\n\nMi alzo. Ora so cosa farò.\n\nCammina verso est. Il Lustgarten è a cinque minuti.',
  },
  'clara_08a': {
    'ES': 'El Lustgarten es el jardín frente al Berliner Dom.\n\nLustgarten significa jardín del placer — aunque en 1946 está bastante serio, con el césped pisado y algunos árboles con las ramas quemadas. Fue huerta del Palacio Real en el siglo XVI, campo de maniobras militares en el XVII, parque público en el XIX, plaza de desfiles nazis en los años treinta. Cada régimen le dio un uso diferente. Oma Else dice que las plazas no tienen ideología — son las personas que las llenan las que la tienen.\n\nMe siento en el borde del jardín y escribo todo en mi cuaderno de colegio.\n\nEscribo la dirección. Escribo la descripción del sótano. Escribo el nombre de Hannah Goldberg y la fecha de la fotografía. Escribo cuántos libros calculo que hay — muchos, no sé el número exacto. Escribo la descripción de la llave dorada, que guardo en el bolsillo.\n\nCuando termino de escribir me doy cuenta de que estoy temblando un poco. No de frío. De otra cosa.\n\nA veces hacer lo correcto da miedo. Eso también lo sé ahora.\n\nCamina hacia el sur. El Berliner Dom está al lado — dos minutos.',
    'EN': 'The Lustgarten is the garden in front of the Berliner Dom.\n\nLustgarten means pleasure garden — though in 1946 it is fairly grim, with the grass trampled and some trees with burned branches. It was the Royal Palace\'s kitchen garden in the 16th century, a military drill ground in the 17th, a public park in the 19th, a Nazi parade ground in the thirties. Each regime gave it a different use. Oma Else says squares have no ideology — it is the people who fill them who do.\n\nI sit on the edge of the garden and write everything down in my school notebook.\n\nI write the address. I write the description of the basement. I write Hannah Goldberg\'s name and the date on the photograph. I write how many books I estimate there are — many, I don\'t know the exact number. I write a description of the golden key, which I keep in my pocket.\n\nWhen I finish writing I realise I am trembling a little. Not from cold. From something else.\n\nSometimes doing the right thing is frightening. That is something else I know now.\n\nWalk south. The Berliner Dom is right next door — two minutes.',
    'DE': 'Der Lustgarten ist der Garten vor dem Berliner Dom.\n\nLustgarten bedeutet Vergnügungsgarten – obwohl er 1946 ziemlich ernst ist, mit zertretenem Rasen und einigen Bäumen mit verbrannten Ästen. Im 16. Jahrhundert war er der Küchengarten des Königspalastes, im 17. ein militärisches Exerzierfeld, im 19. ein öffentlicher Park, in den dreißiger Jahren ein Aufmarschplatz der Nazis. Jedes Regime gab ihm eine andere Nutzung. Oma Else sagt, Plätze haben keine Ideologie – es sind die Menschen, die sie füllen, die sie haben.\n\nIch setze mich an den Rand des Gartens und schreibe alles in mein Schulheft.\n\nIch schreibe die Adresse auf. Ich schreibe die Beschreibung des Kellers auf. Ich schreibe den Namen Hannah Goldberg und das Datum der Fotografie auf. Ich schreibe, wie viele Bücher ich schätze, dass es gibt – viele, ich weiß die genaue Zahl nicht. Ich schreibe die Beschreibung des goldenen Schlüssels auf, den ich in der Tasche behalte.\n\nAls ich aufgehört habe zu schreiben, merke ich, dass ich ein bisschen zittere. Nicht vor Kälte. Vor etwas anderem.\n\nManchmal macht es Angst, das Richtige zu tun. Das weiß ich jetzt auch.\n\nGeh nach Süden. Der Berliner Dom ist nebenan – zwei Minuten.',
    'IT': 'Il Lustgarten è il giardino davanti al Berliner Dom.\n\nLustgarten significa giardino del piacere – anche se nel 1946 è abbastanza serio, con il prato calpestato e alcuni alberi con i rami bruciati. Nel XVI secolo era l\'orto del Palazzo Reale, nel XVII un campo di manovra militare, nel XIX un parco pubblico, negli anni trenta una piazza per le sfilate naziste. Ogni regime gli diede un uso diverso. Oma Else dice che le piazze non hanno ideologia – sono le persone che le riempiono ad averla.\n\nMi siedo al bordo del giardino e scrivo tutto nel mio quaderno di scuola.\n\nScrivo l\'indirizzo. Scrivo la descrizione della cantina. Scrivo il nome di Hannah Goldberg e la data della fotografia. Scrivo quanti libri calcolo che ci siano – molti, non so il numero esatto. Scrivo la descrizione della chiave dorata, che tengo in tasca.\n\nQuando finisco di scrivere mi accorgo che tremo un po\'. Non di freddo. Di qualcos\'altro.\n\nA volte fare la cosa giusta fa paura. Anche questo lo so adesso.\n\nCammina verso sud. Il Berliner Dom è accanto – due minuti.',
  },
  'clara_09a': {
    'ES': 'El Berliner Dom es la catedral más grande de Berlín.\n\nLo construyó el Kaiser Guillermo II entre 1894 y 1905 para demostrar que el protestantismo alemán era tan importante como el catolicismo romano. Tiene 98 metros de cúpula central, cuatro torres angulares, mármoles italianos, mosaicos dorados y una cripta con noventa y tres sarcófagos de la familia Hohenzollern — los reyes de Prusia que gobernaron durante doscientos años. En 1944 una bomba destruyó parte de la cúpula. Cuando miras hacia arriba puedes ver los agujeros donde el cielo entra. A mí me parece que así es más honesto — un edificio que no finge que la guerra no pasó.\n\nEntro.\n\nHay un pastor — un hombre mayor con ropa negra — que está ordenando unas sillas. Lo miro. Él me mira. Le digo: señor, encontré algo importante y no sé a quién contárselo.\n\nMe escucha. Sin poner cara rara. Sin decirme que hay cosas que es mejor no saber. Me escucha hasta el final.\n\nCuando termino de hablar, él se queda callado un momento. Luego dice: eres una niña muy valiente, Clara.\n\nNadie me había llamado valiente antes. Solo inteligente, o curiosa, o demasiado preguntona. Valiente me gusta más.\n\nLos libros de Hannah van a estar bien. Y Hannah, donde quiera que esté, lo sabe.\n\nBerlín en 1946 es una ciudad de ruinas y de personas que buscan entre las ruinas lo que todavía puede salvarse. Cada libro rescatado, cada nombre recordado, cada historia contada es una forma de decirle a la destrucción que no ganó del todo. Las ciudades no se reconstruyen solo con ladrillos. Se reconstruyen también con esto: una niña de nueve años y tres cuartos que decide que un secreto merece una voz.\n\nHas llegado al final del recorrido de Clara. Berlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'The Berliner Dom is the largest cathedral in Berlin.\n\nKaiser Wilhelm II had it built between 1894 and 1905 to demonstrate that German Protestantism was as important as Roman Catholicism. It has a 98-metre central dome, four corner towers, Italian marbles, golden mosaics and a crypt with ninety-three sarcophagi of the Hohenzollern family — the Kings of Prussia who ruled for two hundred years. In 1944 a bomb destroyed part of the dome. When you look up you can see the gaps where the sky comes in. I think that makes it more honest — a building that doesn\'t pretend the war didn\'t happen.\n\nI go inside.\n\nThere is a pastor — an older man in black — arranging some chairs. I look at him. He looks at me. I say: sir, I found something important and I don\'t know who to tell.\n\nHe listens. That is the first thing he does — listen to me properly, without making a strange face, without telling me there are some things it\'s better not to know. He listens until the end.\n\nWhen I finish speaking, he is quiet for a moment. Then he says: you are a very brave girl, Clara.\n\nNo one had called me brave before. Just clever, or curious, or too full of questions. I like brave better.\n\nHannah\'s books are going to be all right. And Hannah, wherever she is, knows it.\n\nBerlin in 1946 is a city of ruins and people searching through the ruins for what can still be saved. Every rescued book, every remembered name, every story told is a way of saying to the destruction: you didn\'t quite win. Cities are not rebuilt with bricks alone. They are also rebuilt with this: a girl of nine and three-quarters who decides that a secret deserves a voice.\n\nYou have reached the end of Clara\'s journey. Berlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Der Berliner Dom ist die größte Kathedrale Berlins.\n\nKaiser Wilhelm II. ließ ihn zwischen 1894 und 1905 bauen, um zu beweisen, dass der deutsche Protestantismus genauso wichtig war wie der römische Katholizismus. Er hat eine 98 Meter hohe Mittelkuppel, vier Ecktürme, italienische Marmors, goldene Mosaike und eine Gruft mit dreiundneunzig Sarkophagen der Hohenzollern-Familie – die Könige Preußens, die zweihundert Jahre lang regierten. 1944 zerstörte eine Bombe einen Teil der Kuppel. Wenn man nach oben schaut, sieht man die Löcher, wo der Himmel hereinkommt. Ich finde, so ist es ehrlicher – ein Gebäude, das nicht so tut, als wäre der Krieg nicht gewesen.\n\nIch betrete es.\n\nEs gibt einen Pastor – einen älteren Mann mit schwarzen Kleidern – der gerade Stühle ordnet. Ich schaue ihn an. Er schaut mich an. Ich sage ihm: Herr, ich habe etwas Wichtiges gefunden und weiß nicht, wem ich es erzählen soll.\n\nEr hört mir zu. Ohne komisches Gesicht. Ohne mir zu sagen, dass es Dinge gibt, die man besser nicht weiß. Er hört mir bis zum Ende zu.\n\nAls ich aufgehört habe zu reden, bleibt er einen Moment still. Dann sagt er: Du bist ein sehr mutiges Mädchen, Clara.\n\nNoch nie hatte mich jemand mutig genannt. Nur klug, oder neugierig, oder zu sehr fragend. Mutig gefällt mir besser.\n\nHannahs Bücher werden in Sicherheit sein. Und Hannah, wo immer sie ist, weiß das.\n\nBerlin 1946 ist eine Stadt aus Ruinen und Menschen, die in den Ruinen suchen, was noch gerettet werden kann. Jedes gerettete Buch, jeder erinnerte Name, jede erzählte Geschichte ist eine Art zu sagen, dass die Zerstörung nicht ganz gewann. Städte werden nicht nur mit Ziegeln wiederaufgebaut. Sie werden auch damit wiederaufgebaut: einem neunjährigen Mädchen und drei Vierteln, das entscheidet, dass ein Geheimnis eine Stimme verdient.\n\nDu hast das Ende von Claras Rundgang erreicht. Berlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Il Berliner Dom è la cattedrale più grande di Berlino.\n\nL\'imperatore Guglielmo II lo fece costruire tra il 1894 e il 1905 per dimostrare che il protestantesimo tedesco era importante quanto il cattolicesimo romano. Ha una cupola centrale di 98 metri, quattro torri angolari, marmi italiani, mosaici dorati e una cripta con novantaré sarcofagi della famiglia Hohenzollern – i re di Prussia che governarono per duecento anni. Nel 1944 una bomba distrusse parte della cupola. Quando guardi in su puoi vedere i buchi da cui entra il cielo. A me sembra più onesto così – un edificio che non finge che la guerra non sia accaduta.\n\nEntro.\n\nC\'è un pastore – un uomo anziano con abiti neri – che sta sistemando delle sedie. Lo guardo. Lui mi guarda. Gli dico: signore, ho trovato qualcosa di importante e non so a chi raccontarlo.\n\nMi ascolta. Senza fare facce strane. Senza dirmi che ci sono cose che è meglio non sapere. Mi ascolta fino alla fine.\n\nQuando finisco di parlare, lui rimane in silenzio un momento. Poi dice: sei una bambina molto coraggiosa, Clara.\n\nNessuno mi aveva mai chiamata coraggiosa prima. Solo intelligente, o curiosa, o troppo curiosona. Coraggiosa mi piace di più.\n\nI libri di Hannah staranno bene. E Hannah, dovunque sia, lo sa.\n\nBerlino nel 1946 è una città di rovine e di persone che cercano tra le rovine ciò che può ancora essere salvato. Ogni libro salvato, ogni nome ricordato, ogni storia raccontata è un modo di dire alla distruzione che non ha vinto del tutto. Le città non si ricostruiscono solo con i mattoni. Si ricostruiscono anche con questo: una bambina di nove anni e tre quarti che decide che un segreto merita una voce.\n\nHai raggiunto la fine del percorso di Clara. Berlino è ancora qui. E anche tu. Per ora basta così.',
  },
  'clara_07b': {
    'ES': 'Decido guardarlo. Por ahora.\n\nEso me digo mientras cierro la puerta del sótano y guardo la llave en el bolsillo más profundo de mi abrigo.\n\nCamino hacia el Nikolaiviertel, que es el barrio más viejo de Berlín. La Nikolaikirche fue fundada en 1230 — tiene setecientos años, que es más que cualquier cosa que pueda imaginar. Las casas son pequeñas y están apretadas y las calles son tan estrechas que si extiendes los brazos casi puedes tocar las dos paredes. En la guerra fue uno de los barrios más destruidos — el noventa por ciento de los edificios quedaron en ruinas. Los que ves ahora son reconstrucciones nuevas que intentan parecerse a lo que había antes. Como cuando te caes y te raspas la rodilla y crece piel nueva que no es exactamente igual a la de antes, pero cubre.\n\nMe siento en los adoquines frente a la Nikolaikirche.\n\nPienso en Hannah. Ella también guardó un secreto — llevó libros al sótano de noche para que no los quemaran. Lo hizo sola, sin que nadie lo supiera, con nueve años.\n\nA lo mejor los secretos a veces necesitan tiempo. A lo mejor este necesita que yo crezca un poco antes de saber qué hacer con él.\n\nLa llave está caliente en mi bolsillo.\n\nCamina hacia el oeste. El Marx-Engels-Forum está al lado del Spree — cinco minutos.',
    'EN': 'I decide to keep it. For now.\n\nThat is what I tell myself as I close the basement door and push the key deep into my coat pocket.\n\nI walk toward the Nikolaiviertel, which is the oldest neighbourhood in Berlin. The Nikolaikirche was founded in 1230 — it is seven hundred years old, which is more than anything I can imagine. The houses are small and crowded together and the streets are so narrow that if you stretch out your arms you can almost touch both walls at once. During the war it was one of the most destroyed neighbourhoods — ninety per cent of the buildings were left in ruins. The ones you see now are new reconstructions trying to look like what was there before. Like when you fall and scrape your knee and new skin grows that isn\'t quite the same as the skin before, but covers.\n\nI sit on the cobblestones in front of the Nikolaikirche.\n\nI think about Hannah. She also kept a secret — she carried books to the basement at night so they wouldn\'t be burned. She did it alone, without anyone knowing, at nine years old.\n\nMaybe secrets sometimes need time. Maybe this one needs me to grow a little before I know what to do with it.\n\nThe key is warm in my pocket.\n\nWalk west. The Marx-Engels-Forum is beside the Spree — five minutes.',
    'DE': 'Ich entscheide mich, es zu bewahren. Erst mal.\n\nDas sage ich mir, während ich die Kellertür schließe und den Schlüssel in die tiefste Tasche meines Mantels stecke.\n\nIch gehe zum Nikolaiviertel, dem ältesten Viertel Berlins. Die Nikolaikirche wurde 1230 gegründet – sie ist siebenhundert Jahre alt, was mehr ist als ich mir vorstellen kann. Die Häuser sind klein und eng und die Straßen so schmal, dass man, wenn man die Arme ausstreckt, fast beide Wände berühren kann. Im Krieg war es eines der am stärksten zerstörten Viertel – neunzig Prozent der Gebäude lagen in Trümmern. Die, die du jetzt siehst, sind neue Rekonstruktionen, die versuchen, dem zu ähneln, was vorher da war. Wie wenn man hinfällt und sich das Knie aufschürft und neue Haut wächst, die nicht ganz dieselbe wie die alte ist, aber bedeckt.\n\nIch setze mich auf das Pflaster vor der Nikolaikirche.\n\nIch denke an Hannah. Auch sie bewahrte ein Geheimnis – sie trug Bücher nachts in den Keller, damit sie nicht verbrannt wurden. Sie tat es allein, ohne dass jemand es wusste, mit neun Jahren.\n\nVielleicht brauchen Geheimnisse manchmal Zeit. Vielleicht braucht dieses, dass ich ein bisschen älter werde, bevor ich weiß, was ich damit tun soll.\n\nDer Schlüssel ist warm in meiner Tasche.\n\nGeh nach Westen. Das Marx-Engels-Forum ist neben der Spree – fünf Minuten.',
    'IT': 'Decido di tenerlo segreto. Per ora.\n\nMe lo dico mentre chiudo la porta della cantina e metto la chiave nella tasca più profonda del cappotto.\n\nCammino verso il Nikolaiviertel, il quartiere più antico di Berlino. La Nikolaikirche fu fondata nel 1230 – ha settecento anni, che è più di quanto possa immaginare. Le case sono piccole e strette e le strade sono così strette che se allarghi le braccia puoi quasi toccare entrambe le pareti. Durante la guerra fu uno dei quartieri più distrutti – il novanta per cento degli edifici erano in macerie. Quelli che vedi ora sono nuove ricostruzioni che cercano di assomigliare a quello che c\'era prima. Come quando cadi e ti sbucchi il ginocchio e cresce pelle nuova che non è esattamente uguale a quella di prima, ma copre.\n\nMi siedo sui selci davanti alla Nikolaikirche.\n\nPenso a Hannah. Anche lei custodì un segreto – portò i libri nella cantina di notte, perché non li bruciassero. Lo fece da sola, senza che nessuno lo sapesse, a nove anni.\n\nForse i segreti a volte hanno bisogno di tempo. Forse questo ha bisogno che io cresca un po\' prima di sapere cosa farci.\n\nLa chiave è calda in tasca.\n\nCammina verso ovest. Il Marx-Engels-Forum è vicino alla Spree – cinque minuti.',
  },
  'clara_08b': {
    'ES': 'Me siento a la orilla del Spree.\n\nEl Spree no sabe nada de guerras ni de particiones. Solo va hacia donde va — desde las montañas de Lusacia hasta el Havel, cuatrocientos kilómetros de agua gris verdosa que no se preguntan si van en la dirección correcta. En los peores meses del invierno de 1945, cuando no había carbón y la gente moría de frío, las familias bajaban al río a hacer fuego con lo que encontraban. El río siguió fluyendo. Los ríos siempre siguen fluyendo.\n\nSaco la fotografía de Hannah.\n\nLa miro mucho rato. Ella mira a la cámara con cara de estar pensando algo importante. Me pregunto qué pensaba. Si pensaba en esta biblioteca. Si pensaba: alguien la encontrará algún día. Si pensaba: espero que sea alguien bueno.\n\nQuiero ser alguien bueno.\n\nNo sé si guardar el secreto es lo bueno o si contarlo es lo bueno. A lo mejor las dos cosas son buenas de maneras distintas. A lo mejor no hay una respuesta correcta — y eso es lo más difícil de todo, porque a los nueve años uno quiere que las cosas tengan respuesta correcta.\n\nDoblo la foto con cuidado y la guardo junto a la llave.\n\nCamina hacia el norte. El Rotes Rathaus está a tres minutos.',
    'EN': 'I sit by the edge of the Spree.\n\nThe Spree doesn\'t know anything about wars or divisions. It just goes where it goes — from the Lusatian mountains to the Havel, four hundred kilometres of grey-green water that don\'t ask themselves if they are going in the right direction. In the worst months of the winter of 1945, when there was no coal and people were dying of cold, families came down to the river to make fires from whatever they could find. The river kept flowing. Rivers always keep flowing.\n\nI take out Hannah\'s photograph.\n\nI look at it for a long time. She looks at the camera with a face like she is thinking about something important. I wonder what she was thinking. Whether she was thinking about this library. Whether she was thinking: someone will find it someday. Whether she was thinking: I hope it\'s someone good.\n\nI want to be someone good.\n\nI don\'t know if keeping the secret is the good thing or if telling it is the good thing. Maybe both things are good in different ways. Maybe there is no right answer — and that is the hardest part of all, because when you are nine you want things to have a right answer.\n\nI fold the photo carefully and put it away with the key.\n\nWalk north. The Rotes Rathaus is three minutes away.',
    'DE': 'Ich setze mich ans Spreeufer.\n\nDie Spree weiß nichts von Kriegen oder Teilungen. Sie fließt einfach wohin sie fließt – von den Bergen der Lausitz bis zur Havel, vierhundert Kilometer graugrünes Wasser, das sich nicht fragt, ob es in die richtige Richtung geht. In den schlimmsten Monaten des Winters 1945, als es keine Kohle gab und die Menschen an Kälte starben, gingen die Familien zum Fluss hinunter, um mit dem zu feuern, was sie fanden. Der Fluss floss weiter. Flüsse fließen immer weiter.\n\nIch hole Hannahs Foto heraus.\n\nIch schaue es lange an. Sie schaut in die Kamera mit dem Gesicht von jemandem, der gerade etwas Wichtiges denkt. Ich frage mich, was sie dachte. Ob sie an diese Bibliothek dachte. Ob sie dachte: Jemand wird sie eines Tages finden. Ob sie dachte: Ich hoffe, es ist jemand Gutes.\n\nIch möchte jemand Gutes sein.\n\nIch weiß nicht, ob das Geheimnis zu bewahren das Gute ist oder ob es erzählen das Gute ist. Vielleicht sind beide Dinge gut auf unterschiedliche Art. Vielleicht gibt es keine richtige Antwort – und das ist das Schwerste von allem, denn mit neun Jahren möchte man, dass die Dinge eine richtige Antwort haben.\n\nIch falte das Foto vorsichtig und verstaue es zusammen mit dem Schlüssel.\n\nGeh nach Norden. Das Rote Rathaus ist drei Minuten entfernt.',
    'IT': 'Mi siedo sulla riva della Spree.\n\nLa Spree non sa niente di guerre né di divisioni. Va semplicemente dove va – dalle montagne della Lusazia all\'Havel, quattrocento chilometri di acqua grigio-verdognola che non si chiede se sta andando nella direzione giusta. Nei mesi peggiori dell\'inverno del 1945, quando non c\'era carbone e la gente moriva di freddo, le famiglie scendevano al fiume per accendere il fuoco con quello che trovavano. Il fiume continuò a scorrere. I fiumi continuano sempre a scorrere.\n\nTiro fuori la fotografia di Hannah.\n\nLa guardo a lungo. Lei guarda la macchina fotografica con la faccia di qualcuno che sta pensando qualcosa di importante. Mi chiedo cosa pensasse. Se pensasse a questa biblioteca. Se pensasse: qualcuno la troverà un giorno. Se pensasse: spero che sia qualcuno di buono.\n\nVoglio essere qualcuno di buono.\n\nNon so se tenere il segreto è la cosa buona o se raccontarlo è la cosa buona. Forse tutte e due le cose sono buone in modi diversi. Forse non c\'è una risposta giusta – e questa è la cosa più difficile di tutte, perché a nove anni si vuole che le cose abbiano una risposta giusta.\n\nPiego la foto con cura e la ripongo insieme alla chiave.\n\nCammina verso nord. Il Rotes Rathaus è a tre minuti.',
  },
  'clara_09b': {
    'ES': 'El Ayuntamiento Rojo.\n\nSe llama así por el color de los ladrillos — rojo oscuro, como la tierra mojada. Lo construyeron entre 1861 y 1869, cuando Berlín empezaba a crecer muy rápido y necesitaba un gobierno a la altura de su ambición. Tiene 97 metros de torre central y una banda de terracota alrededor del primer piso con figuras en bajorrelieve que cuentan la historia de la ciudad desde su fundación. Si miras esas figuras puedes ver batallas, incendios, plagas, reconstrucciones — toda la historia de Berlín resumida en piedra a la altura de los ojos. En 1946 parte del tejado está dañado y hay andamios. Aquí trabajan las personas que toman decisiones sobre qué se reconstruye y qué no, qué se recuerda y qué no.\n\nMe paro frente a él y pienso: quizás algún día entre aquí y le cuente a alguien lo de la biblioteca de Hannah.\n\nPero hoy no. Hoy la llave sigue en mi bolsillo.\n\nMe doy la vuelta y empiezo a caminar hacia casa. Por el camino, cuento los adoquines. Eso me ayuda a pensar. Cuento hasta ciento cuarenta y siete antes de llegar a nuestra calle.\n\nMañana volveré al sótano. Llevaré mi cuaderno. Copiaré los títulos de todos los libros, uno por uno, para que aunque pase algo yo tenga la lista. Para que las voces de esos libros estén en algún sitio más.\n\nHannah guardó una biblioteca para que no muriera. Yo voy a guardar la lista para que Hannah no muera. Tengo nueve años y tres cuartos. Es suficiente.\n\nBerlín en 1946 es una ciudad que no sabe todavía lo que va a ser. Sus ruinas podrían convertirse en cualquier cosa. Sus niños también. A veces la historia la escriben los gobiernos y los generales. Y a veces la escribe una niña con una llave en el bolsillo que decide, sin que nadie se lo pida, que ciertos nombres merecen ser recordados.\n\nHas llegado al final del recorrido de Clara. Berlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'The Red Town Hall.\n\nIt gets its name from the colour of the bricks — dark red, like wet earth. It was built between 1861 and 1869, when Berlin was beginning to grow very fast and needed a government to match its ambitions. It has a 97-metre central tower and a terracotta frieze around the first floor with bas-relief figures telling the history of the city from its founding. If you look at those figures you can see battles, fires, plagues, reconstructions — the whole history of Berlin summarised in stone at eye level. In 1946 part of the roof is damaged and there are scaffolding poles. Here work the people who decide what gets rebuilt and what doesn\'t, what gets remembered and what doesn\'t.\n\nI stand in front of it and think: maybe someday I\'ll go inside and tell someone about Hannah\'s library.\n\nBut not today. Today the key stays in my pocket.\n\nI turn around and start walking home. On the way, I count the cobblestones. That helps me think. I count to a hundred and forty-seven before I reach our street.\n\nTomorrow I will go back to the basement. I will bring my notebook. I will copy down the titles of all the books, one by one, so that even if something happens I will have the list. So that the voices of those books will exist somewhere else too.\n\nHannah kept a library so it wouldn\'t die. I am going to keep the list so Hannah won\'t die. I am nine and three-quarters. That is enough.\n\nBerlin in 1946 is a city that doesn\'t yet know what it is going to be. Its ruins could become anything. Its children too. Sometimes history is written by governments and generals. And sometimes it is written by a girl with a key in her pocket who decides, without anyone asking her to, that certain names deserve to be remembered.\n\nYou have reached the end of Clara\'s journey. Berlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Das Rote Rathaus.\n\nEs heißt so wegen der Farbe der Ziegel – dunkelrot, wie feuchte Erde. Es wurde zwischen 1861 und 1869 gebaut, als Berlin anfing, sehr schnell zu wachsen und eine Regierung brauchte, die seiner Ambition gerecht wurde. Es hat einen 97 Meter hohen Mittelturm und ein Terrakottaband rings um das erste Stockwerk mit Relieffiguren, die die Geschichte der Stadt seit ihrer Gründung erzählen. Wenn man diese Figuren anschaut, sieht man Schlachten, Brände, Seuchen, Wiederaufbauten – die ganze Geschichte Berlins zusammengefasst in Stein auf Augenhöhe. 1946 ist ein Teil des Dachs beschädigt und es gibt Gerüste. Hier arbeiten die Menschen, die Entscheidungen darüber treffen, was wiederaufgebaut wird und was nicht, was erinnert wird und was nicht.\n\nIch bleibe davor stehen und denke: Vielleicht werde ich eines Tages hier hineingehen und jemandem von Hannahs Bibliothek erzählen.\n\nAber heute nicht. Heute bleibt der Schlüssel in meiner Tasche.\n\nIch drehe mich um und fange an, nach Hause zu laufen. Unterwegs zähle ich die Pflastersteine. Das hilft mir beim Denken. Ich zähle bis hundertsiebenundvierzig, bevor ich in unsere Straße komme.\n\nMorgen werde ich in den Keller zurückgehen. Ich werde mein Schulheft mitnehmen. Ich werde die Titel aller Bücher abschreiben, einen nach dem anderen, damit, selbst wenn etwas passiert, ich die Liste habe. Damit die Stimmen dieser Bücher noch irgendwo existieren.\n\nHannah bewahrte eine Bibliothek, damit sie nicht starb. Ich werde die Liste aufbewahren, damit Hannah nicht stirbt. Ich bin neun Jahre und drei Viertel alt. Das reicht.\n\nBerlin 1946 ist eine Stadt, die noch nicht weiß, was sie werden wird. Ihre Ruinen könnten zu allem werden. Ihre Kinder auch. Manchmal schreiben die Regierungen und die Generäle Geschichte. Und manchmal schreibt sie ein Mädchen mit einem Schlüssel in der Tasche, das entscheidet, ohne dass jemand es darum bittet, dass bestimmte Namen erinnert werden sollten.\n\nDu hast das Ende von Claras Rundgang erreicht. Berlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Il Municipio Rosso.\n\nSi chiama così per il colore dei mattoni – rosso scuro, come la terra bagnata. Fu costruito tra il 1861 e il 1869, quando Berlino cominciava a crescere molto velocemente e aveva bisogno di un governo all\'altezza della sua ambizione. Ha una torre centrale di 97 metri e una fascia di terracotta intorno al primo piano con figure in bassorilievo che raccontano la storia della città dalla sua fondazione. Se guardi quelle figure puoi vedere battaglie, incendi, pestilenze, ricostruzioni – tutta la storia di Berlino riassunta in pietra all\'altezza degli occhi. Nel 1946 parte del tetto è danneggiata e ci sono impalcature. Qui lavorano le persone che prendono decisioni su cosa ricostruire e cosa no, cosa ricordare e cosa no.\n\nMi fermo davanti ad esso e penso: forse un giorno entrerò qui e racconterò a qualcuno della biblioteca di Hannah.\n\nMa oggi no. Oggi la chiave rimane in tasca.\n\nMi giro e comincio a camminare verso casa. Per strada, conto i selci. Questo mi aiuta a pensare. Conto fino a centoquarantasette prima di arrivare alla nostra strada.\n\nDomani tornerò nella cantina. Porterò il mio quaderno di scuola. Copierò i titoli di tutti i libri, uno per uno, così anche se succede qualcosa io ho la lista. Così le voci di quei libri esistano da qualche parte in più.\n\nHannah conservò una biblioteca perché non morisse. Io conserverò la lista perché Hannah non muoia. Ho nove anni e tre quarti. È abbastanza.\n\nBerlino nel 1946 è una città che non sa ancora cosa diventerà. Le sue rovine potrebbero diventare qualsiasi cosa. Anche i suoi bambini. A volte la storia la scrivono i governi e i generali. E a volte la scrive una bambina con una chiave in tasca che decide, senza che nessuno glielo chieda, che certi nomi meritano di essere ricordati.\n\nHai raggiunto la fine del percorso di Clara. Berlino è ancora qui. E anche tu. Per ora basta così.',
  },
  'otto_01': {
    'ES': 'Berlín Oriental, 9 de noviembre de 1989. Son las 10:14 de la mañana.\n\nMe llamo Otto Fischer. Tengo cincuenta y cinco años, llevo veintidós trabajando para el Ministerio de Información de la República Democrática Alemana, y esta mañana tengo en el bolsillo un papel que no he leído bien.\n\nEl Weltzeituhr lleva aquí desde 1969. Marca la hora en veinticuatro ciudades simultáneamente — Moscú, La Habana, Pekín, Hanói, Ciudad de México. Las ciudades del mundo correcto, el que ganó. O el que creímos que había ganado.\n\nLa Alexanderplatz fue diseñada para hacer sentir al individuo pequeño. La escala es deliberada. Los espacios abiertos sin sombra ni lugar donde sentarse son deliberados. Una plaza donde no es cómodo quedarse es una plaza donde no se forman grupos, no se hablan extraños, no se organiza nada que el Estado no haya organizado primero.\n\nHace cuatro semanas, el 4 de noviembre, medio millón de personas se reunieron aquí de todas formas. La manifestación más grande de la historia de la RDA. En la plaza diseñada para que no se reunieran.\n\nPor eso existe el decreto del papel que llevo en el bolsillo.\n\nCamina hacia el sur. El Fernsehturm está a dos minutos.',
    'EN': 'East Berlin, 9 November 1989. It is 10:14 in the morning.\n\nMy name is Otto Fischer. I am fifty-five years old, I have spent twenty-two years working for the Ministry of Information of the German Democratic Republic, and this morning I have a piece of paper in my pocket that I have not read carefully enough.\n\nThe Weltzeituhr has stood here since 1969. It shows the time in twenty-four cities simultaneously — Moscow, Havana, Beijing, Hanoi, Mexico City. The cities of the right world, the one that won. Or the one we believed had won.\n\nAlexanderplatz was designed to make the individual feel small. The scale is deliberate. The open spaces without shade or anywhere to sit are deliberate. A square where it is not comfortable to linger is a square where groups do not form, strangers do not talk, nothing is organised that the State has not organised first.\n\nFour weeks ago, on 4 November, half a million people gathered here anyway. The largest demonstration in the history of the GDR. In the square designed so they would not gather.\n\nThat is why the decree on the paper in my pocket exists.\n\nWalk south. The Fernsehturm is two minutes away.',
    'DE': 'Berlin-Ost, 9. November 1989. Es ist 10:14 Uhr.\n\nMein Name ist Otto Fischer. Ich bin fünfundfünfzig Jahre alt, arbeite seit zweiundzwanzig Jahren für das Ministerium für Information der Deutschen Demokratischen Republik, und heute Morgen habe ich ein Papier in der Tasche, das ich nicht sorgfältig genug gelesen habe.\n\nDie Weltzeituhr steht hier seit 1969. Sie zeigt gleichzeitig die Zeit in vierundzwanzig Städten an — Moskau, Havanna, Peking, Hanoi, Mexiko-Stadt. Die Städte der richtigen Welt, der siegreichen. Oder der, von der wir glaubten, sie habe gesiegt.\n\nDie Alexanderplatz wurde so gestaltet, dass der Einzelne sich klein fühlt. Die Maßstäbe sind bewusst gewählt. Die offenen Flächen ohne Schatten und ohne Sitzgelegenheiten sind bewusst gewählt. Ein Platz, auf dem man sich nicht gerne aufhält, ist ein Platz, auf dem sich keine Gruppen bilden, keine Fremden miteinander reden, nichts organisiert wird, was der Staat nicht zuerst organisiert hätte.\n\nVor vier Wochen, am 4. November, versammelten sich hier trotzdem eine halbe Million Menschen. Die größte Demonstration in der Geschichte der DDR. Auf dem Platz, der dafür gebaut wurde, dass sich niemand versammelt.\n\nDeshalb gibt es das Dekret auf dem Papier, das ich in der Tasche trage.\n\nGeh nach Süden. Der Fernsehturm ist zwei Minuten entfernt.',
    'IT': 'Berlino Est, 9 novembre 1989. Sono le 10:14.\n\nMi chiamo Otto Fischer. Ho cinquantacinque anni, lavoro da ventidue per il Ministero dell\'Informazione della Repubblica Democratica Tedesca, e stamattina ho in tasca un documento che non ho letto con sufficiente attenzione.\n\nIl Weltzeituhr è qui dal 1969. Indica l\'ora in ventiquattro città simultaneamente — Mosca, L\'Avana, Pechino, Hanoi, Città del Messico. Le città del mondo giusto, quello che ha vinto. O quello che credevamo avesse vinto.\n\nL\'Alexanderplatz è stata progettata per far sentire l\'individuo piccolo. La scala è deliberata. Gli spazi aperti senza ombra né posti a sedere sono deliberati. Una piazza in cui non è comodo fermarsi è una piazza in cui non si formano gruppi, gli estranei non si parlano, non si organizza nulla che lo Stato non abbia organizzato per primo.\n\nQuattro settimane fa, il 4 novembre, mezzo milione di persone si sono radunate qui lo stesso. La manifestazione più grande nella storia della DDR. Nella piazza costruita perché non si radunasse nessuno.\n\nÈ per questo che esiste il decreto del documento che porto in tasca.\n\nCammina verso sud. La Torre della Televisione è a due minuti.',
  },
  'otto_02': {
    'ES': 'La Torre de la Televisión tiene 368 metros. Se puede ver desde cualquier punto de Berlín. Eso no es un accidente — es el propósito.\n\nFue construida entre 1965 y 1969 como símbolo visible del poder y la permanencia del Estado socialista. La ironía que los berlineses occidentales disfrutaron durante décadas: cuando el sol da en la esfera de acero inoxidable a cierto ángulo, aparece un reflejo en forma de cruz. El Estado ateo había construido, sin querer, la cruz religiosa más visible de Berlín. La llamaron la venganza del Papa.\n\nLlevo treinta años mirando esta torre. Empecé en el Ministerio en 1967, redactando comunicados. Ascendí despacio, sin hacer ruido. Ese es el método correcto: no llamar la atención, hacer bien el trabajo que te asignan, no preguntar demasiado.\n\nEsta tarde tengo que leer en voz alta ante doscientos periodistas extranjeros el decreto sobre los permisos de viaje. Mi colega Schabowski tiene una reunión que se alarga y me lo pasó esta mañana. Me dijo: léelo tal como está, no necesitas preparación especial.\n\nNo he leído el papel con suficiente atención.\n\nCamina hacia el oeste. El Marx-Engels-Forum está a cuatro minutos.',
    'EN': 'The Television Tower is 368 metres tall. It can be seen from any point in Berlin. That is not an accident — it is the purpose.\n\nIt was built between 1965 and 1969 as a visible symbol of the power and permanence of the socialist State. The irony that West Berliners enjoyed for decades: when the sun hits the stainless steel sphere at certain angles, a reflection appears in the shape of a cross. The atheist State had built, without intending to, the most visible religious cross in Berlin. They called it the Pope\'s Revenge.\n\nI have spent thirty years looking at this tower. I joined the Ministry in 1967, drafting communiqués. I rose slowly, without making noise. That is the correct method: do not attract attention, do the work you are assigned well, do not ask too many questions.\n\nThis afternoon I have to read aloud to two hundred foreign journalists the decree on travel permits. My colleague Schabowski has a meeting running long and passed it to me this morning. He said: read it as it is, you do not need special preparation.\n\nI have not read the paper carefully enough.\n\nWalk west. The Marx-Engels-Forum is four minutes away.',
    'DE': 'Der Fernsehturm ist 368 Meter hoch. Er ist von jedem Punkt Berlins aus zu sehen. Das ist kein Zufall — das ist der Zweck.\n\nEr wurde zwischen 1965 und 1969 als sichtbares Symbol der Macht und Beständigkeit des sozialistischen Staates errichtet. Die Ironie, an der die West-Berliner sich jahrzehntelang ergötzten: Wenn die Sonne in einem bestimmten Winkel auf die Kugel aus rostfreiem Stahl trifft, erscheint ein Reflexionsbild in Form eines Kreuzes. Der atheistische Staat hatte, ohne es zu wollen, das sichtbarste religiöse Kreuz Berlins gebaut. Sie nannten es die Rache des Papstes.\n\nIch schaue auf diesen Turm seit dreißig Jahren. Ich fing 1967 im Ministerium an und schrieb Kommuniqués. Ich stieg langsam auf, ohne Aufsehen. Das ist die richtige Methode: nicht auffallen, die zugewiesene Arbeit gut machen, nicht zu viel fragen.\n\nHeute Nachmittag muss ich vor zweihundert ausländischen Journalisten das Dekret über die Reisegenehmigungen vorlesen. Mein Kollege Schabowski hat eine Sitzung, die sich in die Länge zieht, und hat es mir heute Morgen übergeben. Er sagte: Lies es so vor, wie es ist, du brauchst keine besondere Vorbereitung.\n\nIch habe das Papier nicht aufmerksam genug gelesen.\n\nGeh nach Westen. Das Marx-Engels-Forum ist vier Minuten entfernt.',
    'IT': 'La Torre della Televisione è alta 368 metri. Si vede da ogni punto di Berlino. Non è un caso — è lo scopo.\n\nFu costruita tra il 1965 e il 1969 come simbolo visibile del potere e della permanenza dello Stato socialista. L\'ironia di cui i berlinesi occidentali si deliziarono per decenni: quando il sole colpisce la sfera in acciaio inossidabile a una certa angolazione, appare un riflesso a forma di croce. Lo Stato ateo aveva costruito, senza volerlo, la croce religiosa più visibile di Berlino. La chiamarono la vendetta del Papa.\n\nGuardo questa torre da trent\'anni. Ho iniziato al Ministero nel 1967, redigendo comunicati. Sono avanzato lentamente, senza fare rumore. Questo è il metodo corretto: non attirare l\'attenzione, fare bene il lavoro assegnato, non fare troppe domande.\n\nQuesto pomeriggio devo leggere ad alta voce davanti a duecento giornalisti stranieri il decreto sui permessi di viaggio. Il mio collega Schabowski ha una riunione che si prolunga e me lo ha consegnato stamattina. Ha detto: leggilo così com\'è, non hai bisogno di una preparazione speciale.\n\nNon ho letto il documento con sufficiente attenzione.\n\nCammina verso ovest. Il Marx-Engels-Forum è a quattro minuti.',
  },
  'otto_03': {
    'ES': 'Las estatuas de bronce de Marx y Engels llevan aquí desde 1986. El foro fue construido como espacio de conmemoración ideológica. El resultado es una plaza tranquila junto al Spree, con los dos padres del socialismo mirando hacia el Berliner Dom con una expresión que yo siempre he interpretado como escepticismo.\n\nHace cuatro semanas, durante la manifestación del 4 de noviembre, alguien les puso un cartel: "Próxima vez lo haremos mejor." Nadie lo quitó en horas.\n\nSaco el papel del bolsillo y lo leo aquí, en este banco junto al río.\n\nEl decreto dice que los ciudadanos de la RDA podrán solicitar permisos de viaje al exterior. Que los permisos se concederán sin condiciones previas. Que la nueva regulación entra en vigor de inmediato, sin demora.\n\nLo que no noto — lo que no puedo notar porque no tengo el decreto completo — es que "de inmediato" debería haber significado mañana, después de que los puestos fronterizos recibieran instrucciones. Hay una cláusula de implementación que quedó fuera del borrador que me dieron.\n\nEn seis horas voy a leer esto ante doscientos periodistas.\n\nCamina hacia el oeste. El Humboldt Forum está a tres minutos.',
    'EN': 'The bronze statues of Marx and Engels have stood here since 1986. The forum was built as a space for ideological commemoration. The result is a quiet square beside the Spree, with the two fathers of socialism looking toward the Berliner Dom with an expression I have always interpreted as scepticism.\n\nFour weeks ago, during the 4 November demonstration, someone placed a sign on them: "Next time we will do better." Nobody removed it for hours.\n\nI take the paper from my pocket and read it here, on this bench beside the river.\n\nThe decree says that GDR citizens will be able to apply for permits to travel abroad. That permits will be granted without prior conditions. That the new regulation takes effect immediately, without delay.\n\nWhat I do not notice — what I cannot notice because I do not have the complete decree — is that "immediately" should have meant tomorrow, after the border posts had received their instructions. There is an implementation clause that was left out of the draft I was given.\n\nIn six hours I am going to read this to two hundred journalists.\n\nWalk west. The Humboldt Forum is three minutes away.',
    'DE': 'Die Bronzestatuen von Marx und Engels stehen hier seit 1986. Das Forum wurde als Raum für ideologisches Gedenken errichtet. Das Ergebnis ist ein ruhiger Platz an der Spree, auf dem die beiden Väter des Sozialismus mit einem Blick auf den Berliner Dom schauen — mit einem Ausdruck, den ich immer als Skepsis interpretiert habe.\n\nVor vier Wochen, während der Demonstration am 4. November, hatte jemand ein Schild an sie gehängt: "Nächstes Mal machen wir es besser." Niemand nahm es stundenlang ab.\n\nIch hole das Papier aus der Tasche und lese es hier, auf dieser Bank am Fluss.\n\nDas Dekret besagt, dass die Bürger der DDR Reisegenehmigungen ins Ausland beantragen können. Dass die Genehmigungen ohne Vorbedingungen erteilt werden. Dass die neue Regelung sofort, ohne Verzögerung in Kraft tritt.\n\nWas ich nicht bemerke — was ich nicht bemerken kann, weil ich nicht das vollständige Dekret habe — ist, dass "sofort" eigentlich morgen bedeutet haben sollte, nachdem die Grenzposten Anweisungen erhalten hätten. Es gibt eine Umsetzungsklausel, die im Entwurf, den man mir gegeben hat, fehlt.\n\nIn sechs Stunden werde ich das vor zweihundert Journalisten vorlesen.\n\nGeh nach Westen. Das Humboldt Forum ist drei Minuten entfernt.',
    'IT': 'Le statue di bronzo di Marx ed Engels sono qui dal 1986. Il foro fu costruito come spazio di commemorazione ideologica. Il risultato è una piazza tranquilla lungo la Spree, con i due padri del socialismo che guardano verso il Berliner Dom con un\'espressione che ho sempre interpretato come scetticismo.\n\nQuattro settimane fa, durante la manifestazione del 4 novembre, qualcuno aveva appeso loro un cartello: "La prossima volta lo faremo meglio." Nessuno lo tolse per ore.\n\nTiro fuori il documento dalla tasca e lo leggo qui, su questa panchina lungo il fiume.\n\nIl decreto dice che i cittadini della DDR potranno richiedere permessi di viaggio all\'estero. Che i permessi saranno concessi senza condizioni preliminari. Che la nuova regolamentazione entra in vigore immediatamente, senza ritardi.\n\nCiò che non noto — ciò che non posso notare perché non ho il decreto completo — è che "immediatamente" avrebbe dovuto significare domani, dopo che i posti di frontiera avessero ricevuto le istruzioni. C\'è una clausola di attuazione che manca dalla bozza che mi hanno consegnato.\n\nTra sei ore leggerò questo davanti a duecento giornalisti.\n\nCammina verso ovest. L\'Humboldt Forum è a tre minuti.',
  },
  'otto_04': {
    'ES': 'El Palast der Republik cerraron el año pasado por reformas. Lo que ves ahora es el solar — pronto construirán aquí el Humboldt Forum, la reconstrucción del Stadtschloss prusiano que los soviéticos volaron en 1950.\n\nBerlín tiene esa costumbre: construir el siguiente régimen encima de los cimientos del anterior. La RDA levantó su palacio de cristal sobre el palacio de los Kaiser. La República Federal levantará el palacio de los Kaiser sobre el palacio de la RDA. El suelo no cambia. Solo cambia lo que se pone encima y el nombre con que se llama.\n\nLlevo el papel en el bolsillo desde esta mañana. Lo he leído tres veces. Lo que me preocupa es una frase: "Lo anterior es válido de inmediato, sin demora." En el contexto del decreto — permisos de viaje al exterior, todos los pasos fronterizos, sin condiciones previas — esa frase puede significar esta tarde o puede significar mañana después de que los puestos fronterizos reciban instrucciones.\n\nEl decreto tenía una cláusula de implementación. No está en el borrador que me dieron. Yo no lo sé todavía.\n\nCamina hacia el sur. La Nikolaikirche está a cuatro minutos.',
    'EN': 'The Palast der Republik closed last year for renovations. What you see now is the empty plot — soon the Humboldt Forum will be built here, the reconstruction of the Prussian Stadtschloss that the Soviets blew up in 1950.\n\nBerlin has that habit: building the next regime on top of the foundations of the previous one. The GDR raised its glass palace over the Kaiser\'s palace. The Federal Republic will raise the Kaiser\'s palace over the GDR\'s palace. The ground does not change. Only what is placed on top of it changes, and the name it is given.\n\nI have had the paper in my pocket since this morning. I have read it three times. What concerns me is one sentence: "The above applies immediately, without delay." In the context of the decree — travel permits abroad, all border crossings, no prior conditions — that sentence can mean this afternoon or it can mean tomorrow after the border posts receive instructions.\n\nThe decree had an implementation clause. It is not in the draft I was given. I do not know this yet.\n\nWalk south. The Nikolaikirche is four minutes away.',
    'DE': 'Den Palast der Republik schlossen sie letztes Jahr für Renovierungen. Was du jetzt siehst, ist die Baustelle — bald werden sie hier das Humboldt Forum errichten, die Rekonstruktion des Stadtschlosses der Preußen, das die Sowjets 1950 sprengten.\n\nBerlin hat diese Gewohnheit: das nächste Regime auf den Fundamenten des vorigen zu errichten. Die DDR baute ihren Glaspalast über dem Palast der Kaiser. Die Bundesrepublik wird den Palast der Kaiser über dem Palast der DDR bauen. Der Boden ändert sich nicht. Nur was man darauf stellt und wie man es nennt.\n\nIch trage das Papier seit heute Morgen in der Tasche. Ich habe es dreimal gelesen. Was mich beunruhigt, ist ein Satz: "Das Vorstehende gilt unverzüglich, ohne Verzögerung." Im Kontext des Dekrets — Reisegenehmigungen ins Ausland, alle Grenzübergänge, keine Vorbedingungen — kann dieser Satz diesen Nachmittag bedeuten oder morgen, nachdem die Grenzposten Anweisungen erhalten haben.\n\nDas Dekret hatte eine Umsetzungsklausel. Sie ist nicht in dem Entwurf, den man mir gegeben hat. Das weiß ich noch nicht.\n\nGeh nach Süden. Die Nikolaikirche ist vier Minuten entfernt.',
    'IT': 'Il Palazzo della Repubblica l\'hanno chiuso l\'anno scorso per ristrutturazioni. Quello che vedi ora è il cantiere — presto costruiranno qui l\'Humboldt Forum, la ricostruzione dello Stadtschloss prussiano che i sovietici fecero saltare nel 1950.\n\nBerlino ha questa abitudine: costruire il regime successivo sulle fondamenta del precedente. La DDR alzò il suo palazzo di vetro sopra il palazzo dei Kaiser. La Repubblica Federale alzerà il palazzo dei Kaiser sopra il palazzo della DDR. Il suolo non cambia. Cambia solo ciò che ci si mette sopra e il nome con cui lo si chiama.\n\nPorto il documento in tasca da stamattina. L\'ho letto tre volte. Ciò che mi preoccupa è una frase: "Quanto sopra è valido immediatamente, senza ritardi." Nel contesto del decreto — permessi di viaggio all\'estero, tutti i valichi di frontiera, senza condizioni preliminari — quella frase può significare questo pomeriggio o domani dopo che i posti di frontiera ricevono le istruzioni.\n\nIl decreto aveva una clausola di attuazione. Non è nella bozza che mi hanno dato. Non lo so ancora.\n\nCammina verso sud. La Nikolaikirche è a quattro minuti.',
  },
  'otto_05': {
    'ES': 'El Nikolaiviertel es el barrio más antiguo de Berlín. La Nikolaikirche fue fundada hacia 1230 — ochocientos años mirando pasar los regímenes.\n\nLa RDA lo reconstruyó en 1987 para el 750 aniversario de la ciudad. Hormigón prefabricado disfrazado de arquitectura medieval. Si tocas las fachadas sientes el cemento bajo la piedra pintada. Una cosa que parece ser lo que no es. Construida con materiales que hacen lo que se les pide sin preguntar.\n\nVeintidós años haciendo lo que se me pide sin preguntar demasiado. Eso soy yo.\n\nMe siento en los adoquines frente a la iglesia y saco el papel por tercera vez.\n\n"Los permisos de viaje pueden ser solicitados sin condiciones previas y la salida puede producirse por todos los pasos fronterizos de la RDA hacia la RFA o hacia Berlín Occidental. Lo anterior es válido de inmediato, sin demora."\n\nDoblo el papel. Lo guardo. Son las 15:30. Tengo dos horas y media.\n\nCamina hacia el norte. El Rotes Rathaus está a dos minutos.',
    'EN': 'The Nikolaiviertel is the oldest neighbourhood in Berlin. The Nikolaikirche was founded around 1230 — eight hundred years watching regimes pass.\n\nThe GDR reconstructed it in 1987 for the city\'s 750th anniversary. Prefabricated concrete disguised as medieval architecture. If you touch the facades you feel the cement beneath the painted stone. A thing that appears to be what it is not. Built with materials that do what they are asked without questioning.\n\nTwenty-two years doing what I am asked without questioning too much. That is what I am.\n\nI sit on the cobblestones in front of the church and take out the paper for the third time.\n\n"Travel permits can be applied for without prior conditions and departure can take place through all GDR border crossings to the FRG or West Berlin. The above applies immediately, without delay."\n\nI fold the paper. I put it away. It is 15:30. I have two and a half hours.\n\nWalk north. The Rotes Rathaus is two minutes away.',
    'DE': 'Das Nikolaiviertel ist der älteste Stadtteil Berlins. Die Nikolaikirche wurde um 1230 gegründet — achthundert Jahre lang hat sie die Regime vorbeiziehen sehen.\n\nDie DDR hat es 1987 zum 750. Stadtjubiläum wiederaufgebaut. Vorgefertigter Beton, verkleidet als mittelalterliche Architektur. Wenn man die Fassaden berührt, spürt man den Zement unter dem bemalten Stein. Eine Sache, die aussieht, als wäre sie das, was sie nicht ist. Gebaut mit Materialien, die tun, was man ihnen sagt, ohne zu fragen.\n\nZweiundzwanzig Jahre lang tat ich, was man mir sagte, ohne zu viel zu fragen. Das bin ich.\n\nIch setze mich auf das Pflaster vor der Kirche und hole das Papier zum dritten Mal heraus.\n\n"Die Reisegenehmigungen können ohne Vorbedingungen beantragt werden und die Ausreise kann über alle Grenzübergänge der DDR in die BRD oder nach West-Berlin erfolgen. Das Vorstehende gilt unverzüglich, ohne Verzögerung."\n\nIch falte das Papier. Ich stecke es ein. Es ist 15:30 Uhr. Ich habe zweieinhalb Stunden.\n\nGeh nach Norden. Das Rote Rathaus ist zwei Minuten entfernt.',
    'IT': 'Il Nikolaiviertel è il quartiere più antico di Berlino. La Nikolaikirche fu fondata intorno al 1230 — ottocento anni a guardare passare i regimi.\n\nLa DDR lo ricostruì nel 1987 per il 750° anniversario della città. Cemento prefabbricato travestito da architettura medievale. Se tocchi le facciate senti il cemento sotto la pietra dipinta. Una cosa che sembra essere ciò che non è. Costruita con materiali che fanno ciò che si chiede loro senza domandare.\n\nVentidue anni a fare ciò che mi si chiede senza fare troppe domande. Questo sono io.\n\nMi siedo sui selci davanti alla chiesa e tiro fuori il documento per la terza volta.\n\n"I permessi di viaggio possono essere richiesti senza condizioni preliminari e l\'espatrio può avvenire attraverso tutti i valichi di frontiera della DDR verso la RFT o verso Berlino Ovest. Quanto sopra è valido immediatamente, senza ritardi."\n\nPiego il documento. Lo rimetto in tasca. Sono le 15:30. Ho due ore e mezza.\n\nCammina verso nord. Il Rotes Rathaus è a due minuti.',
  },
  'otto_06': {
    'ES': 'El Ayuntamiento Rojo fue construido entre 1861 y 1869. La banda de terracota que rodea el primer piso narra la historia de Berlín desde su fundación — batallas, incendios, pestes, reconstrucciones. Cada régimen añadió su interpretación. El edificio sigue igual. Las interpretaciones cambian.\n\nLos funcionarios como yo no hacemos historia. Preparamos documentos. Organizamos ruedas de prensa. Leemos comunicados en voz alta. El trabajo de mantener el Estado es, en su mayor parte, terriblemente aburrido. Que es exactamente como debe ser.\n\nSon las 16:15. La rueda de prensa empieza en menos de dos horas.\n\nAquí la historia se divide.\n\n¿Sigues al Otto que camina hacia el Tränenpalast — que pasa por el edificio de las despedidas de camino al Centro Internacional de Prensa? Camina hacia el oeste por Rathausstrasse.\n\n¿O sigues al Otto que da un rodeo hacia el sur por el Gendarmenmarkt, intentando aclarar sus ideas antes de llegar? Camina hacia el suroeste por Spandauer Strasse.',
    'EN': 'The Red Town Hall was built between 1861 and 1869. The terracotta frieze running around the first floor narrates the history of Berlin from its founding — battles, fires, plagues, reconstructions. Each regime added its interpretation. The building stays the same. The interpretations change.\n\nOfficials like me do not make history. We prepare documents. We organise press conferences. We read communiqués aloud. The work of keeping the State going is, for the most part, tremendously boring. Which is exactly how it should be.\n\nIt is 16:15. The press conference starts in less than two hours.\n\nHere the story divides.\n\nDo you follow the Otto who walks toward the Tränenpalast — who passes the building of farewells on his way to the International Press Centre? Walk west along Rathausstrasse.\n\nOr do you follow the Otto who takes a detour south through the Gendarmenmarkt, trying to clear his head before arriving? Walk southwest along Spandauer Strasse.',
    'DE': 'Das Rote Rathaus wurde zwischen 1861 und 1869 erbaut. Das Terrakottaband, das das erste Stockwerk umläuft, erzählt die Geschichte Berlins seit seiner Gründung — Schlachten, Brände, Seuchen, Wiederaufbauten. Jedes Regime fügte seine Interpretation hinzu. Das Gebäude bleibt gleich. Die Interpretationen ändern sich.\n\nFunktionäre wie ich machen keine Geschichte. Wir bereiten Dokumente vor. Wir organisieren Pressekonferenzen. Wir lesen Kommuniqués laut vor. Die Arbeit, den Staat am Laufen zu halten, ist größtenteils entsetzlich langweilig. Genau so, wie es sein soll.\n\nEs ist 16:15 Uhr. Die Pressekonferenz beginnt in weniger als zwei Stunden.\n\nHier teilt sich die Geschichte.\n\nFolgst du dem Otto, der zum Tränenpalast geht — der am Gebäude der Abschiede vorbeigeht, auf dem Weg zum Internationalen Pressezentrum? Geh nach Westen entlang der Rathausstraße.\n\nOder folgst du dem Otto, der einen Umweg über den Gendarmenmarkt macht und versucht, seine Gedanken zu ordnen, bevor er ankommt? Geh nach Südwesten über die Spandauer Straße.',
    'IT': 'Il Rotes Rathaus fu costruito tra il 1861 e il 1869. La fascia di terracotta che corre intorno al primo piano narra la storia di Berlino dalla sua fondazione — battaglie, incendi, pestilenze, ricostruzioni. Ogni regime aggiunse la propria interpretazione. L\'edificio rimane uguale. Le interpretazioni cambiano.\n\nFunzionari come me non fanno la storia. Preparano documenti. Organizzano conferenze stampa. Leggono comunicati ad alta voce. Il lavoro di mantenere lo Stato funzionante è, per la maggior parte, terribilmente noioso. Esattamente come dovrebbe essere.\n\nSono le 16:15. La conferenza stampa inizia tra meno di due ore.\n\nQui la storia si divide.\n\nSegui l\'Otto che cammina verso il Tränenpalast — che passa davanti all\'edificio dei commiati sulla strada per il Centro Stampa Internazionale? Cammina verso ovest lungo la Rathausstrasse.\n\nO segui l\'Otto che fa un giro per il Gendarmenmarkt, cercando di schiarirsi le idee prima di arrivare? Cammina verso sudovest lungo la Spandauer Strasse.',
  },
  'otto_07a': {
    'ES': 'Son las 17:20. Camino por Friedrichstrasse hacia el sur.\n\nEl Tränenpalast está a mi derecha. Me detengo un momento.\n\nLo conozco bien. He pasado por aquí cientos de veces en veintidós años. Es el pabellón de control de la estación de Friedrichstrasse — el punto donde los visitantes del Oeste tienen que volver a casa. Los ves desde fuera: gente abrazando a alguien en la puerta, sin querer soltar. Los berlineses del Oeste lo llamaron Palacio de las Lágrimas. Siempre me pareció exagerado. Era el procedimiento normal. Era como funcionaban las cosas.\n\nEsta tarde, mirándolo, pienso: si el decreto dice lo que creo que dice, este edificio va a perder su función en cuestión de horas.\n\nLas personas que ahora hacen cola para cruzar al Oeste con sus permisos y sus formularios... podrán simplemente cruzar. Sin cola. Sin formularios. Sin cara de guardia.\n\n¿Es posible? ¿Un papel que yo voy a leer dentro de cuarenta minutos puede cambiar eso?\n\nSigo caminando.\n\nEl Centro Internacional de Prensa está a tres minutos.',
    'EN': 'It is 17:20. I am walking south along Friedrichstrasse.\n\nThe Tränenpalast is on my right. I stop for a moment.\n\nI know it well. I have walked past it hundreds of times in twenty-two years. It is the control pavilion of Friedrichstrasse station — the point where Western visitors have to go home. You can see them from outside: people embracing someone at the door, not wanting to let go. West Berliners called it the Palace of Tears. It always seemed excessive to me. It was the normal procedure. It was how things worked.\n\nThis afternoon, looking at it, I think: if the decree says what I believe it says, this building is going to lose its function within hours.\n\nThe people now queuing to cross to the West with their permits and their forms... they will simply be able to cross. Without a queue. Without forms. Without a guard\'s face.\n\nIs that possible? Can a piece of paper that I am going to read in forty minutes change that?\n\nI keep walking.\n\nThe International Press Centre is three minutes away.',
    'DE': 'Es ist 17:20 Uhr. Ich gehe die Friedrichstraße nach Süden.\n\nDer Tränenpalast liegt zu meiner Rechten. Ich halte einen Moment inne.\n\nIch kenne ihn gut. Ich bin in zweiundzwanzig Jahren hunderte Male hier vorbeigegangen. Es ist der Kontrollpavillon des Bahnhofs Friedrichstraße — der Punkt, an dem die West-Besucher nach Hause müssen. Man sieht sie von draußen: Menschen, die jemanden an der Tür umarmen, ohne loslassen zu wollen. Die West-Berliner nannten ihn Palast der Tränen. Das erschien mir immer übertrieben. Es war das normale Verfahren. So funktionierten die Dinge.\n\nHeute Nachmittag, als ich ihn anschaue, denke ich: Wenn das Dekret bedeutet, was ich glaube dass es bedeutet, verliert dieses Gebäude seine Funktion in wenigen Stunden.\n\nDie Menschen, die jetzt Schlange stehen, um mit ihren Genehmigungen und Formularen in den Westen zu kommen... könnten einfach rübergehen. Ohne Schlange. Ohne Formulare. Ohne Wachgesicht.\n\nIst das möglich? Kann ein Papier, das ich in vierzig Minuten vorlesen werde, das ändern?\n\nIch gehe weiter.\n\nDas Internationale Pressezentrum ist drei Minuten entfernt.',
    'IT': 'Sono le 17:20. Cammino verso sud lungo la Friedrichstrasse.\n\nIl Tränenpalast è alla mia destra. Mi fermo un momento.\n\nLo conosco bene. Ci sono passato davanti centinaia di volte in ventidue anni. È il padiglione di controllo della stazione Friedrichstrasse — il punto dove i visitatori dell\'Ovest devono tornare a casa. Li si vede dall\'esterno: persone che abbracciano qualcuno sulla porta, senza voler lasciare andare. I berlinesi occidentali lo chiamarono Palazzo delle Lacrime. Mi sembrò sempre esagerato. Era la procedura normale. Era così che funzionavano le cose.\n\nQuesto pomeriggio, guardandolo, penso: se il decreto dice ciò che credo significhi, questo edificio perderà la sua funzione nel giro di poche ore.\n\nLe persone che ora fanno la coda per passare all\'Ovest con i loro permessi e i loro moduli... potranno semplicemente attraversare. Senza coda. Senza moduli. Senza faccia da guardia.\n\nÈ possibile? Un documento che leggerò tra quaranta minuti può cambiare tutto questo?\n\nContinuo a camminare.\n\nIl Centro Stampa Internazionale è a tre minuti.',
  },
  'otto_08a': {
    'ES': 'Son las 21:00. Salgo del Centro Internacional de Prensa.\n\nLeí el decreto. Alguien preguntó cuándo entraba en vigor. Dije: de inmediato, sin demora. Porque eso dice el papel. Otro preguntó si incluía Berlín Occidental. Dije que sí. Porque el papel dice todos los pasos fronterizos.\n\nLa sala estalló. Los periodistas corrieron a los teléfonos.\n\nCamino sin dirección y me encuentro frente al Friedrichstadtpalast. El mayor teatro de variedades del mundo, construido por la RDA en 1984 como prueba de que el socialismo también sabía entretener. Esta noche el teatro está cerrado. No hay función. Todo el mundo está en otro lugar.\n\nLa radio desde un bar abierto dice que miles de personas se han congregado en los puestos fronterizos. Que los guardias están abriendo las barreras. Que la gente está cruzando.\n\nMe quedo parado frente al teatro vacío pensando: lo que dije esta tarde no era lo que el decreto quería decir. Y sin embargo era lo que el decreto decía. Y sin embargo es lo que está pasando.\n\nLas palabras a veces son más grandes que quien las pronuncia.\n\nCamina hacia el sur. La Neue Wache está a quince minutos.',
    'EN': 'It is 21:00. I am leaving the International Press Centre.\n\nI read the decree. Someone asked when it took effect. I said: immediately, without delay. Because that is what the paper says. Another asked whether it included West Berlin. I said yes. Because the paper says all border crossings.\n\nThe room erupted. Journalists ran to the telephones.\n\nI walk without direction and find myself in front of the Friedrichstadtpalast. The largest variety theatre in the world, built by the GDR in 1984 as proof that socialism also knew how to entertain. Tonight the theatre is closed. No performance. Everyone is somewhere else.\n\nThe radio from an open bar says thousands of people have gathered at the border crossings. That the guards are opening the barriers. That people are crossing.\n\nI stand in front of the empty theatre thinking: what I said this afternoon was not what the decree intended to say. And yet it was what the decree said. And yet it is what is happening.\n\nWords are sometimes larger than the person who speaks them.\n\nWalk south. The Neue Wache is fifteen minutes away.',
    'DE': 'Es ist 21:00 Uhr. Ich verlasse das Internationale Pressezentrum.\n\nIch las das Dekret vor. Jemand fragte, wann es in Kraft trete. Ich sagte: unverzüglich, ohne Verzögerung. Weil das Papier das so sagt. Ein anderer fragte, ob es West-Berlin einschließe. Ich sagte ja. Weil das Papier alle Grenzübergänge sagt.\n\nDer Saal explodierte. Die Journalisten liefen zu den Telefonen.\n\nIch gehe ziellos und finde mich vor dem Friedrichstadtpalast. Das größte Varietétheater der Welt, 1984 von der DDR als Beweis gebaut, dass auch der Sozialismus unterhalten kann. Heute Nacht ist das Theater geschlossen. Es gibt keine Vorstellung. Alle sind woanders.\n\nDas Radio aus einer offenen Bar sagt, dass sich Tausende von Menschen an den Grenzübergängen versammelt haben. Dass die Wachen die Schranken öffnen. Dass die Menschen hinüberkommen.\n\nIch stehe vor dem leeren Theater und denke: Was ich heute Nachmittag sagte, war nicht das, was das Dekret bedeuten wollte. Und trotzdem war es das, was das Dekret sagte. Und trotzdem ist es das, was gerade passiert.\n\nWorte sind manchmal größer als der, der sie spricht.\n\nGeh nach Süden. Die Neue Wache ist fünfzehn Minuten entfernt.',
    'IT': 'Sono le 21:00. Esco dal Centro Stampa Internazionale.\n\nHo letto il decreto. Qualcuno ha chiesto quando entrava in vigore. Ho detto: immediatamente, senza ritardi. Perché questo dice il documento. Un altro ha chiesto se includeva Berlino Ovest. Ho detto di sì. Perché il documento dice tutti i valichi di frontiera.\n\nLa sala è esplosa. I giornalisti sono corsi ai telefoni.\n\nCammino senza direzione e mi ritrovo davanti al Friedrichstadtpalast. Il teatro di varietà più grande del mondo, costruito dalla DDR nel 1984 come prova che anche il socialismo sapeva intrattenere. Stanotte il teatro è chiuso. Non c\'è spettacolo. Tutti sono altrove.\n\nLa radio da un bar aperto dice che migliaia di persone si sono radunate ai valichi di frontiera. Che le guardie stanno aprendo le barriere. Che la gente sta attraversando.\n\nRimango fermo davanti al teatro vuoto pensando: ciò che ho detto questo pomeriggio non era ciò che il decreto voleva dire. Eppure era ciò che il decreto diceva. Eppure è ciò che sta succedendo.\n\nLe parole a volte sono più grandi di chi le pronuncia.\n\nCammina verso sud. La Neue Wache è a quindici minuti.',
  },
  'otto_09a': {
    'ES': 'Esta es la última parada.\n\nLa Neue Wache fue construida por Schinkel en 1818. Ha sido guardhouse prusiano, memorial de la Primera Guerra Mundial, lugar de honor nazi, memorial de la RDA a las víctimas del fascismo — con guardia de honor mientras el mismo Estado construía el Muro — y desde 1993, el Memorial Central de la República Federal a las víctimas de la guerra y la tiranía.\n\nEntro.\n\nDentro hay una sola escultura bajo una abertura circular en el techo por donde entra el cielo. Es la Madre con hijo muerto de Käthe Kollwitz — una mujer que abraza a alguien que ya no respira. Kollwitz la esculpió pensando en su hijo muerto en la Primera Guerra. Y en su nieto muerto en la Segunda. La misma madre. Dos guerras. El mismo peso.\n\nMe quedo de pie frente a ella un tiempo que no sé medir.\n\nPienso en el papel que leí esta tarde. En los miles de personas que ahora mismo están cruzando porque yo la leí tal como estaba escrita.\n\nNo soy un héroe. Soy un funcionario que no leyó entre líneas porque nadie le enseñó que debía hacerlo. Y eso fue suficiente para que la historia girara.\n\nLos sistemas no caen porque alguien los derriba. Caen cuando las palabras que los sostienen dejan de ser creídas. Esta tarde, en esa sala de prensa, las palabras correctas llegaron al momento correcto. No porque yo lo planeara. Sino porque nadie lo planeó.\n\nEl Muro sigue en pie esta noche. Pero ya no lo cree nadie.\n\nBerlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'This is the last stop.\n\nThe Neue Wache was built by Schinkel in 1818. It has been a Prussian guardhouse, a First World War memorial, a Nazi place of honour, a GDR memorial to the victims of fascism — with an honour guard while the same State built the Wall — and since 1993, the Central Memorial of the Federal Republic to the victims of war and tyranny.\n\nI go inside.\n\nInside there is a single sculpture beneath a circular opening in the roof through which the sky enters. It is Mother with Dead Son by Käthe Kollwitz — a woman embracing someone who is no longer breathing. Kollwitz sculpted it thinking of her son who died in the First World War. And of her grandson who died in the Second. The same mother. Two wars. The same weight.\n\nI stand in front of it for a length of time I cannot measure.\n\nI think about the paper I read this afternoon. About the thousands of people who are crossing right now because I read it exactly as it was written.\n\nI am not a hero. I am an official who did not read between the lines because nobody taught him that he should. And that was enough for history to turn.\n\nSystems do not fall because someone knocks them down. They fall when the words that hold them up are no longer believed. This afternoon, in that press room, the right words arrived at the right moment. Not because I planned it. But because nobody planned it.\n\nThe Wall is still standing tonight. But nobody believes in it anymore.\n\nBerlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Das ist die letzte Station.\n\nDie Neue Wache wurde 1818 von Schinkel erbaut. Sie war preußisches Wachhaus, Kriegerdenkmal des Ersten Weltkriegs, nationalsozialistischer Ehrenort, DDR-Mahnmal für die Opfer des Faschismus — mit Ehrenwache, während derselbe Staat die Mauer baute — und seit 1993 die Zentrale Gedenkstätte der Bundesrepublik für die Opfer von Krieg und Gewaltherrschaft.\n\nIch trete ein.\n\nDrinnen steht eine einzige Skulptur unter einer kreisförmigen Öffnung im Dach, durch die der Himmel hereinkommt. Es ist die Mutter mit totem Sohn von Käthe Kollwitz — eine Frau, die jemanden umarmt, der nicht mehr atmet. Kollwitz schuf sie im Gedenken an ihren im Ersten Weltkrieg gefallenen Sohn. Und an ihren im Zweiten gestorbenen Enkel. Dieselbe Mutter. Zwei Kriege. Dieselbe Last.\n\nIch stehe eine nicht messbare Zeit vor ihr.\n\nIch denke an das Papier, das ich heute Nachmittag vorlas. An die Tausenden von Menschen, die jetzt gerade hinüberkommen, weil ich es so vorlas, wie es geschrieben war.\n\nIch bin kein Held. Ich bin ein Funktionär, der nicht zwischen den Zeilen las, weil niemand ihm beigebracht hatte, das zu tun. Und das reichte, um die Geschichte zu wenden.\n\nSysteme stürzen nicht, weil jemand sie umwirft. Sie stürzen, wenn die Worte, die sie stützen, nicht mehr geglaubt werden. Heute Nachmittag, in diesem Pressesaal, kamen die richtigen Worte zum richtigen Moment. Nicht weil ich es plante. Sondern weil niemand es plante.\n\nDie Mauer steht noch heute Nacht. Aber niemand glaubt ihr mehr.\n\nBerlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Questa è l\'ultima tappa.\n\nLa Neue Wache fu costruita da Schinkel nel 1818. Fu guardiola prussiana, memoriale della Prima Guerra Mondiale, luogo d\'onore nazista, memoriale della DDR alle vittime del fascismo — con guardia d\'onore mentre lo stesso Stato costruiva il Muro — e dal 1993 il Memoriale Centrale della Repubblica Federale alle vittime della guerra e della tirannia.\n\nEntro.\n\nDentro c\'è un\'unica scultura sotto un\'apertura circolare nel tetto da cui entra il cielo. È la Madre con figlio morto di Käthe Kollwitz — una donna che abbraccia qualcuno che non respira più. Kollwitz la creò in memoria del figlio morto nella Prima Guerra Mondiale. E del nipote morto nella Seconda. La stessa madre. Due guerre. Lo stesso peso.\n\nResto in piedi davanti a lei per un tempo che non so misurare.\n\nPenso al documento che ho letto questo pomeriggio. Alle migliaia di persone che in questo momento stanno attraversando perché io l\'ho letto così com\'era scritto.\n\nNon sono un eroe. Sono un funzionario che non ha letto tra le righe perché nessuno gli aveva insegnato a farlo. E questo è bastato a far girare la storia.\n\nI sistemi non cadono perché qualcuno li abbatte. Cadono quando le parole che li sostengono smettono di essere credute. Questo pomeriggio, in quella sala stampa, le parole giuste arrivarono al momento giusto. Non perché lo pianificai. Ma perché nessuno lo pianificò.\n\nIl Muro è ancora in piedi stanotte. Ma non ci crede più nessuno.\n\nBerlino è ancora qui. E anche tu. Per ora basta così.',
  },
  'otto_07b': {
    'ES': 'Son las 17:20. Doy un rodeo por el Gendarmenmarkt antes de ir al Centro de Prensa.\n\nNecesito pensar.\n\nEl Gendarmenmarkt es la plaza más bella de Berlín. El Konzerthaus de Schinkel en el centro. El Französischer Dom y el Deutscher Dom a cada lado, gemelos de piedra mirándose desde el siglo XVIII. Todo destruido en los bombardeos. Todo reconstruido fielmente.\n\nMe siento en los escalones del Konzerthaus.\n\nEn 1685 el Edicto de Potsdam abrió las puertas de Prusia a los hugonotes que huían de Francia. Cincuenta mil personas que llegaron sin pedirlo, que transformaron la ciudad sin proponérselo. Un decreto cambió todo. Alguien lo firmó. Alguien lo leyó en voz alta. Y la ciudad se convirtió en otra cosa.\n\nEsta tarde yo voy a leer un decreto en voz alta.\n\nNo sé exactamente lo que va a pasar. Pero tengo la sensación extraña, sentado aquí, de que lo que pase va a ser más grande que el papel que lo contiene.\n\nCamina hacia el norte. La Bebelplatz está a cinco minutos.',
    'EN': 'It is 17:20. I take a detour through the Gendarmenmarkt before going to the Press Centre.\n\nI need to think.\n\nThe Gendarmenmarkt is the most beautiful square in Berlin. Schinkel\'s Konzerthaus in the centre. The Französischer Dom and the Deutscher Dom on either side, stone twins looking at each other since the 18th century. All destroyed in the bombing. All faithfully reconstructed.\n\nI sit on the steps of the Konzerthaus.\n\nIn 1685 the Edict of Potsdam opened Prussia\'s doors to the Huguenots fleeing France. Fifty thousand people who arrived without being asked for, who transformed the city without intending to. A decree changed everything. Someone signed it. Someone read it aloud. And the city became something else.\n\nThis afternoon I am going to read a decree aloud.\n\nI do not know exactly what is going to happen. But I have a strange feeling, sitting here, that whatever happens will be larger than the paper that contains it.\n\nWalk north. The Bebelplatz is five minutes away.',
    'DE': 'Es ist 17:20 Uhr. Ich mache einen Umweg über den Gendarmenmarkt, bevor ich zum Pressezentrum gehe.\n\nIch muss nachdenken.\n\nDer Gendarmenmarkt ist der schönste Platz Berlins. Das Konzerthaus von Schinkel in der Mitte. Der Französische Dom und der Deutsche Dom auf jeder Seite, steinerne Zwillinge, die sich seit dem 18. Jahrhundert anschauen. Alles bei den Bombenangriffen zerstört. Alles originalgetreu wiederaufgebaut.\n\nIch setze mich auf die Stufen des Konzerthauses.\n\n1685 öffnete das Edikt von Potsdam die Tore Preußens für die Hugenotten, die aus Frankreich flohen. Fünfzigtausend Menschen, die ungebeten kamen und die Stadt verwandelten, ohne es zu beabsichtigen. Ein Dekret änderte alles. Jemand unterschrieb es. Jemand las es laut vor. Und die Stadt wurde etwas anderes.\n\nHeute Nachmittag werde ich ein Dekret laut vorlesen.\n\nIch weiß nicht genau, was passieren wird. Aber ich habe das seltsame Gefühl, hier sitzend, dass das, was passiert, größer sein wird als das Papier, das es enthält.\n\nGeh nach Norden. Die Bebelplatz ist fünf Minuten entfernt.',
    'IT': 'Sono le 17:20. Faccio un giro per il Gendarmenmarkt prima di andare al Centro Stampa.\n\nHo bisogno di pensare.\n\nIl Gendarmenmarkt è la piazza più bella di Berlino. Il Konzerthaus di Schinkel al centro. Il Französischer Dom e il Deutscher Dom su ciascun lato, gemelli di pietra che si guardano dal XVIII secolo. Tutto distrutto dai bombardamenti. Tutto ricostruito fedelmente.\n\nMi siedo sui gradini del Konzerthaus.\n\nNel 1685 l\'Editto di Potsdam aprì le porte della Prussia agli ugonotti in fuga dalla Francia. Cinquantamila persone che arrivarono senza essere invitate e trasformarono la città senza proporsi di farlo. Un decreto cambiò tutto. Qualcuno lo firmò. Qualcuno lo lesse ad alta voce. E la città divenne qualcos\'altro.\n\nQuesto pomeriggio leggerò un decreto ad alta voce.\n\nNon so esattamente cosa succederà. Ma ho la strana sensazione, seduto qui, che ciò che accadrà sarà più grande del documento che lo contiene.\n\nCammina verso nord. La Bebelplatz è a cinque minuti.',
  },
  'otto_08b': {
    'ES': 'Son las 22:30. He vuelto aquí después de la rueda de prensa.\n\nLa Bebelplatz. El 10 de mayo de 1933, en esta plaza, ardieron veinte mil libros. Los de Freud, Marx, Remarque, Heine. Heine había escrito en 1820: donde queman libros, al final también queman personas. Sus libros ardieron aquí ciento trece años después.\n\nEsta noche no hay fuego. Hay silencio.\n\nEn el centro hay una ventana de cristal empotrada en el suelo. Debajo, una sala blanca con estantes vacíos — capacidad exacta para veinte mil libros. La instalación la hizo Micha Ullman en 1995. Una habitación con la forma exacta de lo que falta.\n\nMe quedo mirando los estantes vacíos desde arriba.\n\nLa rueda de prensa fue hace cuatro horas. Leí el decreto. Dije: de inmediato. Los periodistas corrieron. Los puestos fronterizos están abriendo. Berlín está cambiando mientras yo miro estantes vacíos en una plaza donde quemaron libros.\n\nLos huecos a veces se llenan de maneras que nadie planeó.\n\nCamina hacia el este dos minutos. La Staatsoper está ahí al lado.',
    'EN': 'It is 22:30. I have come back here after the press conference.\n\nThe Bebelplatz. On 10 May 1933, twenty thousand books burned in this square. Freud\'s, Marx\'s, Remarque\'s, Heine\'s. Heine had written in 1820: where they burn books, they will ultimately burn people too. His books burned here one hundred and thirteen years later.\n\nTonight there is no fire. There is silence.\n\nIn the centre there is a glass window set into the ground. Below it, a white room with empty shelves — the exact capacity for twenty thousand books. The installation was made by Micha Ullman in 1995. A room with the exact shape of what is missing.\n\nI stand looking at the empty shelves from above.\n\nThe press conference was four hours ago. I read the decree. I said: immediately. The journalists ran. The border crossings are opening. Berlin is changing while I look at empty shelves in a square where they burned books.\n\nGaps sometimes fill in ways nobody planned.\n\nWalk east two minutes. The Staatsoper is right next door.',
    'DE': 'Es ist 22:30 Uhr. Ich bin nach der Pressekonferenz hierher zurückgekehrt.\n\nDie Bebelplatz. Am 10. Mai 1933 brannten auf diesem Platz zwanzigtausend Bücher. Die von Freud, Marx, Remarque, Heine. Heine hatte 1820 geschrieben: Dort, wo man Bücher verbrennt, verbrennt man auch am Ende Menschen. Seine Bücher brannten hier hundertdreizehn Jahre später.\n\nHeute Nacht gibt es kein Feuer. Es gibt Stille.\n\nIn der Mitte befindet sich ein Glasfenster, das in den Boden eingelassen ist. Darunter ein weißer Raum mit leeren Regalen — genau genug Platz für zwanzigtausend Bücher. Die Installation schuf Micha Ullman 1995. Ein Zimmer in der genauen Form dessen, was fehlt.\n\nIch stehe von oben vor den leeren Regalen.\n\nDie Pressekonferenz war vor vier Stunden. Ich las das Dekret vor. Ich sagte: unverzüglich. Die Journalisten liefen los. Die Grenzübergänge öffnen. Berlin verändert sich, während ich auf leere Regale in einem Platz schaue, auf dem Bücher verbrannt wurden.\n\nLücken werden manchmal auf eine Weise gefüllt, die niemand geplant hat.\n\nGeh nach Osten, zwei Minuten. Die Staatsoper steht gleich daneben.',
    'IT': 'Sono le 22:30. Sono tornato qui dopo la conferenza stampa.\n\nLa Bebelplatz. Il 10 maggio 1933, in questa piazza, bruciarono ventimila libri. Quelli di Freud, Marx, Remarque, Heine. Heine aveva scritto nel 1820: dove si bruciano i libri, alla fine si bruciano anche le persone. I suoi libri bruciarono qui centotredici anni dopo.\n\nStanotte non c\'è fuoco. C\'è silenzio.\n\nAl centro c\'è una finestra di vetro incassata nel suolo. Sotto, una stanza bianca con scaffali vuoti — capacità esatta per ventimila libri. L\'installazione fu realizzata da Micha Ullman nel 1995. Una stanza con la forma esatta di ciò che manca.\n\nResto in piedi a guardare dall\'alto gli scaffali vuoti.\n\nLa conferenza stampa è stata quattro ore fa. Ho letto il decreto. Ho detto: immediatamente. I giornalisti sono corsi via. I valichi di frontiera si stanno aprendo. Berlino sta cambiando mentre guardo scaffali vuoti in una piazza dove bruciarono libri.\n\nI vuoti a volte si riempiono in modi che nessuno aveva pianificato.\n\nCammina verso est, due minuti. La Staatsoper è lì accanto.',
  },
  'otto_09b': {
    'ES': 'Esta es la última parada.\n\nLa Staatsoper Unter den Linden. Construida por Federico el Grande en 1742. Destruida en 1941, reconstruida por los nazis en 1942, destruida de nuevo en 1945, reconstruida por la RDA en 1955. Cada reconstrucción la devolvió al diseño original del siglo XVIII. Berlín decidió que este edificio debía parecer siempre el mismo aunque el mundo alrededor hubiera cambiado cuatro veces.\n\nEsta noche la ópera está oscura. No hay función.\n\nMe quedo parado frente a la fachada.\n\nDurante veintidós años este edificio representó para mí la continuidad de la alta cultura alemana bajo el socialismo. La RDA como heredera legítima de Beethoven y Mozart. La legitimidad que no podía comprarse con votos se compraba con palcos y temporadas de ópera.\n\nEsta noche ese argumento ha caducado. En algún puesto fronterizo de esta ciudad, en este preciso momento, alguien está cruzando hacia el Oeste por primera vez. Y lo que yo leí esta tarde fue la señal de que podía hacerlo.\n\nNo soy responsable de la caída del Muro. Soy responsable de una frase en una rueda de prensa. Las consecuencias de esa frase las escribieron cuatrocientas mil personas que decidieron que era hora.\n\nLos funcionarios ejecutan. El pueblo decide. Esa distinción, que el Estado siempre intentó invertir, esta noche quedó restaurada en su orden correcto.\n\nBerlín sigue aquí. Y tú también. Eso, por ahora, es suficiente.',
    'EN': 'This is the last stop.\n\nThe Staatsoper Unter den Linden. Built by Frederick the Great in 1742. Destroyed in 1941, rebuilt by the Nazis in 1942, destroyed again in 1945, rebuilt by the GDR in 1955. Each reconstruction returned it to the original 18th-century design. Berlin decided this building should always look the same even as the world around it changed four times.\n\nTonight the opera is dark. No performance.\n\nI stand in front of the facade.\n\nFor twenty-two years this building represented for me the continuity of high German culture under socialism. The GDR as the legitimate heir of Beethoven and Mozart. The legitimacy that could not be bought with votes was bought with boxes and opera seasons.\n\nTonight that argument has expired. At some border crossing in this city, at this precise moment, someone is crossing to the West for the first time. And what I read this afternoon was the signal that they could do it.\n\nI am not responsible for the fall of the Wall. I am responsible for a sentence at a press conference. The consequences of that sentence were written by four hundred thousand people who decided it was time.\n\nOfficials execute. The people decide. That distinction, which the State always tried to invert, has tonight been restored to its correct order.\n\nBerlin is still here. And so are you. That, for now, is enough.',
    'DE': 'Das ist die letzte Station.\n\nDie Staatsoper Unter den Linden. Von Friedrich dem Großen 1742 erbaut. 1941 zerstört, 1942 von den Nationalsozialisten wiederaufgebaut, 1945 erneut zerstört, 1955 von der DDR wiederaufgebaut. Jeder Wiederaufbau stellte das ursprüngliche Design des 18. Jahrhunderts wieder her. Berlin entschied, dass dieses Gebäude immer gleich aussehen sollte, auch wenn sich die Welt ringsum viermal verändert hatte.\n\nHeute Nacht ist die Oper dunkel. Es gibt keine Vorstellung.\n\nIch stehe vor der Fassade.\n\nZweiundzwanzig Jahre lang stand dieses Gebäude für mich für die Kontinuität der deutschen Hochkultur unter dem Sozialismus. Die DDR als rechtmäßige Erbin von Beethoven und Mozart. Die Legitimität, die man sich nicht mit Stimmen erkaufen konnte, kaufte man sich mit Logen und Opernsaisons.\n\nHeute Nacht ist dieses Argument abgelaufen. An irgendeinem Grenzübergang dieser Stadt, in diesem genauen Moment, überquert jemand zum ersten Mal den Weg nach Westen. Und was ich heute Nachmittag vorlas, war das Signal, dass er es tun konnte.\n\nIch bin nicht verantwortlich für den Fall der Mauer. Ich bin verantwortlich für einen Satz in einer Pressekonferenz. Die Konsequenzen dieses Satzes schrieben vierhunderttausend Menschen, die entschieden, dass es Zeit war.\n\nFunktionäre führen aus. Das Volk entscheidet. Diese Unterscheidung, die der Staat immer umzukehren versuchte, wurde heute Nacht in der richtigen Reihenfolge wiederhergestellt.\n\nBerlin ist noch hier. Und du auch. Das genügt vorerst.',
    'IT': 'Questa è l\'ultima tappa.\n\nLa Staatsoper Unter den Linden. Costruita da Federico il Grande nel 1742. Distrutta nel 1941, ricostruita dai nazisti nel 1942, distrutta di nuovo nel 1945, ricostruita dalla DDR nel 1955. Ogni ricostruzione la riportò al progetto originale del XVIII secolo. Berlino decise che questo edificio doveva sembrare sempre lo stesso anche se il mondo intorno era cambiato quattro volte.\n\nStanotte il teatro dell\'opera è al buio. Non c\'è spettacolo.\n\nResto fermo davanti alla facciata.\n\nPer ventidue anni questo edificio rappresentò per me la continuità dell\'alta cultura tedesca sotto il socialismo. La DDR come erede legittima di Beethoven e Mozart. La legittimità che non si poteva comprare con i voti la si comprava con i palchi e le stagioni operistiche.\n\nStanotte quell\'argomento è scaduto. A qualche valico di frontiera di questa città, in questo preciso momento, qualcuno sta attraversando verso Ovest per la prima volta. E ciò che ho letto questo pomeriggio fu il segnale che poteva farlo.\n\nNon sono responsabile della caduta del Muro. Sono responsabile di una frase in una conferenza stampa. Le conseguenze di quella frase le scrissero quattrocentomila persone che decisero che era ora.\n\nI funzionari eseguono. Il popolo decide. Quella distinzione, che lo Stato cercò sempre di invertire, stanotte fu ripristinata nell\'ordine corretto.\n\nBerlino è ancora qui. E anche tu. Per ora basta così.',
  },
};

